INSERT INTO ovh.vocabulary (id,content_key,stage,topic,en,ko,part_of_speech,example,translation,example_2,translation_2,status) VALUES
('prep-01:abandon','prep-01:abandon','prep','prep-01','abandon','버리다, 포기하다','verb','Some say hundreds of people drowned in the deluge because they would not abandon their pets.','어떤 사람들은 애완동물을 버리지 않았기 때문에 수백 명이 홍수에 빠져 익사했다고 말합니다.','The leader called on both sides to ''abandon old hatreds and meet their responsibility toward peace.''.','지도자는 양측에 ''오래된 증오를 버리고 평화를 향한 책임을 다하라''고 촉구했습니다.','published'),
('prep-01:ability','prep-01:ability','prep','prep-01','ability','능력','noun','This phone has the ability to have its software upgraded wirelessly.','이 전화기에는 소프트웨어를 무선으로 업그레이드할 수 있는 기능이 있습니다.','She has an uncanny ability to defuse conflict.','그녀는 갈등을 해소하는 놀라운 능력을 가지고 있습니다.','published'),
('prep-01:absorb','prep-01:absorb','prep','prep-01','absorb','흡수하다','verb','The liquids, light, and gases absorb.','액체, 빛, 기체가 흡수됩니다.','The situation may absorb without warning.','상황은 예고 없이 흡수될 수 있습니다.','published'),
('prep-01:abstract','prep-01:abstract','prep','prep-01','abstract','추상적인','adjective','Online racists are apt to describe their activity in the most abstract possible terms, hoping no one will look further into it.','온라인 인종차별주의자는 누구도 더 자세히 조사하지 않기를 바라면서 자신의 활동을 가장 추상적인 용어로 설명하는 경향이 있습니다.','In the laboratory there is a piece of abstract art that is composed of images of neuron networks, showing their vast complexity.','실험실에는 뉴런 네트워크의 이미지로 구성된 추상 미술 작품이 있는데, 이는 그 엄청난 복잡성을 보여줍니다.','published'),
('prep-01:academic','prep-01:academic','prep','prep-01','academic','학업의, 학문적인','adjective','I have always had an academic interest in hacking.','저는 항상 해킹에 학문적 관심을 갖고 있었습니다.','I''m more academic than athletic — I get lower marks in phys. ed. than in anything else.','나는 운동보다는 학문에 더 가깝습니다. 체육에서 낮은 점수를 받았습니다. 에드. 다른 것보다.','published'),
('prep-01:accept','prep-01:accept','prep','prep-01','accept','받아들이다','verb','I cannot accept the dogma of this church.','나는 이 교회의 교리를 받아들일 수 없습니다.','I cannot accept your invitation.','나는 당신의 초대를 받아들일 수 없습니다.','published'),
('prep-01:access','prep-01:access','prep','prep-01','access','접근, 이용 권한','noun','He took a wrong turn on the access to the bridge.','그는 다리로 가는 길에서 방향을 잘못 잡았습니다.','How do I access the dark web?','다크웹에 어떻게 접속하나요?','published'),
('prep-01:accommodate','prep-01:accommodate','prep','prep-01','accommodate','수용하다, 편의를 제공하다','verb','Can you accommodate me with a rental car?','렌트카로 저를 수용할 수 있나요?','This hotel can accommodate 250 guests.','이 호텔은 250명을 수용할 수 있습니다.','published'),
('prep-01:accomplish','prep-01:accomplish','prep','prep-01','accomplish','성취하다','verb','To accomplish a design, an object, a promise.','디자인, 목적, 약속을 달성하기 위해.','I can''t believe such a lazy man will accomplish his job!','이렇게 게으른 사람이 자기 일을 해낸다니 믿을 수가 없어요!','published'),
('prep-01:accurate','prep-01:accurate','prep','prep-01','accurate','정확한','adjective','My horoscopes I read last week were surprisingly accurate.','지난 주에 읽은 나의 운세는 놀라울 정도로 정확했습니다.','Pat will fill a critical role, leading our efforts to provide timely, accurate information to the media.','Pat은 미디어에 시기적절하고 정확한 정보를 제공하기 위한 우리의 노력을 이끄는 중요한 역할을 맡을 것입니다.','published'),
('prep-01:achieve','prep-01:achieve','prep','prep-01','achieve','성취하다','verb','Secession was the means by which the southern states hoped to achieve their goal of preserving slavery.','탈퇴는 남부 주들이 노예 제도를 보존하려는 목표를 달성하기를 희망하는 수단이었습니다.','Instead of using brain implants to achieve this, DARPA is looking for non-invasive to minutely invasive ways of interfacing with the machine.','이를 달성하기 위해 뇌 임플란트를 사용하는 대신 DARPA는 기계와 인터페이스하는 비침습적부터 미세한 침습적 방법을 찾고 있습니다.','published'),
('prep-01:acquire','prep-01:acquire','prep','prep-01','acquire','습득하다, 얻다','verb','You can''t acquire a language without consuming it.','언어를 소비하지 않고는 습득할 수 없습니다.','The students were asked to acquire something important.','학생들은 중요한 것을 얻으라는 요청을 받았습니다.','published'),
('prep-01:adapt','prep-01:adapt','prep','prep-01','adapt','적응하다, 맞추다','verb','To adapt a story for the stage.','이야기를 무대에 맞게 조정합니다.','They could not adapt to the new climate and so perished.','그들은 새로운 기후에 적응하지 못하고 멸망했습니다.','published'),
('prep-01:adequate','prep-01:adequate','prep','prep-01','adequate','충분한, 적절한','adjective','She was adequate to the job.','그녀는 그 일에 적합했습니다.','The backrest should conform to the natural curvature of your spine, and provide adequate lumbar support.','등받이는 척추의 자연스러운 곡선에 맞춰야 하며 요추를 적절하게 지지해야 합니다.','published'),
('prep-01:adjust','prep-01:adjust','prep','prep-01','adjust','조절하다, 적응하다','verb','We must adjust to the bad economic situation.','우리는 나쁜 경제 상황에 적응해야 합니다.','The team may adjust the proposal after careful review.','팀은 신중한 검토 후 제안을 조정할 수 있습니다.','published'),
('prep-01:admit','prep-01:admit','prep','prep-01','admit','인정하다, 입학을 허가하다','verb','We cannot admit non-members into our club building.','우리 클럽 건물에는 비회원이 출입할 수 없습니다.','We''ll have to vote on whether or not to admit a new member.','우리는 새로운 회원을 받아들일지 말지 투표를 해야 합니다.','published'),
('prep-01:adopt','prep-01:adopt','prep','prep-01','adopt','채택하다, 입양하다','verb','If you wouldn''t support your kid if they came out as gay, you shouldn''t adopt.','자녀가 동성애자라고 커밍아웃하더라도 지지하지 않으려면 입양해서는 안 됩니다.','The students were asked to adopt something important.','학생들은 중요한 것을 채택하도록 요청 받았습니다.','published'),
('prep-01:advantage','prep-01:advantage','prep','prep-01','advantage','이점, 유리함','noun','The experience gave him the advantage over me.','그 경험은 그에게 나보다 유리하게 작용했습니다.','It turned out to my advantage.','그것은 나에게 유리한 것으로 판명되었습니다.','published'),
('prep-01:advocate','prep-01:advocate','prep','prep-01','advocate','옹호하다; 옹호자','verb','I like trees, but I do not advocate living in them.','나는 나무를 좋아하지만 나무 속에서 사는 것을 옹호하지는 않습니다.','Torres promised to reactivate the economy, tackle the country''s security situation, advocate for those at risk and run an efficient government.','토레스는 경제를 재가동하고 국가의 안보 상황을 해결하며 위험에 처한 사람들을 옹호하고 효율적인 정부를 운영하겠다고 약속했습니다.','published'),
('prep-01:affect','prep-01:affect','prep','prep-01','affect','영향을 미치다','verb','Will the new rules affect me?','새로운 규칙이 나에게 영향을 미치나요?','He managed to affect a smile despite feeling quite miserable.','그는 매우 비참한 기분에도 불구하고 미소를 지었습니다.','published'),
('prep-02:allocate','prep-02:allocate','prep','prep-02','allocate','할당하다','verb','The school will allocate more funds to science education.','학교는 과학 교육에 더 많은 자금을 할당할 것입니다.','We need to allocate enough time for each task.','각 작업에 충분한 시간을 할당해야 합니다.','published'),
('prep-02:alternative','prep-02:alternative','prep','prep-02','alternative','대안; 대안의','noun','If alternative medicine worked, it would just be called medicine.','대체의학이 효과가 있었다면 그냥 의학이라고 부를 수 있었을 겁니다.','It once seemed like there was no alternative to monarchy, that it was just the way things were.','한때 군주제 외에는 대안이 없는 것처럼 보였고 상황이 그랬던 것 같습니다.','published'),
('prep-02:analyze','prep-02:analyze','prep','prep-02','analyze','분석하다','verb','We must analyze the risk data.','우리는 위험 데이터를 분석해야 합니다.','The students were asked to analyze something important.','학생들은 중요한 것을 분석해 달라는 요청을 받았습니다.','published'),
('prep-02:anticipate','prep-02:anticipate','prep','prep-02','anticipate','예상하다','verb','Aid organizations anticipate continued flooding will displace about 200,000 people and affect the lives of 485,000 people.','구호단체들은 지속적인 홍수로 인해 약 20만명의 이재민이 발생하고 485,000명의 삶에 영향을 미칠 것으로 예상하고 있습니다.','The team may anticipate the proposal after careful review.','팀은 신중한 검토를 거쳐 제안을 예상할 수 있습니다.','published'),
('prep-02:apparent','prep-02:apparent','prep','prep-02','apparent','분명한, 겉으로 보이는','adjective','The effects of the drought are apparent to anyone who sees the parched fields.','가뭄의 영향은 메마른 들판을 보는 사람이라면 누구나 명백히 알 수 있습니다.','For all his apparent wealth he had no money to pay the rent.','겉으로 보기에는 재산이 많아 보였지만 집세를 낼 돈이 없었습니다.','published'),
('prep-02:apply','prep-02:apply','prep','prep-02','apply','적용하다, 지원하다','verb','Apply a magnetic field here.','여기에 자기장을 적용하십시오.','I apply this rule to get good results.','나는 좋은 결과를 얻기 위해 이 규칙을 적용합니다.','published'),
('prep-02:approach','prep-02:approach','prep','prep-02','approach','접근하다; 접근법','verb','That''s a very anglonormative approach.','그것은 매우 앵글로 규범적인 접근 방식입니다.','An experimental treatment providing a new approach in the fight against HIV has cleared the first hurdle.','HIV 퇴치에 새로운 접근 방식을 제공하는 실험적 치료법이 첫 번째 장애물을 통과했습니다.','published'),
('prep-02:appropriate','prep-02:appropriate','prep','prep-02','appropriate','적절한','adjective','A funeral conducted the appropriate solemnity.','장례식은 적절한 엄숙함으로 거행되었습니다.','It seems that an apology is appropriate.','사과하는 것이 적절할 것 같습니다.','published'),
('prep-02:aspect','prep-02:aspect','prep','prep-02','aspect','측면','noun','Gambling needs to be looked at not as a personal failing, but as an aspect of an exploitative system.','도박은 개인적인 실패가 아니라 착취적인 시스템의 한 측면으로 보아야 합니다.','Addiction is not a personal failing but an aspect of an exploitative system.','중독은 개인적인 실패가 아니라 착취적인 시스템의 한 측면입니다.','published'),
('prep-02:assess','prep-02:assess','prep','prep-02','assess','평가하다','verb','Tom got out of his car to assess the damage.','Tom은 피해를 평가하기 위해 차에서 나왔습니다.','I need to assess the damage.','피해 규모를 평가해야 합니다.','published'),
('prep-02:associate','prep-02:associate','prep','prep-02','associate','연관시키다; 동료','verb','Tom was killed by a former business associate.','Tom은 전직 동료에 의해 살해되었습니다.','Tom graduated from community college with an associate degree.','Tom은 커뮤니티 칼리지를 준학사 학위로 졸업했습니다.','published'),
('prep-02:assume','prep-02:assume','prep','prep-02','assume','가정하다','verb','I assume his train was late.','나는 그의 기차가 늦었다고 생각한다.','The gods assume human or animal form in these fables.','이 우화에서 신들은 인간이나 동물의 형태를 취합니다.','published'),
('prep-02:attempt','prep-02:attempt','prep','prep-02','attempt','시도하다; 시도','verb','It is more time-efficient to do several tasks sequentially than attempt to do them simultaneously.','여러 작업을 동시에 수행하는 것보다 순차적으로 수행하는 것이 시간 효율적입니다.','Tom''s diatribe was an artless attempt at persuading the others.','톰의 비난은 다른 사람들을 설득하려는 교묘한 시도였습니다.','published'),
('prep-02:attitude','prep-02:attitude','prep','prep-02','attitude','태도','noun','He had the attitude that work was fun.','그는 일이 재미있다는 태도를 갖고 있었습니다.','He assumed an attitude of surrender.','그는 항복하는 태도를 취했습니다.','published'),
('prep-02:attribute','prep-02:attribute','prep','prep-02','attribute','~의 탓으로 돌리다; 속성','verb','It''s not fair to attribute your failure to your parents.','당신의 실패를 당신의 부모님 탓으로 돌리는것은 옳지 않습니다','Never attribute to malice that which is adequately explained by stupidity.','어리석음으로 적절하게 설명되는 것을 결코 악의로 돌리지 마십시오.','published'),
('prep-02:authority','prep-02:authority','prep','prep-02','authority','권위, 당국','noun','He has the authority to issue warrants.','그는 영장을 발부할 권한을 가지고 있습니다.','He is an authority on corporate law.','그는 기업법의 권위자입니다.','published'),
('prep-02:available','prep-02:available','prep','prep-02','available','이용 가능한','adjective','The information is available on the school website.','해당 정보는 학교 홈페이지에서 확인할 수 있다.','A quiet study room is available after class.','수업 후에는 조용한 스터디룸을 이용하실 수 있습니다.','published'),
('prep-02:aware','prep-02:aware','prep','prep-02','aware','알고 있는','adjective','Students should be aware of the deadline.','학생들은 마감일을 알고 있어야 합니다.','She became aware of a problem in the report.','그녀는 보고서에서 문제를 알게 되었습니다.','published'),
('prep-02:benefit','prep-02:benefit','prep','prep-02','benefit','이익; 이익을 주다','noun','The risks of such a project would clearly outweigh any putative benefit.','그러한 프로젝트의 위험은 추정되는 이익보다 분명히 더 클 것입니다.','People with dark hair would benefit more from laser hair removal than electrolysis.','검은 머리를 가진 사람들은 전기 제모보다 레이저 제모가 더 많은 이점을 얻을 수 있습니다.','published'),
('prep-02:bias','prep-02:bias','prep','prep-02','bias','편견, 편향','noun','Researchers must avoid bias when analyzing results.','연구자는 결과를 분석할 때 편견을 피해야 합니다.','The article showed a clear bias against the proposal.','해당 기사에서는 해당 제안에 대한 분명한 편견이 드러났습니다.','published'),
('prep-03:capacity','prep-03:capacity','prep','prep-03','capacity','능력, 수용력','noun','Among his gifts is his capacity for true altruism.','그의 재능 중에는 진정한 이타주의 능력도 있습니다.','The gas tank has a capacity of 12 gallons.','가스 탱크의 용량은 12갤런입니다.','published'),
('prep-03:category','prep-03:category','prep','prep-03','category','범주','noun','Should I pick a category, or do you want to?','카테고리를 선택해야 합니까, 아니면 선택하시겠습니까?','Each manta ray has been placed in a category depending on its unique underbelly markings.','각 쥐가오리는 고유한 하복부 표시에 따라 카테고리에 배치되어 있습니다.','published'),
('prep-03:challenge','prep-03:challenge','prep','prep-03','challenge','도전, 난제','noun','This is our biggest challenge.','이것은 우리에게 가장 큰 도전이다.','She decided to embark on a new challenge to further her career.','그녀는 자신의 경력을 더욱 발전시키기 위해 새로운 도전을 시작하기로 결정했습니다.','published'),
('prep-03:circumstance','prep-03:circumstance','prep','prep-03','circumstance','상황, 환경','noun','Under this circumstance, delaying the trip is sensible.','이러한 상황에서는 여행을 연기하는 것이 합리적입니다.','A person''s choice often depends on the circumstance.','사람의 선택은 종종 상황에 따라 달라집니다.','published'),
('prep-03:claim','prep-03:claim','prep','prep-03','claim','주장하다; 주장','verb','The claim that nonbinary people do not have gender dysphoria is dated and runs contrary to current medical standards.','논바이너리 사람들이 성별위화감을 느끼지 않는다는 주장은 시대에 뒤떨어진 것이며 현재의 의료 기준에 어긋납니다.','How sick do you have to be to claim that unarmed protesters were trying to get shot?','비무장 시위대가 총에 맞으려고 했다고 주장하려면 얼마나 속상해야 할까요?','published'),
('prep-03:coherent','prep-03:coherent','prep','prep-03','coherent','일관성 있는','adjective','She was more coherent than she had been just after the accident.','그녀는 사고 직후보다 더 일관성이 있었습니다.','The final decision seemed coherent to everyone involved.','최종 결정은 관련된 모든 사람에게 일관된 것처럼 보였습니다.','published'),
('prep-03:compensate','prep-03:compensate','prep','prep-03','compensate','보상하다','verb','It is hard work, but they will compensate you well for it.','힘든 일이지만 그에 대해 충분한 보상을 해 줄 것입니다.','His loud voice cannot compensate for a lack of personality.','그의 큰 목소리는 개성의 부족을 보완할 수 없습니다.','published'),
('prep-03:compete','prep-03:compete','prep','prep-03','compete','경쟁하다','verb','Rabbits, another invasive species, also compete with the marsupials for food and shelter.','또 다른 침입종인 토끼도 먹이와 은신처를 놓고 유대류와 경쟁합니다.','If it''s unfair for trans women to compete in women''s sports, how come trans women aren''t dominating in any sport?','트랜스 여성이 여성 스포츠에서 경쟁하는 것이 불공평하다면 왜 트랜스 여성이 어떤 스포츠에서도 지배하지 못하는 걸까요?','published'),
('prep-03:complex','prep-03:complex','prep','prep-03','complex','복잡한','adjective','A complex set of variations based on a simple folk melody.','단순한 민요 선율을 기반으로 한 복잡한 변주 세트입니다.','Tom''s explanation was too complex.','톰은 너무 복잡하게 설명해.','published'),
('prep-03:comprehensive','prep-03:comprehensive','prep','prep-03','comprehensive','포괄적인','adjective','When there are diametrically opposing views on a big issue that concerns millions of people, doing comprehensive research just makes sense.','수백만 명의 사람들이 관심을 갖는 큰 문제에 대해 정반대의 견해가 있을 때 포괄적인 연구를 수행하는 것이 합리적입니다.','The reviewers considered the final result comprehensive.','검토자들은 최종 결과가 포괄적이라고 생각했습니다.','published'),
('prep-03:comprise','prep-03:comprise','prep','prep-03','comprise','구성하다','verb','These few men comprise his entire army.','이 소수의 사람들이 그의 군대 전체를 구성합니다.','The new policy may comprise the final outcome.','새로운 정책은 최종 결과를 구성할 수 있습니다.','published'),
('prep-03:concentrate','prep-03:concentrate','prep','prep-03','concentrate','집중하다','verb','These groups concentrate in the inner cities.','이 그룹은 도심에 집중되어 있습니다.','To concentrate rays of light into a focus.','광선을 한 초점으로 집중시키다.','published'),
('prep-03:concept','prep-03:concept','prep','prep-03','concept','개념','noun','I made the concept of an NFT into an NFT.','NFT의 개념을 NFT로 만들었습니다.','I don''t think she fully grasped the concept.','나는 그녀가 개념을 완전히 이해했다고 생각하지 않습니다.','published'),
('prep-03:concern','prep-03:concern','prep','prep-03','concern','걱정, 관심; 관련되다','noun','The safety of the ship is the captain''s concern.','배의 안전은 선장의 관심사입니다.','She felt strong concern for those less fortunate.','그녀는 불우한 사람들에 대한 강한 관심을 느꼈습니다.','published'),
('prep-03:conclude','prep-03:conclude','prep','prep-03','conclude','결론짓다','verb','The researchers conclude that more evidence is needed.','연구자들은 더 많은 증거가 필요하다고 결론지었습니다.','We can conclude from the data that sales increased.','데이터를 보면 매출이 증가했다는 결론을 내릴 수 있습니다.','published'),
('prep-03:conduct','prep-03:conduct','prep','prep-03','conduct','수행하다; 행동','verb','You cannot conduct business like this.','이런 식으로 사업을 할 수는 없습니다.','All gods are better than their conduct.','모든 신은 그들의 행위보다 낫습니다.','published'),
('prep-03:confirm','prep-03:confirm','prep','prep-03','confirm','확인하다','verb','Tom can neither confirm nor deny any of the claims made about him.','Tom은 자신에 대한 어떤 주장도 확인하거나 거부할 수 없습니다.','I just need to ask you a few questions to confirm you''re not a robot.','당신이 로봇이 아닌지 확인하기 위해 몇 가지 질문만 하면 됩니다.','published'),
('prep-03:consequence','prep-03:consequence','prep','prep-03','consequence','결과','noun','Decisions of great consequence are made by the president himself.','중대한 결정은 대통령이 직접 내린다.','That result is of no consequence.','그 결과는 아무런 의미가 없습니다.','published'),
('prep-03:consider','prep-03:consider','prep','prep-03','consider','고려하다','verb','I consider her to be shallow.','나는 그녀가 천박하다고 생각합니다.','Consider the possibility of moving.','이동 가능성을 고려하십시오.','published'),
('prep-03:constant','prep-03:constant','prep','prep-03','constant','끊임없는, 일정한','adjective','Tom lives in constant fear of a cataclysm.','톰은 대격변에 대한 끊임없는 두려움 속에 살고 있습니다.','The worst kind of man is the kind who keeps his wife under constant surveillance while having affairs himself.','가장 나쁜 남자는 자신은 불륜을 저지르면서도 아내를 끊임없이 감시하는 남자다.','published'),
('prep-04:consume','prep-04:consume','prep','prep-04','consume','소비하다','verb','Baby birds consume their own weight in food each day.','아기 새들은 매일 자신의 체중만큼 음식을 섭취합니다.','Brains consume 25% of the body''s energy.','뇌는 신체 에너지 중 25%를 소비해.','published'),
('prep-04:contain','prep-04:contain','prep','prep-04','contain','포함하다','verb','I''m so excited, I can hardly contain myself!','너무 신나서 참을 수가 없어요!','Oranges contain a lot of vitamin C.','오렌지는 많은 비타민C를 함유하고 있다.','published'),
('prep-04:context','prep-04:context','prep','prep-04','context','맥락, 문맥','noun','Without any context, I can''t tell you if the "dish" refers to the food, or the thing you eat it on.','아무런 맥락 없이는 "접시"가 음식을 가리키는지 아니면 먹는 음식을 가리키는지 알 수 없습니다.','That depends on the context.','문맥에 따라 달렸다.','published'),
('prep-04:contrast','prep-04:contrast','prep','prep-04','contrast','대조하다; 대조','verb','In contrast with many of his contemporaries, he’s not brash and boastful.','많은 동시대 사람들과 달리 그는 뻔뻔하거나 자랑하지 않습니다.','The students were asked to contrast something important.','학생들은 중요한 것을 대조하도록 요청 받았습니다.','published'),
('prep-04:contribute','prep-04:contribute','prep','prep-04','contribute','기여하다','verb','I want to contribute to a charitable cause.','나는 자선 활동에 기여하고 싶습니다.','Doing things, however minor those things are, helps contribute to peace of mind.','아무리 사소한 일이라도 하는 것은 마음의 평화에 도움이 됩니다.','published'),
('prep-04:conventional','prep-04:conventional','prep','prep-04','conventional','전통적인, 관습적인','adjective','She had strayed from the path of conventional behavior.','그녀는 전통적인 행동의 길에서 벗어났습니다.','Conventional wisdom is that this will work; however, it won''t.','일반적인 통념은 이것이 효과가 있을 것이라는 것입니다. 그러나 그렇지 않습니다.','published'),
('prep-04:convert','prep-04:convert','prep','prep-04','convert','전환하다','verb','Could you convert my dollars into pounds?','내 달러를 파운드로 바꿔 주실 수 있나요?','How do you convert feet into metres?','피트를 미터로 어떻게 변환하나요?','published'),
('prep-04:convince','prep-04:convince','prep','prep-04','convince','확신시키다','verb','Tom''s arguments didn''t convince us.','Tom의 주장은 우리를 설득하지 못했습니다.','I know what I saw and you can''t convince me otherwise.','나는 내가 본 것을 알고 있으며 다른 방법으로는 나를 설득할 수 없습니다.','published'),
('prep-04:correspond','prep-04:correspond','prep','prep-04','correspond','일치하다, 서신을 주고받다','verb','The numbers in the chart correspond to each region.','차트의 숫자는 각 지역에 해당합니다.','The two friends correspond by email every week.','두 친구는 매주 이메일로 연락을 주고받는다.','published'),
('prep-04:criteria','prep-04:criteria','prep','prep-04','criteria','기준들','noun','The judges explained the criteria for selecting a winner.','심사위원들은 수상작 선정 기준을 설명했다.','Safety and cost are important criteria in our decision.','안전과 비용은 우리의 결정에 있어 중요한 기준입니다.','published'),
('prep-04:critical','prep-04:critical','prep','prep-04','critical','비판적인, 매우 중요한','adjective','A critical temperature of water is 100 degrees C--its boiling point at standard atmospheric pressure.','물의 임계 온도는 섭씨 100도, 즉 표준 대기압에서 끓는점입니다.','A good teacher is fair but critical.','좋은 선생님은 공정하지만 비판적입니다.','published'),
('prep-04:crucial','prep-04:crucial','prep','prep-04','crucial','결정적인, 매우 중요한','adjective','That is crucial to revive not just the river, but also the banks or “ghats” in pilgrim towns where visitors throng.','이는 강뿐만 아니라 방문객이 붐비는 순례자 마을의 제방이나 ''가트''도 살리는 데 중요합니다.','Scientists have discovered that a protein that plays a crucial role in healing broken bones is not fully functional in diabetics.','과학자들은 부러진 뼈를 치료하는 데 중요한 역할을 하는 단백질이 당뇨병 환자에게는 제대로 기능하지 않는다는 사실을 발견했습니다.','published'),
('prep-04:decline','prep-04:decline','prep','prep-04','decline','감소하다, 거절하다','verb','On reflection I think I will decline your generous offer.','생각해 보면 나는 당신의 관대한 제안을 거절할 것 같습니다.','The team chose to decline the fifteen-yard penalty because their receiver had caught the ball for a thirty-yard gain.','팀은 리시버가 30야드 이득을 위해 공을 잡았기 때문에 15야드 페널티를 거부하기로 결정했습니다.','published'),
('prep-04:deduce','prep-04:deduce','prep','prep-04','deduce','추론하다','verb','To deduce a part from the whole.','전체에서 일부를 추론합니다.','The report could deduce that the estimate was wrong.','보고서에서는 추정치가 잘못되었다고 추론할 수 있었습니다.','published'),
('prep-04:define','prep-04:define','prep','prep-04','define','정의하다','verb','The camera could define the smallest object.','카메라는 가장 작은 물체를 정의할 수 있습니다.','I define myself as a techno-anarchist.','나는 나 자신을 기술 무정부주의자라고 정의합니다.','published'),
('prep-04:demonstrate','prep-04:demonstrate','prep','prep-04','demonstrate','입증하다, 보여주다','verb','Can you demonstrate the new tools for us?','새로운 도구를 보여주실 수 있나요?','Allow me to demonstrate my invention to you.','내 발명품 시연하게 해주라.','published'),
('prep-04:deny','prep-04:deny','prep','prep-04','deny','부인하다','verb','It''s a fact you can''t deny.','네가 부정하지 못할 사실이다.','It''s not fair to deny me of the cross-eyed bear that you gave to me.','당신이 나에게 준 사시 곰을 거부하는 것은 불공평합니다.','published'),
('prep-04:derive','prep-04:derive','prep','prep-04','derive','얻다, 유래하다','verb','Many English words derive from Latin roots.','많은 영어 단어는 라틴어 뿌리에서 파생됩니다.','Plants derive energy from sunlight through photosynthesis.','식물은 광합성을 통해 햇빛으로부터 에너지를 얻습니다.','published'),
('prep-04:detect','prep-04:detect','prep','prep-04','detect','발견하다, 감지하다','verb','The high-pitched whine of a mosquito is annoying, but scientists have developed an app that uses that sound to detect dangerous mosquitoes.','모기의 높은 윙윙거리는 소리는 짜증나는 소리지만, 과학자들은 그 소리를 이용해 위험한 모기를 탐지하는 앱을 개발했습니다.','I can detect that there are other dimensions parallel to this one.','나는 이 차원과 평행한 다른 차원이 있다는 것을 감지할 수 있습니다.','published'),
('prep-04:determine','prep-04:determine','prep','prep-04','determine','결정하다, 알아내다','verb','They want to determine whether there were any unreported malfunctions and whether or not all test objectives were met.','그들은 보고되지 않은 오작동이 있었는지, 그리고 모든 테스트 목표가 충족되었는지 여부를 확인하려고 합니다.','The students were asked to determine something important.','학생들은 중요한 것을 결정하도록 요청 받았습니다.','published'),
('prep-05:deviate','prep-05:deviate','prep','prep-05','deviate','벗어나다','verb','Do not deviate from the approved safety procedure.','승인된 안전 절차를 벗어나지 마십시오.','The results may deviate slightly from the original estimate.','결과는 원래 추정치와 약간 다를 수 있습니다.','published'),
('prep-05:dimension','prep-05:dimension','prep','prep-05','dimension','차원, 측면','noun','The dimension of velocity is length divided by time.','속도의 차원은 길이를 시간으로 나눈 값입니다.','Voice recognition technologies bring a human dimension to our devices, but developers need an enormous amount of voice data to build them.','음성 인식 기술은 우리 장치에 인간적인 차원을 더해 주지만 개발자는 이를 구축하기 위해 엄청난 양의 음성 데이터가 필요합니다.','published'),
('prep-05:distinguish','prep-05:distinguish','prep','prep-05','distinguish','구별하다','verb','We distinguish several kinds of maple.','우리는 여러 종류의 단풍나무를 구별합니다.','Philosophers distinguish between a priori and a posteriori knowledge.','철학자들은 선험적 지식과 사후적 지식을 구별합니다.','published'),
('prep-05:distribute','prep-05:distribute','prep','prep-05','distribute','분배하다','verb','Volunteers distribute meals to families every weekend.','자원봉사자들은 주말마다 가족들에게 식사를 나눠줍니다.','The teacher will distribute the worksheets before class.','교사는 수업 전에 워크시트를 배포할 것입니다.','published'),
('prep-05:diverse','prep-05:diverse','prep','prep-05','diverse','다양한','adjective','All in all, the southeast sector offers a very diverse avifauna, and it should not be ignored by the visiting birder.','전체적으로 남동부 지역은 매우 다양한 조류상을 제공하므로 방문하는 조류 관찰자가 이를 무시해서는 안 됩니다.','Bangladesh is a diverse country with a rich culture and history.','방글라데시는 풍부한 문화와 역사를 지닌 다양한 국가입니다.','published'),
('prep-05:dominate','prep-05:dominate','prep','prep-05','dominate','지배하다','verb','One large tree seemed to dominate the landscape.','커다란 나무 한 그루가 풍경을 지배하는 것 같았습니다.','A single topic should not dominate the entire discussion.','하나의 주제가 전체 토론을 지배해서는 안 됩니다.','published'),
('prep-05:efficient','prep-05:efficient','prep','prep-05','efficient','효율적인','adjective','The price of jet fuel is one reason aviation technology research is so often focused on making planes lighter and more efficient.','제트 연료의 가격은 항공 기술 연구가 비행기를 더 가볍고 효율적으로 만드는 데 집중되는 이유 중 하나입니다.','Torres promised to reactivate the economy, tackle the country''s security situation, advocate for those at risk and run an efficient government.','토레스는 경제를 재가동하고 국가의 안보 상황을 해결하며 위험에 처한 사람들을 옹호하고 효율적인 정부를 운영하겠다고 약속했습니다.','published'),
('prep-05:eliminate','prep-05:eliminate','prep','prep-05','eliminate','제거하다','verb','Attempting to eliminate gay and trans people is a fundamentally flawed goal, as we will keep being born no matter what.','동성애자와 트랜스젠더를 제거하려는 시도는 근본적으로 결함이 있는 목표입니다. 우리는 무슨 일이 있어도 계속해서 태어날 것이기 때문입니다.','The right is attempting to eliminate trans people, but this is impossible, because trans people will always continue to be born.','우파는 트랜스젠더를 제거하려고 시도하지만 이는 불가능합니다. 트랜스젠더는 언제나 계속해서 탄생할 것이기 때문입니다.','published'),
('prep-05:emerge','prep-05:emerge','prep','prep-05','emerge','나타나다','verb','He felt new emotions emerge.','그는 새로운 감정이 솟아오르는 것을 느꼈다.','Not until dawn did the truth emerge.','새벽이 되어서야 진실이 드러났습니다.','published'),
('prep-05:emphasize','prep-05:emphasize','prep','prep-05','emphasize','강조하다','verb','The teacher used an example to emphasize the main point.','교사는 요점을 강조하기 위해 예를 사용했습니다.','The report will emphasize the need for immediate action.','보고서는 즉각적인 조치의 필요성을 강조할 것입니다.','published'),
('prep-05:enable','prep-05:enable','prep','prep-05','enable','가능하게 하다','verb','The scholarship will enable her to continue studying.','장학금 덕분에 그녀는 계속 공부할 수 있게 되었습니다.','New tools enable students to analyze data quickly.','새로운 도구를 사용하면 학생들이 데이터를 빠르게 분석할 수 있습니다.','published'),
('prep-05:encounter','prep-05:encounter','prep','prep-05','encounter','마주치다; 만남','verb','Tom recognized me from a single encounter at a party three years ago.','톰은 3년 전 파티에서 한 번 만났을 때 나를 알아보았습니다.','Anyone you encounter may be traumatized.','만나는 사람마다 트라우마를 겪을 수 있습니다.','published'),
('prep-05:enhance','prep-05:enhance','prep','prep-05','enhance','향상시키다','verb','This will enhance your enjoyment.','이것은 당신의 즐거움을 향상시킬 것입니다.','This sauce will enhance the flavor of the meat.','이 소스는 고기의 맛을 한층 더 높여줄 것이다.','published'),
('prep-05:ensure','prep-05:ensure','prep','prep-05','ensure','확실하게 하다','verb','This nest egg will ensure a nice retirement for us.','이 둥지 알은 우리에게 좋은 은퇴를 보장해 줄 것입니다.','Republicans have been implementing ways to ensure undemocratic minority rule, because their core demographic is shrinking.','공화당은 핵심 인구가 줄어들고 있기 때문에 비민주적인 소수 지배를 보장하는 방법을 시행해 왔습니다.','published'),
('prep-05:equivalent','prep-05:equivalent','prep','prep-05','equivalent','동등한; 동등한 것','adjective','A wish that was equivalent to a command.','명령과도 같은 소원.','When a cat or dog licks you, it''s their equivalent of petting you.','고양이나 개가 당신을 핥는 것은 당신을 쓰다듬는 것과 같습니다.','published'),
('prep-05:establish','prep-05:establish','prep','prep-05','establish','확립하다, 설립하다','verb','They have to establish communications first, get radio techs out there and get repeater sites set up.','먼저 통신을 구축하고, 무선 기술자를 파견하고, 중계기 사이트를 설치해야 합니다.','Will they establish new trade routes soon?','곧 새로운 무역로를 개척하게 될까요?','published'),
('prep-05:estimate','prep-05:estimate','prep','prep-05','estimate','추정하다; 추정','verb','I estimate this chicken to weigh three pounds.','내 생각에 이 닭의 무게는 3파운드 정도 될 것 같아요.','The inertial measurement unit contains accelerometers, which—just like the accelerometers within the inclinometer—can be used to estimate the initial attitude.','관성 측정 장치에는 경사계 내의 가속도계와 마찬가지로 초기 자세를 추정하는 데 사용할 수 있는 가속도계가 포함되어 있습니다.','published'),
('prep-05:ethical','prep-05:ethical','prep','prep-05','ethical','윤리적인','adjective','Ours is a world of nuclear giants and ethical infants.','우리의 세계는 핵 거인과 윤리적인 유아들의 세계입니다.','It seems ethical and right.','윤리적이고 옳은 것 같습니다.','published'),
('prep-05:evaluate','prep-05:evaluate','prep','prep-05','evaluate','평가하다','verb','How do you evaluate this grant proposal?','이 보조금 제안을 어떻게 평가하시나요?','L''Hôpital''s rule uses derivatives to help evaluate limits involving indeterminate forms.','로피탈의 법칙은 미분을 사용하여 불확정 형태와 관련된 극한을 평가하는 데 도움을 줍니다.','published'),
('prep-05:evidence','prep-05:evidence','prep','prep-05','evidence','증거','noun','The evidence that smoking causes lung cancer is very compelling.','흡연이 폐암을 유발한다는 증거는 매우 설득력이 있습니다.','His trembling was evidence of his fear.','그의 떨림은 그의 두려움의 증거였습니다.','published'),
('prep-06:evolve','prep-06:evolve','prep','prep-06','evolve','진화하다, 발전하다','verb','What is consciousness and why did it evolve?','의식이란 무엇이며 왜 진화했는가?','The team may evolve the proposal after careful review.','팀은 신중한 검토 후 제안을 발전시킬 수 있습니다.','published'),
('prep-06:exceed','prep-06:exceed','prep','prep-06','exceed','초과하다','verb','Your password cannot exceed eight characters.','비밀번호는 8자를 초과할 수 없습니다.','A small change could exceed the entire process.','작은 변화가 전체 프로세스를 초과할 수 있습니다.','published'),
('prep-06:exception','prep-06:exception','prep','prep-06','exception','예외','noun','With the exception of the children, everyone was told the news.','아이들을 제외하고 모두가 그 소식을 들었습니다.','All her children were brilliant; the only exception was her last child.','그녀의 아이들은 모두 훌륭했습니다. 유일한 예외는 그녀의 마지막 아이였습니다.','published'),
('prep-06:exclude','prep-06:exclude','prep','prep-06','exclude','제외하다','verb','To exclude young animals from the womb or from eggs.','어린 동물을 자궁이나 알에서 제외하는 것입니다.','Count from 1 to 30, but exclude the prime numbers.','1부터 30까지 세되 소수는 제외하세요.','published'),
('prep-06:expand','prep-06:expand','prep','prep-06','expand','확대하다','verb','Expand the house by adding another wing.','또 다른 날개를 추가하여 집을 확장하세요.','You can expand this compact umbrella to cover a large table.','이 컴팩트한 우산을 펼치면 큰 테이블까지 덮을 수 있습니다.','published'),
('prep-06:expect','prep-06:expect','prep','prep-06','expect','예상하다, 기대하다','verb','I expect my students to arrive in time for their lessons.','나는 학생들이 수업 시간에 맞춰 도착하기를 기대합니다.','I expect you to wait.','네가 기다리고 있길 기대하고 있어.','published'),
('prep-06:explicit','prep-06:explicit','prep','prep-06','explicit','명백한, 명시적인','adjective','She made her wishes explicit.','그녀는 자신의 소망을 분명히 밝혔습니다.','Most drag shows are not sexually explicit.','대부분의 드래그 쇼는 성적으로 노골적이지 않습니다.','published'),
('prep-06:expose','prep-06:expose','prep','prep-06','expose','노출시키다','verb','Expose your students to art.','학생들을 예술에 노출시키세요.','Expose the blanket to sunshine.','담요를 햇빛에 노출시키세요.','published'),
('prep-06:facilitate','prep-06:facilitate','prep','prep-06','facilitate','촉진하다, 용이하게 하다','verb','You could facilitate the process by sharing your knowledge.','지식을 공유함으로써 프로세스를 촉진할 수 있습니다.','The team may facilitate the proposal after careful review.','팀은 신중한 검토를 거쳐 제안을 용이하게 진행할 수 있습니다.','published'),
('prep-06:factor','prep-06:factor','prep','prep-06','factor','요인','noun','The factor of the trading post bought the furs.','교역소의 요인이 모피를 구입했습니다.','The economy was a factor in this year''s budget figures.','경제는 올해 예산 수치의 한 요소였습니다.','published'),
('prep-06:feature','prep-06:feature','prep','prep-06','feature','특징; 특징으로 삼다','noun','They ran a feature on retirement planning.','그들은 은퇴 계획에 관한 기능을 실행했습니다.','The photo editor includes a feature which allows users to add a blur effect to images.','사진 편집기에는 사용자가 이미지에 흐림 효과를 추가할 수 있는 기능이 포함되어 있습니다.','published'),
('prep-06:flexible','prep-06:flexible','prep','prep-06','flexible','융통성 있는','adjective','Is the future predetermined or flexible?','미래는 미리 결정된 것인가, 아니면 유연한 것인가?','The reviewers considered the final result flexible.','검토자는 최종 결과가 유연하다고 생각했습니다.','published'),
('prep-06:fluctuate','prep-06:fluctuate','prep','prep-06','fluctuate','변동하다','verb','Variegated leaves fluctuate between green and white, or green and yellow, and display these colors in nearly all possible patterns.','잡색의 잎은 녹색과 흰색, 녹색과 노란색 사이를 오가며 거의 모든 가능한 패턴으로 이러한 색상을 표시합니다.','A small change could fluctuate the entire process.','작은 변화로 인해 전체 프로세스가 달라질 수 있습니다.','published'),
('prep-06:focus','prep-06:focus','prep','prep-06','focus','집중하다; 초점','verb','Please focus on your studies and not on your hobbies.','취미보다는 공부에 집중하시기 바랍니다.','Please focus the image; we cannot enjoy the movie.','이미지의 초점을 맞추세요. 우리는 영화를 즐길 수 없습니다.','published'),
('prep-06:formulate','prep-06:formulate','prep','prep-06','formulate','공식화하다, 만들어내다','verb','The team met to formulate a practical solution.','팀은 실용적인 솔루션을 공식화하기 위해 만났습니다.','Scientists formulate a hypothesis before testing it.','과학자들은 테스트하기 전에 가설을 세웁니다.','published'),
('prep-06:function','prep-06:function','prep','prep-06','function','기능; 기능하다','noun','The function of an auger is to bore holes.','오거의 기능은 구멍을 뚫는 것입니다.','Height is a function of age.','키는 나이의 함수입니다.','published'),
('prep-06:fundamental','prep-06:fundamental','prep','prep-06','fundamental','근본적인, 필수적인','adjective','An example that was fundamental to the argument.','논쟁의 기본이 되는 예.','Computers are fundamental to modern industrial structure.','컴퓨터는 현대 산업 구조의 기본입니다.','published'),
('prep-06:generate','prep-06:generate','prep','prep-06','generate','발생시키다, 만들어내다','verb','We can''t generate enough power for the entire city.','우리는 도시 전체에 충분한 전력을 생산할 수 없습니다.','The hydroelectric plant needs to generate more electricity.','수력 발전소는 더 많은 전기를 생산해야 합니다.','published'),
('prep-06:hypothesis','prep-06:hypothesis','prep','prep-06','hypothesis','가설','noun','A scientific hypothesis that survives experimental testing becomes a scientific theory.','실험적 테스트를 거쳐 살아남은 과학적 가설은 과학적인 이론이 됩니다.','I think your hypothesis is correct.','네 가설이 맞는 것 같아.','published'),
('prep-06:identify','prep-06:identify','prep','prep-06','identify','확인하다, 식별하다','verb','Can you identify the man who did this to you?','당신에게 이런 짓을 한 사람이 누구인지 알 수 있나요?','Could you identify him in a lineup?','라인업에서 그 사람을 알아볼 수 있나요?','published'),
('prep-07:ignore','prep-07:ignore','prep','prep-07','ignore','무시하다','verb','People who ignore history tend to repeat it.','역사를 무시하는 사람들은 역사를 되풀이하게 된다.','Calls for a peaceful solution often ignore the everyday violence that led to the conflict in question.','평화로운 해결책을 요구하면 문제의 갈등을 초래한 일상적인 폭력을 무시하는 경우가 많습니다.','published'),
('prep-07:illustrate','prep-07:illustrate','prep','prep-07','illustrate','설명하다, 예시하다','verb','Illustrate a book with drawings.','그림으로 책을 그려보세요.','The team may illustrate the proposal after careful review.','팀은 주의 깊게 검토한 후 제안을 설명할 수 있습니다.','published'),
('prep-07:impact','prep-07:impact','prep','prep-07','impact','영향; 영향을 주다','noun','The book had an important impact on my thinking.','그 책은 내 생각에 중요한 영향을 미쳤다.','And while many are feeling the impact of that slowdown, the region''s growing middle class is helping to act as a buffer.','그리고 많은 사람들이 경기 둔화의 영향을 느끼고 있는 반면, 지역의 성장하는 중산층은 완충 역할을 하고 있습니다.','published'),
('prep-07:implement','prep-07:implement','prep','prep-07','implement','시행하다','verb','The idea is very interesting, but I''m worried about how we are going to implement it.','아이디어는 매우 흥미롭지만, 이를 어떻게 구현해낼지 걱정이 됩니다.','He added that it behooves both the sub-regional group and its member states to implement the agreed measures to combat the famine.','그는 기근 퇴치를 위해 합의된 조치를 이행하는 것이 소지역 그룹과 회원국 모두의 의무라고 덧붙였습니다.','published'),
('prep-07:imply','prep-07:imply','prep','prep-07','imply','암시하다','verb','Being LGBT theoretically does not imply a political affiliation, but when a party is promising to destroy your life, believe them.','이론적으로 LGBT가 된다는 것은 정치적 성향을 의미하지는 않지만, 정당이 당신의 삶을 파괴하겠다고 약속한다면 그 말을 믿으세요.','The team may imply the proposal after careful review.','팀은 신중한 검토 후 제안을 암시할 수 있습니다.','published'),
('prep-07:incentive','prep-07:incentive','prep','prep-07','incentive','동기, 장려책','noun','That''s not much of an incentive.','그다지 인센티브가 되지는 않습니다.','The incentive encouraged them to continue.','인센티브는 그들이 계속하도록 격려했습니다.','published'),
('prep-07:indicate','prep-07:indicate','prep','prep-07','indicate','나타내다','verb','These symptoms indicate a serious illness.','이러한 증상은 심각한 질병을 나타냅니다.','The results indicate the need for more work.','결과는 더 많은 작업이 필요함을 나타냅니다.','published'),
('prep-07:individual','prep-07:individual','prep','prep-07','individual','개인; 개인의','noun','The common interests of the many should outweigh the individual interest of the few.','다수의 공동 이익이 소수의 개인 이익보다 중요해야 합니다.','People can believe whatever they want as long they don’t infringe upon anyone’s individual freedom.','개인의 자유를 침해하지 않는 한 사람들은 무엇이든 믿을 수 있습니다.','published'),
('prep-07:inevitable','prep-07:inevitable','prep','prep-07','inevitable','불가피한','adjective','It was inevitable, wasn''t it?','어쩔 수 없었지 않니?','I think we''re just prolonging the inevitable.','나는 우리가 피할 수 없는 일을 연장하고 있다고 생각합니다.','published'),
('prep-07:infer','prep-07:infer','prep','prep-07','infer','추론하다','verb','Telescopes are not yet powerful enough to see planets orbiting distant stars, so astronomers must infer their presence.','망원경은 아직 먼 별을 공전하는 행성을 볼 만큼 강력하지 않기 때문에 천문학자들은 행성의 존재를 추론해야 합니다.','What can you infer from these observations?','이러한 관찰로부터 무엇을 추론할 수 있습니까?','published'),
('prep-07:influence','prep-07:influence','prep','prep-07','influence','영향; 영향을 미치다','noun','Used her parents'' influence to get the job.','취직을 위해 부모님의 영향력을 이용했습니다.','Her wishes had a great influence on his thinking.','그녀의 소망은 그의 생각에 큰 영향을 미쳤습니다.','published'),
('prep-07:inhibit','prep-07:inhibit','prep','prep-07','inhibit','억제하다','verb','Fear can inhibit creative thinking.','두려움은 창의적인 사고를 방해할 수 있습니다.','The medicine may inhibit the growth of bacteria.','약은 박테리아의 성장을 억제할 수 있습니다.','published'),
('prep-07:initial','prep-07:initial','prep','prep-07','initial','초기의','adjective','Took the initial step toward reconciliation.','화해를 향한 첫 걸음을 내디뎠습니다.','Our initial admiration for their efficiency gave way to disgust about their methods.','그들의 효율성에 대한 우리의 초기 감탄은 그들의 방법에 대한 혐오감으로 바뀌었습니다.','published'),
('prep-07:innovative','prep-07:innovative','prep','prep-07','innovative','혁신적인','adjective','These people are working on the goals in innovative ways.','이 사람들은 혁신적인 방식으로 목표를 달성하기 위해 노력하고 있습니다.','They collaborate to create innovative solutions.','그들은 혁신적인 솔루션을 만들기 위해 협력합니다.','published'),
('prep-07:integrate','prep-07:integrate','prep','prep-07','integrate','통합하다','verb','They were keen to integrate their new skills into the performance.','그들은 자신들의 새로운 기술을 공연에 통합하고 싶어했습니다.','Kabyle people integrate easily into other societies.','Kabyle 사람들은 다른 사회에 쉽게 통합됩니다.','published'),
('prep-07:interact','prep-07:interact','prep','prep-07','interact','상호작용하다','verb','He should interact more with his colleagues.','그는 동료들과 더 많이 상호 작용해야 합니다.','Does cannabis interact with antidepressants or lithium?','대마초는 항우울제나 리튬과 상호작용합니까?','published'),
('prep-07:interpret','prep-07:interpret','prep','prep-07','interpret','해석하다','verb','How do you interpret his behavior?','그의 행동을 어떻게 해석하시나요?','Can you interpret the speech of the visiting dignitaries?','방문 고위 인사들의 연설을 통역할 수 있습니까?','published'),
('prep-07:involve','prep-07:involve','prep','prep-07','involve','포함하다, 관련시키다','verb','Don''t involve me in your family affairs!','당신의 가족 문제에 나를 포함하지 마십시오!','Divide-and-conquer strategies involve pitting groups against one another.','분할 정복 전략에는 그룹을 서로 대결시키는 것이 포함됩니다.','published'),
('prep-07:issue','prep-07:issue','prep','prep-07','issue','문제, 쟁점','noun','The issue could be settled by requiring public education for everyone.','이 문제는 모든 사람에게 공교육을 요구함으로써 해결될 수 있습니다.','She found an old issue of the magazine in her dentist''s waiting room.','그녀는 치과의사 대기실에서 오래된 잡지를 발견했습니다.','published'),
('prep-07:justify','prep-07:justify','prep','prep-07','justify','정당화하다','verb','Can you justify your action?','네 행동을 정당화할 수 있니?','If someone victimizes LGBT people, their own LGBT status does not justify their actions.','누군가가 LGBT를 피해자로 삼는다면, 그 사람의 LGBT 지위가 그 행동을 정당화할 수는 없습니다.','published'),
('prep-08:maintain','prep-08:maintain','prep','prep-08','maintain','유지하다, 주장하다','verb','The trick is to maintain plausible deniability.','비결은 그럴듯한 거부성을 유지하는 것입니다.','Amid speculation that the party is headed for a schism, participants at the meeting resolved to maintain the party''s unity and integrity.','당이 분열로 향하고 있다는 관측이 나오는 가운데, 회의 참석자들은 당의 단결과 청렴을 유지하기로 결의했다.','published'),
('prep-08:major','prep-08:major','prep','prep-08','major','주요한; 전공','adjective','His major field was mathematics.','그의 전공 분야는 수학이었다.','Unemployment is a major problem.','실업은 주요한 문제야.','published'),
('prep-08:measure','prep-08:measure','prep','prep-08','measure','측정하다; 조치','verb','Police presence in the neighborhood was increased as a measure to deter crime.','범죄를 예방하기 위한 조치로 인근 지역에 경찰의 배치가 강화되었습니다.','Each participant wore an activity monitor to measure heart rate, perspiration and sleep quality.','각 참가자는 활동 모니터를 착용하여 심박수, 땀 및 수면의 질을 측정했습니다.','published'),
('prep-08:modify','prep-08:modify','prep','prep-08','modify','수정하다','verb','Please modify this letter to make it more polite.','이 편지를 좀 더 정중하게 수정해 주세요.','The pattern could modify over time.','패턴은 시간이 지남에 따라 변경될 수 있습니다.','published'),
('prep-08:objective','prep-08:objective','prep','prep-08','objective','목표; 객관적인','noun','Is there an objective reality?','객관적인 현실이 있나요?','Is reality subjective or objective?','현실은 주관적인가, 객관적인가?','published'),
('prep-08:obtain','prep-08:obtain','prep','prep-08','obtain','얻다','verb','How did you obtain the visa?','비자는 어떻게 취득하셨나요?','The team may obtain the proposal after careful review.','팀은 신중한 검토를 거쳐 제안서를 얻을 수 있습니다.','published'),
('prep-08:obvious','prep-08:obvious','prep','prep-08','obvious','명백한','adjective','Things like that aren''t always obvious.','그런 것들이 항상 분명한 것은 아닙니다.','Taiwan asks deplaning passengers to report travel histories and any obvious symptoms.','대만은 비행기에서 내리는 승객에게 여행 이력과 명백한 증상을 보고하도록 요청합니다.','published'),
('prep-08:occur','prep-08:occur','prep','prep-08','occur','발생하다','verb','The liftoff will occur in exactly twelve seconds.','이륙은 정확히 12초 후에 발생합니다.','When did these delusions first occur?','언제 망상증상이 처음으로 생겼어?','published'),
('prep-08:participate','prep-08:participate','prep','prep-08','participate','참여하다','verb','Many continue to participate in it by using relics of this very same genocide against its victims.','많은 사람들이 피해자들에 대한 동일한 대량 학살의 유물을 사용하여 계속해서 이에 참여하고 있습니다.','I would like to participate.','참여하고 싶습니다.','published'),
('prep-08:particular','prep-08:particular','prep','prep-08','particular','특정한, 특별한','adjective','A man who wishes to make a particular woman fall in love with him.','특정 여자를 사랑하게 만들고 싶은 남자.','Very particular about how her food was prepared.','그녀의 음식이 어떻게 준비되었는지 매우 특별합니다.','published'),
('prep-08:perceive','prep-08:perceive','prep','prep-08','perceive','인식하다','verb','I could perceive the ship coming over the horizon.','나는 수평선 너머로 배가 다가오는 것을 느낄 수 있었다.','I think cats perceive other dimensions.','고양이는 다른 차원을 인식한다고 생각합니다.','published'),
('prep-08:persist','prep-08:persist','prep','prep-08','persist','지속하다, 고집하다','verb','The symptoms may persist for several days.','증상은 며칠 동안 지속될 수 있습니다.','If problems persist, ask the teacher for help.','문제가 지속되면 교사에게 도움을 요청하세요.','published'),
('prep-08:perspective','prep-08:perspective','prep','prep-08','perspective','관점','noun','People need to hear your perspective, however unfashionable it may be.','사람들은 당신의 관점을 들어야 합니다. 그것이 아무리 유행에 뒤떨어져도 마찬가지입니다.','Observing ironies and funny aspects of different situations improved his perspective on life.','다양한 상황의 아이러니와 재미있는 측면을 관찰하면서 삶에 대한 그의 관점이 향상되었습니다.','published'),
('prep-08:phenomenon','prep-08:phenomenon','prep','prep-08','phenomenon','현상','noun','A volcanic eruption is an impressive phenomenon.','화산 폭발은 인상적인 현상이다.','This is a phenomenon that has repeated itself many times throughout history.','이는 역사 전반에 걸쳐 여러 번 반복된 현상이다.','published'),
('prep-08:potential','prep-08:potential','prep','prep-08','potential','잠재적인; 잠재력','adjective','Tom had all the potential in the world.','톰은 세상의 모든 잠재력을 갖고 있었습니다.','Researchers have developed a moisturizing lotion with the potential to treat deadly skin cancers, psoriasis and promote diabetic wound healing.','연구자들은 치명적인 피부암, 건선을 치료하고 당뇨병성 상처 치유를 촉진할 수 있는 잠재력을 지닌 보습 로션을 개발했습니다.','published'),
('prep-08:precise','prep-08:precise','prep','prep-08','precise','정확한','adjective','Arrived at the precise moment.','정확한 순간에 도착했습니다.','The final decision seemed precise to everyone involved.','최종 결정은 관련된 모든 사람에게 정확해 보였습니다.','published'),
('prep-08:predict','prep-08:predict','prep','prep-08','predict','예측하다','verb','Observers predict low turnout among a disaffected electorate squeezed by a deep economic crisis.','관찰자들은 심각한 경제 위기로 인해 불만을 품은 유권자들의 낮은 투표율을 예측합니다.','Most will laud the crackdown as steps toward transparency, fairness in business and better-run local partner companies, economists predict.','경제학자들은 대부분의 사람들이 이번 단속을 사업의 투명성, 공정성, 더 나은 운영 현지 파트너 회사를 위한 조치로 칭찬할 것이라고 예측합니다.','published'),
('prep-08:preserve','prep-08:preserve','prep','prep-08','preserve','보존하다','verb','Preserve the peace in the family.','가족의 평화를 유지하십시오.','We preserve these archeological findings.','우리는 이러한 고고학적 발견을 보존합니다.','published'),
('prep-08:prevent','prep-08:prevent','prep','prep-08','prevent','막다, 예방하다','verb','We must prevent the cancer from spreading.','암이 퍼지는 것을 예방해야 합니다.','The real issue is how to prevent the disease.','진짜 문제는 어떻게 질병을 막는지야.','published'),
('prep-08:primary','prep-08:primary','prep','prep-08','primary','주요한, 일차적인','adjective','Tom used to be a primary school teacher.','톰은 한때 초등학교 선생님이었었어.','His mother is a nursery school teacher and his father is a primary school teacher.','그의 어머니는 보육원 교사이고 그의 아버지는 초등학교 교사입니다.','published'),
('prep-09:principle','prep-09:principle','prep','prep-09','principle','원칙, 원리','noun','Tom doesn''t give money to chuggers out of principle.','톰은 원칙적으로 처거들에게 돈을 주지 않습니다.','We cannot mistake absolutism for principle, or substitute spectacle for politics, or treat name-calling as reasoned debate.','우리는 절대주의를 원칙으로 착각할 수 없고, 구경거리를 정치로 대체할 수 없으며, 욕설을 이성적인 논쟁으로 취급할 수 없습니다.','published'),
('prep-09:priority','prep-09:priority','prep','prep-09','priority','우선순위','noun','National independence takes priority over class struggle.','계급투쟁보다 민족독립이 우선이다.','Has cybersecurity become a national priority?','사이버 보안이 국가적 우선순위가 되었나요?','published'),
('prep-09:process','prep-09:process','prep','prep-09','process','과정; 처리하다','noun','It was a process of trial and error.','그것은 시행착오의 과정이었습니다.','The progress bars indicate how far each language is in the process of website localization and sentence collection.','진행률 표시줄은 각 언어가 웹사이트 현지화 및 문장 수집 과정에서 어느 정도 진행되고 있는지를 나타냅니다.','published'),
('prep-09:prohibit','prep-09:prohibit','prep','prep-09','prohibit','금지하다','verb','Chinese banks began to prohibit the use of digital currencies in 2013 and stepped up regulations after 2016.','중국 은행들은 2013년부터 디지털화폐 사용을 금지하기 시작했고 2016년 이후 규제를 강화했다.','You can''t prohibit me from doing that.','당신은 내가 그런 일을 하는 것을 금지할 수 없습니다.','published'),
('prep-09:promote','prep-09:promote','prep','prep-09','promote','촉진하다, 홍보하다','verb','Researchers have developed a moisturizing lotion with the potential to treat deadly skin cancers, psoriasis and promote diabetic wound healing.','연구자들은 치명적인 피부암, 건선을 치료하고 당뇨병성 상처 치유를 촉진할 수 있는 잠재력을 지닌 보습 로션을 개발했습니다.','Do you promote hygiene at work?','직장에서 위생을 장려합니까?','published'),
('prep-09:proportion','prep-09:proportion','prep','prep-09','proportion','비율','noun','An inordinate proportion of the book is given over to quotations.','책의 과도한 부분이 인용문으로 제공됩니다.','A dry martini has a large proportion of gin.','드라이 마티니에는 진의 비율이 높습니다.','published'),
('prep-09:provide','prep-09:provide','prep','prep-09','provide','제공하다','verb','It is difficult to provide for my family working on minimum wage.','최저임금으로 일하는 가족을 부양하기가 어렵습니다.','Don''t bother bringing equipment, as we will provide it.','장비는 저희가 제공해드리니 굳이 가져오지 마세요.','published'),
('prep-09:pursue','prep-09:pursue','prep','prep-09','pursue','추구하다','verb','I''m still going to pursue the things I''m interested in.','나는 여전히 내가 관심 있는 일을 추구할 것이다.','If you are a woman, how has your gender impacted your decision to pursue a medical career?','당신이 여성이라면, 당신의 성별이 의료 경력을 추구하기로 한 결정에 어떤 영향을 미쳤습니까?','published'),
('prep-09:react','prep-09:react','prep','prep-09','react','반응하다','verb','Plant pigments such as the carotenoids and chlorophylls will react similarly when exposed to light of high intensity.','카로티노이드 및 엽록소와 같은 식물 색소는 높은 강도의 빛에 노출되면 유사하게 반응합니다.','People often react under pressure.','사람들은 종종 압박감에 반응합니다.','published'),
('prep-09:recognize','prep-09:recognize','prep','prep-09','recognize','인식하다, 인정하다','verb','We do not recognize your gods.','우리는 당신의 신을 인식하지 못합니다.','I recognize that my behaviour has been unacceptable.','나는 내 행동이 용납될 수 없다는 것을 알고 있습니다.','published'),
('prep-09:reduce','prep-09:reduce','prep','prep-09','reduce','줄이다','verb','Reduce your daily fat intake.','일일 지방 섭취량을 줄이세요.','Reduce a problem to a single question.','문제를 하나의 질문으로 축소하세요.','published'),
('prep-09:reflect','prep-09:reflect','prep','prep-09','reflect','반영하다, 숙고하다','verb','People do that sort of thing every day, without ever stopping to reflect on the consequences.','사람들은 결과를 반성하기 위해 멈추지 않고 매일 그런 일을 합니다.','Does your academic record reflect any major challenges? If so, what are they and why did they occur?','귀하의 학업 기록에 주요 어려움이 반영되어 있습니까? 그렇다면, 그것들은 무엇이며 왜 발생했는가?','published'),
('prep-09:regard','prep-09:regard','prep','prep-09','regard','여기다; 관심','verb','At its best, postmodernism is a stance of humility with regard to our ability to correctly understand reality.','최선을 다해 포스트모더니즘은 현실을 올바르게 이해하는 능력에 관한 겸손의 입장입니다.','All the naughts in the universe are equal to one naught alone, in regard to their substance and value.','우주의 모든 무(無)는 그 실체와 가치 면에서 단 하나의 무와 같습니다.','published'),
('prep-09:reinforce','prep-09:reinforce','prep','prep-09','reinforce','강화하다','verb','The right homework will reinforce and complement the lesson!','올바른 숙제는 수업을 강화하고 보완할 것입니다!','Advertising for fast food can reinforce unhealthy dietary tendencies.','패스트푸드 광고는 건강에 해로운 식습관 경향을 강화할 수 있습니다.','published'),
('prep-09:relate','prep-09:relate','prep','prep-09','relate','관련시키다','verb','I cannot relate these events at all.','나는 이 사건들을 전혀 연관시킬 수 없습니다.','I relate to about a third of this.','나는 이것의 약 3분의 1에 해당합니다.','published'),
('prep-09:relevant','prep-09:relevant','prep','prep-09','relevant','관련 있는','adjective','The scientist corresponds with colleagues in order to learn about matters relevant to her own research.','과학자는 자신의 연구와 관련된 문제에 대해 배우기 위해 동료들과 연락합니다.','We all have experienced the serendipity of relevant information arriving just when we were least expecting it.','우리 모두는 전혀 예상하지 못한 순간에 관련 정보가 우연히 도착하는 것을 경험해 왔습니다.','published'),
('prep-09:represent','prep-09:represent','prep','prep-09','represent','나타내다, 대표하다','verb','I represent the silent majority.','나는 침묵하는 다수를 대표합니다.','Braille is a code that uses bumps and indentation on a surface to represent letters, which can be recognized by touch.','점자는 문자를 표현하기 위해 표면의 돌기와 들여쓰기를 사용하여 터치로 인식할 수 있는 코드입니다.','published'),
('prep-09:require','prep-09:require','prep','prep-09','require','요구하다','verb','We require our secretary to be on time.','우리는 비서가 정시에 도착하도록 요구합니다.','Mutual aid does not require that people like each other, only that they have a common need.','상호부조는 사람들이 서로를 좋아할 것을 요구하지 않고, 단지 그들이 공통된 필요를 가지고 있을 뿐이라는 것을 요구합니다.','published'),
('prep-09:resolve','prep-09:resolve','prep','prep-09','resolve','해결하다, 결심하다','verb','Are diplomatic efforts enough to resolve the crisis?','외교적 노력만으로 위기를 해결할 수 있을까?','You inspire others through your quiet resolve.','당신은 조용한 결심으로 다른 사람들에게 영감을 줍니다.','published'),
('prep-09:respond','prep-09:respond','prep','prep-09','respond','반응하다, 대답하다','verb','Why would anyone respond to your text?','왜 누군가가 당신의 문자에 응답하겠습니까?','I''m not sure if I will respond.','내가 응답할지 잘 모르겠습니다.','published'),
('prep-10:restrict','prep-10:restrict','prep','prep-10','restrict','제한하다','verb','The move gives authorities greater latitude to forcibly restrict public gatherings and enforce quarantines on those with the virus.','이번 조치로 인해 당국은 공개 모임을 강제로 제한하고 바이러스에 감염된 사람들에 대한 격리를 시행할 수 있는 더 큰 재량권을 갖게 되었습니다.','The team may restrict the proposal after careful review.','팀에서는 신중한 검토 후 제안을 제한할 수 있습니다.','published'),
('prep-10:result','prep-10:result','prep','prep-10','result','결과; 결과로 생기다','noun','He computed the result to four decimal places.','그는 결과를 소수점 이하 네 자리까지 계산했습니다.','Two things result from this fact.','이 사실로 인해 두 가지 결과가 발생합니다.','published'),
('prep-10:retain','prep-10:retain','prep','prep-10','retain','유지하다, 보유하다','verb','I cannot retain so much information.','나는 그렇게 많은 정보를 담을 수 없다.','The students were asked to retain something important.','학생들은 중요한 것을 간직하도록 요청받았습니다.','published'),
('prep-10:reveal','prep-10:reveal','prep','prep-10','reveal','드러내다','verb','The actress won''t reveal how old she is.','여배우는 자신의 나이를 밝히지 않을 것입니다.','He didn''t reveal his secret.','그는 자신의 비밀을 밝히지 않았다.','published'),
('prep-10:shift','prep-10:shift','prep','prep-10','shift','변화하다; 변화','verb','We''ll have to shift these boxes to the downtown office.','이 상자들을 시내 사무실로 옮겨야 해요.','How can I shift a grass stain?','잔디 얼룩을 어떻게 옮길 수 있나요?','published'),
('prep-10:significant','prep-10:significant','prep','prep-10','significant','중요한, 상당한','adjective','The interaction effect is significant at the .01 level.','상호작용 효과는 .01 수준에서 유의미합니다.','No significant difference was found.','유의미한 차이는 발견되지 않았습니다.','published'),
('prep-10:similar','prep-10:similar','prep','prep-10','similar','비슷한','adjective','Similar things happened in other countries.','다른 나라에서도 비슷한 일이 일어났습니다.','I was having similar feelings.','저도 비슷한 감정을 갖고 있었어요.','published'),
('prep-10:specific','prep-10:specific','prep','prep-10','specific','구체적인, 특정한','adjective','Quinine is highly specific for malaria.','퀴닌은 말라리아에 매우 특이적입니다.','A specific stain is one having a specific affinity for particular structural elements.','특정 얼룩은 특정 구조 요소에 대해 특정한 친화력을 갖는 얼룩입니다.','published'),
('prep-10:strategy','prep-10:strategy','prep','prep-10','strategy','전략','noun','It is a colonial divide-and-conquer strategy to pit religious people against one another.','종교인들을 서로 대립시키려는 식민지 분할정복 전략이다.','When I have a panic attack, my best strategy for coping with it is to accept whatever I''m afraid of.','공황 발작이 일어났을 때 대처하기 위한 최선의 전략은 내가 두려워하는 모든 것을 받아들이는 것입니다.','published'),
('prep-10:substitute','prep-10:substitute','prep','prep-10','substitute','대체하다; 대체물','verb','The young teacher had to substitute for the sick colleague.','젊은 교사는 아픈 동료를 대신해야 했습니다.','I had to substitute new parts for the old ones.','오래된 부품을 새 부품으로 교체해야 했습니다.','published'),
('prep-10:sufficient','prep-10:sufficient','prep','prep-10','sufficient','충분한','adjective','There is not sufficient access to the internet in many small rural villages.','많은 소규모 시골 마을에는 인터넷 접속이 충분하지 않습니다.','A two-week training course is sufficient to get a job in the coach-driving profession.','코치 운전직에 취업하려면 2주간의 훈련 과정이면 충분합니다.','published'),
('prep-10:sustain','prep-10:sustain','prep','prep-10','sustain','유지하다, 지탱하다','verb','The money will sustain our good cause.','그 돈은 우리의 좋은 목적을 뒷받침해 줄 것입니다.','Provisions to sustain an army.','군대를 유지하기 위한 규정.','published'),
('prep-10:tend','prep-10:tend','prep','prep-10','tend','~하는 경향이 있다','verb','We need to tend to the garden, which has become a mess.','우리는 엉망이 되어버린 정원을 가꾸어야 합니다.','Ignorant people tend to be arrogant.','무지한 사람은 오만한 경향이 있어.','published'),
('prep-10:transform','prep-10:transform','prep','prep-10','transform','변형시키다','verb','Education can transform a student''s future.','교육은 학생의 미래를 변화시킬 수 있습니다.','Heat can transform water into steam.','열은 물을 증기로 변화시킬 수 있습니다.','published'),
('prep-10:valid','prep-10:valid','prep','prep-10','valid','타당한, 유효한','adjective','The license is still valid.','라이센스는 아직 유효합니다.','Occupying powers never consider an insurgency''s cause to be valid.','점령 세력은 결코 반란의 원인이 타당하다고 생각하지 않습니다.','published'),
('prep-10:vary','prep-10:vary','prep','prep-10','vary','다르다, 변하다','verb','His moods vary depending on the weather.','그의 기분은 날씨에 따라 달라집니다.','My thoughts on life vary with my mood, and I have a mood disorder.','기분에 따라 인생에 대한 생각이 달라지고 기분 장애가 있습니다.','published'),
('prep-10:virtually','prep-10:virtually','prep','prep-10','virtually','사실상, 거의','adverb','The classroom was virtually empty after lunch.','점심시간 이후 교실은 거의 텅 비어 있었습니다.','The two designs are virtually identical.','두 디자인은 사실상 동일합니다.','published'),
('prep-10:widespread','prep-10:widespread','prep','prep-10','widespread','널리 퍼진','adjective','Human rights violations, misogyny and exclusion are widespread and systematic.','인권침해, 여성혐오, 배제는 광범위하고 체계적입니다.','The BMJ editorial describes oppression against women and girls as a great injustice that is insidious, systematic and widespread.','BMJ 사설은 여성과 소녀에 대한 억압을 교활하고 체계적이며 널리 퍼져 있는 큰 불의로 묘사합니다.','published'),
('prep-10:withdraw','prep-10:withdraw','prep','prep-10','withdraw','철회하다, 인출하다','verb','The company decided to withdraw the unsafe product.','회사는 안전하지 않은 제품을 철수하기로 결정했습니다.','You can withdraw cash from the bank account.','은행 계좌에서 현금을 인출할 수 있습니다.','published'),
('prep-10:yield','prep-10:yield','prep','prep-10','yield','산출하다, 양보하다','verb','We should plant aplenty of cherry and small fruit trees to yield feed for birds.','우리는 새들에게 먹이를 주기 위해 벚나무와 작은 과일나무를 많이 심어야 합니다.','A cultivar is a plant deliberately selected for its characteristics, such as color, crop yield or disease resistance.','품종은 색상, 작물 수확량 또는 질병 저항성과 같은 특성을 위해 의도적으로 선택된 식물입니다.','published'),
('grade1-01:ability','grade1-01:ability','grade1','grade1-01','ability','능력','noun','This phone has the ability to have its software upgraded wirelessly.','이 전화기에는 소프트웨어를 무선으로 업그레이드할 수 있는 기능이 있습니다.','She has an uncanny ability to defuse conflict.','그녀는 갈등을 해소하는 놀라운 능력을 가지고 있습니다.','published'),
('grade1-01:able','grade1-01:able','grade1','grade1-01','able','할 수 있는','adjective','She was able to finish the assignment on time.','그녀는 제시간에 과제를 끝낼 수 있었습니다.','The new system is able to process the data quickly.','새로운 시스템은 데이터를 빠르게 처리할 수 있습니다.','published'),
('grade1-01:absence','grade1-01:absence','grade1','grade1-01','absence','부재','noun','He was surprised by the absence of any explanation.','별다른 설명이 없어 깜짝 놀랐다.','He visited during my absence.','내가 없는 동안 그는 방문했다.','published'),
('grade1-01:absolute','grade1-01:absolute','grade1','grade1-01','absolute','절대적인','adjective','An absolute guarantee to respect the nation''s authority.','국가의 권위를 존중하는 절대적인 보장입니다.','Absolute tolerance is ruinous to a tolerant society.','절대적인 관용은 관용적인 사회에 파멸을 가져온다.','published'),
('grade1-01:accept','grade1-01:accept','grade1','grade1-01','accept','받아들이다','verb','I cannot accept the dogma of this church.','나는 이 교회의 교리를 받아들일 수 없습니다.','I cannot accept your invitation.','나는 당신의 초대를 받아들일 수 없습니다.','published'),
('grade1-01:accident','grade1-01:accident','grade1','grade1-01','accident','사고','noun','Winning the lottery was a happy accident.','복권에 당첨된 것은 행복한 우연이었습니다.','It was due to an accident or fortuity.','사고나 우연으로 인한 일이었습니다.','published'),
('grade1-01:active','grade1-01:active','grade1','grade1-01','active','활동적인','adjective','A director who takes an active interest in corporate operations.','기업 운영에 적극적으로 관심을 갖고 있는 이사입니다.','He was active in drawing attention to their grievances.','그는 그들의 불만을 알리는 데 적극적이었습니다.','published'),
('grade1-01:activity','grade1-01:activity','grade1','grade1-01','activity','활동','noun','They avoided all recreational activity.','그들은 모든 오락 활동을 피했습니다.','Pit row was abuzz with activity.','피트 로우는 활동으로 분주했습니다.','published'),
('grade1-01:actual','grade1-01:actual','grade1','grade1-01','actual','실제의','adjective','The predicted temperature and the actual temperature were markedly different.','예상 기온과 실제 기온은 확연히 달랐다.','We saw the actual wedding on television.','우리는 텔레비전에서 실제 결혼식을 보았습니다.','published'),
('grade1-01:adapt','grade1-01:adapt','grade1','grade1-01','adapt','적응하다','verb','To adapt a story for the stage.','이야기를 무대에 맞게 조정합니다.','They could not adapt to the new climate and so perished.','그들은 새로운 기후에 적응하지 못하고 멸망했습니다.','published'),
('grade1-01:address','grade1-01:address','grade1','grade1-01','address','주소;다루다','noun','He failed in his manner of address to the captain.','그는 선장에게 말하는 방식이 실패했습니다.','I forgot my email address.','내 이메일 주소를 잊어버렸다.','published'),
('grade1-01:admire','grade1-01:admire','grade1','grade1-01','admire','존경하다','verb','Our kings admire their subjects.','우리 왕들은 그들의 신민을 존경합니다.','The team may admire the proposal after careful review.','팀은 신중하게 검토한 후 제안에 감탄할 수 있습니다.','published'),
('grade1-01:admit','grade1-01:admit','grade1','grade1-01','admit','인정하다','verb','We cannot admit non-members into our club building.','우리 클럽 건물에는 비회원이 출입할 수 없습니다.','We''ll have to vote on whether or not to admit a new member.','우리는 새로운 회원을 받아들일지 말지 투표를 해야 합니다.','published'),
('grade1-01:advance','grade1-01:advance','grade1','grade1-01','advance','발전;진보하다','noun','You have to book in advance.','미리 예약하셔야 합니다.','You need to register for the event in advance.','행사에 사전 등록을 하셔야 합니다.','published'),
('grade1-01:advantage','grade1-01:advantage','grade1','grade1-01','advantage','장점','noun','The experience gave him the advantage over me.','그 경험은 그에게 나보다 유리하게 작용했습니다.','It turned out to my advantage.','그것은 나에게 유리한 것으로 판명되었습니다.','published'),
('grade1-01:adventure','grade1-01:adventure','grade1','grade1-01','adventure','모험','noun','That pot-bellied, belligerent green ogre is back for yet another animated adventure.','배불뚝이 호전적인 녹색 오우거가 또 다른 애니메이션 모험을 위해 돌아왔습니다.','They went on a snorkeling adventure in the coral reef.','그들은 산호초에서 스노클링 모험을 떠났습니다.','published'),
('grade1-01:advice','grade1-01:advice','grade1','grade1-01','advice','조언','noun','She was offered various piece of advice on what to do with her new-found wealth.','그녀는 새로 발견한 부를 어떻게 해야 할지에 대한 다양한 조언을 받았습니다.','An advice of an incoming settlement payment order may be given to an off-line receiving bank.','오프라인 수취은행에 입금결제지시를 통지할 수 있다.','published'),
('grade1-01:afford','grade1-01:afford','grade1','grade1-01','afford','여유가 있다','verb','I can''t afford to spend two hours with this person.','나는 이 사람과 두 시간을 보낼 여유가 없습니다.','We can''t afford to send our children to college.','우리는 아이들을 대학에 보낼 여유가 없습니다.','published'),
('grade1-01:afraid','grade1-01:afraid','grade1','grade1-01','afraid','두려워하는','adjective','She was afraid to speak in front of the class.','그녀는 학급 앞에서 연설하는 것을 두려워했습니다.','The child felt afraid during the loud storm.','큰 폭풍우가 몰아치는 가운데 아이는 두려움을 느꼈습니다.','published'),
('grade1-01:agency','grade1-01:agency','grade1','grade1-01','agency','기관','noun','An example is the best agency of instruction.','예를 들어 최고의 교육 기관이 있습니다.','Beyle works at an employment agency.','Beyle은 직업 소개소에서 일합니다.','published'),
('grade1-02:agree','grade1-02:agree','grade1','grade1-02','agree','동의하다','verb','I can''t agree with you!','나는 당신의 의견에 동의할 수 없습니다!','The two stories don''t agree in many details.','두 이야기는 많은 세부 사항에서 일치하지 않습니다.','published'),
('grade1-02:alarm','grade1-02:alarm','grade1','grade1-02','alarm','경보','noun','My father set the alarm for six o''clock.','우리 아빠는 알람을 일곱 시로 맞췄어.','I was late for work because my alarm didn''t go off.','알람이 울리지 않아서 출근에 늦었습니다.','published'),
('grade1-02:allow','grade1-02:allow','grade1','grade1-02','allow','허락하다','verb','This sealed door won''t allow the water come into the basement.','이 봉인된 문은 물이 지하실로 들어오는 것을 허용하지 않습니다.','I cannot allow you to see your exam.','나는 당신이 시험을 보는 것을 허락할 수 없습니다.','published'),
('grade1-02:almost','grade1-02:almost','grade1','grade1-02','almost','거의','adverb','The students had almost finished the project.','학생들은 프로젝트를 거의 마쳤습니다.','It was almost midnight when the meeting ended.','회의가 끝났을 때는 거의 자정이 가까워졌습니다.','published'),
('grade1-02:alone','grade1-02:alone','grade1','grade1-02','alone','혼자','adverb','He completed the difficult assignment alone.','그는 혼자서 어려운 임무를 완수했습니다.','The old house stood alone on the hill.','오래된 집은 언덕 위에 홀로 서 있었습니다.','published'),
('grade1-02:although','grade1-02:although','grade1','grade1-02','although','비록 ~이지만','conjunction','Although it was raining, the students continued the game.','비가 와도 학생들은 경기를 계속했다.','She smiled although she was nervous.','그녀는 긴장하면서도 웃었다.','published'),
('grade1-02:amazing','grade1-02:amazing','grade1','grade1-02','amazing','놀라운','adjective','She does an amazing amount of work.','그녀는 놀라운 일을 하고 있습니다.','Tom is an amazing actor.','톰은 놀라운 배우다.','published'),
('grade1-02:amount','grade1-02:amount','grade1','grade1-02','amount','양','noun','The amount he had in cash was insufficient.','그가 갖고 있는 현금은 턱없이 부족했다.','Voice recognition technologies bring a human dimension to our devices, but developers need an enormous amount of voice data to build them.','음성 인식 기술은 우리 장치에 인간적인 차원을 더해 주지만 개발자는 이를 구축하기 위해 엄청난 양의 음성 데이터가 필요합니다.','published'),
('grade1-02:ancient','grade1-02:ancient','grade1','grade1-02','ancient','고대의','adjective','I like learning ancient languages.','난 고대 언어를 배우는 걸 좋아해.','He''s a member of the ancient priestly caste.','그는 고대 성직자 계급의 일원입니다.','published'),
('grade1-02:announce','grade1-02:announce','grade1','grade1-02','announce','발표하다','verb','The man went to the door, and returned to announce that all was quiet.','그 남자는 문으로 갔다가 다시 돌아와 모든 것이 조용해졌다고 알렸습니다.','The students were asked to announce something important.','학생들은 중요한 내용을 발표해 달라는 요청을 받았습니다.','published'),
('grade1-02:annual','grade1-02:annual','grade1','grade1-02','annual','매년의','adjective','Under U.S. law, all top government officials are required to file annual financial disclosure documents with the agency.','미국 법률에 따르면 모든 최고 정부 공무원은 해당 기관에 연간 재무 공개 문서를 제출해야 합니다.','One of the cozy traditions associated with college life is receiving and then pouring over your copy of the annual yearbook.','대학 생활과 관련된 아늑한 전통 중 하나는 연간 앨범을 받아 그 위에 쏟아 붓는 것입니다.','published'),
('grade1-02:anxiety','grade1-02:anxiety','grade1','grade1-02','anxiety','불안','noun','Mary has generalized anxiety disorder.','메리는 범불안장애를 앓고 있습니다.','Marijuana helps my partner''s anxiety, but is the worst possible thing for mine.','마리화나는 파트너의 불안을 덜어주지만 나에게는 최악의 상황입니다.','published'),
('grade1-02:apologize','grade1-02:apologize','grade1','grade1-02','apologize','사과하다','verb','Mary is too stubborn to apologize.','메리는 고집불통이라, 사과할 줄을 모른다.','You should apologize to her for being so distant.','당신은 그 여자에게 거리를 두고 지낸 것에 대해 사과해야 한다.','published'),
('grade1-02:apply','grade1-02:apply','grade1','grade1-02','apply','지원하다;적용하다','verb','Apply a magnetic field here.','여기에 자기장을 적용하십시오.','I apply this rule to get good results.','나는 좋은 결과를 얻기 위해 이 규칙을 적용합니다.','published'),
('grade1-02:appreciate','grade1-02:appreciate','grade1','grade1-02','appreciate','감사하다','verb','Do you appreciate the full meaning of this letter?','이 편지의 전체 의미를 이해하십니까?','You must learn to appreciate time.','시간을 감사하는 법을 배워야합니다.','published'),
('grade1-02:approach','grade1-02:approach','grade1','grade1-02','approach','접근하다','verb','That''s a very anglonormative approach.','그것은 매우 앵글로 규범적인 접근 방식입니다.','An experimental treatment providing a new approach in the fight against HIV has cleared the first hurdle.','HIV 퇴치에 새로운 접근 방식을 제공하는 실험적 치료법이 첫 번째 장애물을 통과했습니다.','published'),
('grade1-02:appropriate','grade1-02:appropriate','grade1','grade1-02','appropriate','적절한','adjective','A funeral conducted the appropriate solemnity.','장례식은 적절한 엄숙함으로 거행되었습니다.','It seems that an apology is appropriate.','사과하는 것이 적절할 것 같습니다.','published'),
('grade1-02:arrange','grade1-02:arrange','grade1','grade1-02','arrange','정리하다','verb','Once two people involved in a dispute have explained themselves, they arrange a compromise.','분쟁에 연루된 두 사람이 자신의 입장을 설명하면 타협을 주선합니다.','They arrange the desks for better flow.','그들은 더 나은 흐름을 위해 책상을 배열합니다.','published'),
('grade1-02:arrive','grade1-02:arrive','grade1','grade1-02','arrive','도착하다','verb','Will we arrive on time?','우리가 제 시간에 도착할까?','I''ll try my best to arrive early.','빨리 도착해 보도록 최선을 다하겠습니다.','published'),
('grade1-02:article','grade1-02:article','grade1','grade1-02','article','기사;글','noun','It''s a good article, but it could use some copyediting.','좋은 글이지만 약간의 편집이 필요할 수 있습니다.','The indefinite article is used before countable nouns.','부정관사는 셀 수 있는 명사 앞에 사용됩니다.','published'),
('grade1-03:aspect','grade1-03:aspect','grade1','grade1-03','aspect','측면','noun','Gambling needs to be looked at not as a personal failing, but as an aspect of an exploitative system.','도박은 개인적인 실패가 아니라 착취적인 시스템의 한 측면으로 보아야 합니다.','Addiction is not a personal failing but an aspect of an exploitative system.','중독은 개인적인 실패가 아니라 착취적인 시스템의 한 측면입니다.','published'),
('grade1-03:assist','grade1-03:assist','grade1','grade1-03','assist','돕다','verb','They were on call to assist during any emergency situation.','긴급 상황이 발생하면 도움을 주기 위해 대기 중이었습니다.','Tom volunteered to assist in the medical care unit.','Tom은 의료 부서를 돕기 위해 자원했습니다.','published'),
('grade1-03:assume','grade1-03:assume','grade1','grade1-03','assume','가정하다','verb','I assume his train was late.','나는 그의 기차가 늦었다고 생각한다.','The gods assume human or animal form in these fables.','이 우화에서 신들은 인간이나 동물의 형태를 취합니다.','published'),
('grade1-03:attack','grade1-03:attack','grade1','grade1-03','attack','공격하다','verb','The visiting team started to attack.','원정팀이 공격을 시작했다.','This is a calculated attack by the world''s most powerful people on the poor and marginalized.','이것은 가난하고 소외된 사람들에 대한 세계 최고의 권력자들의 계산된 공격입니다.','published'),
('grade1-03:attend','grade1-03:attend','grade1','grade1-03','attend','참석하다','verb','I rarely attend services at my church.','나는 교회 예배에 거의 참석하지 않습니다.','I must attend to this matter.','나는 이 문제에 참석해야 합니다.','published'),
('grade1-03:attention','grade1-03:attention','grade1','grade1-03','attention','주의','noun','The old car needs constant attention.','오래된 차는 지속적인 관심이 필요합니다.','She was the center of attention.','그녀는 관심의 중심이었습니다.','published'),
('grade1-03:attitude','grade1-03:attitude','grade1','grade1-03','attitude','태도','noun','He had the attitude that work was fun.','그는 일이 재미있다는 태도를 갖고 있었습니다.','He assumed an attitude of surrender.','그는 항복하는 태도를 취했습니다.','published'),
('grade1-03:attract','grade1-03:attract','grade1','grade1-03','attract','끌어들이다','verb','Her good looks attract the stares of many men.','그녀의 잘생긴 외모는 많은 남자들의 시선을 사로잡는다.','This orchid mimics the shape and colors of a pansy flower to attract pollinators that normally go to a pansy.','이 난초는 팬지 꽃의 모양과 색상을 모방하여 일반적으로 팬지에게 이동하는 수분매개자를 유인합니다.','published'),
('grade1-03:average','grade1-03:average','grade1','grade1-03','average','평균','noun','He is about average in height.','그는 키가 평균 정도입니다.','The snowfall this month is below average.','이번 달 강설량은 평균보다 적습니다.','published'),
('grade1-03:avoid','grade1-03:avoid','grade1','grade1-03','avoid','피하다','verb','Her former friends now avoid her.','그녀의 이전 친구들은 이제 그녀를 피합니다.','He should avoid publishing his wife''s memories.','그는 아내의 추억을 공개하는 것을 피해야 합니다.','published'),
('grade1-03:aware','grade1-03:aware','grade1','grade1-03','aware','알고 있는','adjective','Students should be aware of the deadline.','학생들은 마감일을 알고 있어야 합니다.','She became aware of a problem in the report.','그녀는 보고서에서 문제를 알게 되었습니다.','published'),
('grade1-03:balance','grade1-03:balance','grade1','grade1-03','balance','균형','noun','In all perfectly beautiful objects there is found the opposition of one part to another and a reciprocal balance.','완벽하게 아름다운 모든 대상에는 한 부분이 다른 부분에 대한 반대와 상호 균형이 있습니다.','He took what he wanted and I got the balance.','그는 원하는 것을 가져갔고 나는 균형을 얻었습니다.','published'),
('grade1-03:battle','grade1-03:battle','grade1','grade1-03','battle','전투','noun','He fought a battle for recognition.','그는 인정받기 위해 싸웠다.','Police tried to control the battle between the pro- and anti-abortion mobs.','경찰은 낙태를 찬성하는 폭도와 반대 폭도 사이의 싸움을 통제하려고 노력했습니다.','published'),
('grade1-03:beauty','grade1-03:beauty','grade1','grade1-03','beauty','아름다움','noun','The beauty of the deal is it costs nothing!','거래의 장점은 비용이 전혀 들지 않는다는 것입니다!','She is a real beauty.','그녀는 정말이지 아름답다.','published'),
('grade1-03:behavior','grade1-03:behavior','grade1','grade1-03','behavior','행동','noun','The behavior of small particles can be studied in experiments.','작은 입자의 거동은 실험을 통해 연구될 수 있습니다.','He was on his best behavior when her family visited.','그녀의 가족이 방문했을 때 그는 최선을 다해 행동했습니다.','published'),
('grade1-03:belief','grade1-03:belief','grade1','grade1-03','belief','믿음','noun','It strengthened my belief in his sincerity.','그것은 그의 진실성에 대한 나의 믿음을 강화시켰습니다.','It''s my belief that the thief is somebody known to us.','그 도둑은 우리에게 알려진 사람일 것이라고 나는 믿습니다.','published'),
('grade1-03:benefit','grade1-03:benefit','grade1','grade1-03','benefit','이익','noun','The risks of such a project would clearly outweigh any putative benefit.','그러한 프로젝트의 위험은 추정되는 이익보다 분명히 더 클 것입니다.','People with dark hair would benefit more from laser hair removal than electrolysis.','검은 머리를 가진 사람들은 전기 제모보다 레이저 제모가 더 많은 이점을 얻을 수 있습니다.','published'),
('grade1-03:beyond','grade1-03:beyond','grade1','grade1-03','beyond','~을 넘어서','preposition','The small village lies beyond the mountain.','산 너머에는 작은 마을이 있다.','The final result went beyond our expectations.','최종 결과는 우리의 기대 이상이었습니다.','published'),
('grade1-03:blame','grade1-03:blame','grade1','grade1-03','blame','비난하다','verb','Somebody has to take the blame.','누군가는 책임을 져야 한다.','Blame is like the wind; if we see it, we feel it.','비난은 바람과 같다. 우리가 그것을 보면 느낀다.','published'),
('grade1-03:blank','grade1-03:blank','grade1','grade1-03','blank','빈','adjective','There was a look of blank terror on his face.','그의 얼굴에는 공허한 공포의 빛이 떠올랐다.','Failing to understand the question, he gave me a blank stare.','질문을 이해하지 못한 그는 나를 멍하니 바라보았다.','published'),
('grade1-04:borrow','grade1-04:borrow','grade1','grade1-04','borrow','빌리다','verb','May I borrow your lawn mower?','당신의 잔디 깎는 기계를 빌려도 될까요?','To borrow the style, manner, or opinions of another.','남의 스타일이나 태도, 의견을 빌리다.','published'),
('grade1-04:brain','grade1-04:brain','grade1','grade1-04','brain','뇌','noun','She was a total brain.','그녀는 완전한 두뇌였습니다.','The computer''s brain is capable of millions of calculations a second.','컴퓨터의 두뇌는 초당 수백만 번의 계산을 수행할 수 있습니다.','published'),
('grade1-04:brave','grade1-04:brave','grade1','grade1-04','brave','용감한','adjective','Familiarity with danger makes a brave man braver but less daring.','위험에 익숙해지면 용감한 사람은 더 용감해지지만 덜 대담해집니다.','Girls decked out in brave new dresses.','멋진 새 드레스를 입은 소녀들.','published'),
('grade1-04:bright','grade1-04:bright','grade1','grade1-04','bright','밝은','adjective','The sun was bright and hot.','태양은 밝고 뜨거웠습니다.','The room was bright and airy.','방은 밝고 바람이 잘 통했습니다.','published'),
('grade1-04:broad','grade1-04:broad','grade1','grade1-04','broad','넓은','adjective','Gave us a broad hint that it was time to leave.','이제 떠날 시간이라는 폭넓은 힌트를 우리에게 주었습니다.','His square jaw, broad shoulders and resonant voice served him well in big-budget historical movies in the 1950s and 1960s.','그의 각진 턱, 넓은 어깨, 울려퍼지는 목소리는 1950년대와 1960년대의 대규모 예산 역사 영화에서 그에게 큰 도움이 되었습니다.','published'),
('grade1-04:budget','grade1-04:budget','grade1','grade1-04','budget','예산','noun','The laboratory runs on a budget of a million a year.','연구실은 연간 백만 달러의 예산으로 운영됩니다.','In all, the auditor general said his office uncovered $170 million in funds misused from the national budget.','감사원장은 자신의 사무실에서 국가 예산에서 1억 7천만 달러의 자금이 남용된 사실을 적발했다고 말했습니다.','published'),
('grade1-04:build','grade1-04:build','grade1','grade1-04','build','짓다','verb','Algerian leaders build only mosques, but when they are sick they go abroad.','알제리 지도자들은 모스크만 짓고 몸이 아프면 해외로 떠난다.','Voice recognition technologies bring a human dimension to our devices, but developers need an enormous amount of voice data to build them.','음성 인식 기술은 우리 장치에 인간적인 차원을 더해 주지만 개발자는 이를 구축하기 위해 엄청난 양의 음성 데이터가 필요합니다.','published'),
('grade1-04:calm','grade1-04:calm','grade1','grade1-04','calm','차분한','adjective','Remained calm throughout the uproar.','소란이 일어나는 동안에도 침착함을 유지했습니다.','I just need to stay calm.','나는 단지 차분해질 필요가 있어.','published'),
('grade1-04:cancel','grade1-04:cancel','grade1','grade1-04','cancel','취소하다','verb','Terms like "woke" and "cancel culture" are used by the right as filler to disguise the lack of substance in their arguments.','권리에서는 "깨어남" 및 "문화 취소"와 같은 용어를 주장의 실체 부족을 위장하기 위해 보충용으로 사용합니다.','I''d like to cancel my subscription.','구독을 취소하고 싶습니다.','published'),
('grade1-04:career','grade1-04:career','grade1','grade1-04','career','직업;경력','noun','The general had had a distinguished career.','장군은 뛰어난 경력을 가지고 있었습니다.','He had a long career in the law.','그는 법조계에서 오랜 경력을 쌓았습니다.','published'),
('grade1-04:careful','grade1-04:careful','grade1','grade1-04','careful','조심하는','adjective','They were careful when crossing the busy street.','그들은 혼잡한 거리를 건널 때 조심했습니다.','Be careful to keep her shoes clean.','그녀의 신발을 깨끗하게 유지하도록 조심하십시오.','published'),
('grade1-04:celebrate','grade1-04:celebrate','grade1','grade1-04','celebrate','축하하다','verb','I don''t want to celebrate my birthday.','난 내 생일을 축하하고 싶지 않다.','Tom passed his exams, so his dad popped out the champers to celebrate.','톰이 시험에 합격하자 그의 아버지는 축하하기 위해 챔피언들을 데리고 나왔습니다.','published'),
('grade1-04:certain','grade1-04:certain','grade1','grade1-04','certain','확실한','adjective','Certain breeds do not make good pets.','특정 품종은 좋은 애완동물이 되지 않습니다.','Certain members have not paid their dues.','일부 회원은 회비를 납부하지 않았습니다.','published'),
('grade1-04:challenge','grade1-04:challenge','grade1','grade1-04','challenge','도전','noun','This is our biggest challenge.','이것은 우리에게 가장 큰 도전이다.','She decided to embark on a new challenge to further her career.','그녀는 자신의 경력을 더욱 발전시키기 위해 새로운 도전을 시작하기로 결정했습니다.','published'),
('grade1-04:chance','grade1-04:chance','grade1','grade1-04','chance','기회','noun','We ran into each other by pure chance.','우리는 순전히 우연히 서로를 만났습니다.','You take a chance when you let her drive.','그녀에게 운전을 맡기면 기회를 잡을 수 있습니다.','published'),
('grade1-04:charge','grade1-04:charge','grade1','grade1-04','charge','요금;청구하다','noun','The wrestler''s charge carried him past his adversary.','레슬링 선수의 돌격은 그를 그의 적을 지나치게 만들었습니다.','The battle began with a cavalry charge.','전투는 기병대의 돌격으로 시작되었습니다.','published'),
('grade1-04:choice','grade1-04:choice','grade1','grade1-04','choice','선택','noun','Your choice of colors was unfortunate.','색상 선택이 아쉽네요.','My only choice is to refuse.','나의 유일한 선택은 거절하는 것이다.','published'),
('grade1-04:citizen','grade1-04:citizen','grade1','grade1-04','citizen','시민','noun','Diogenes reckoned himself a citizen of the world.','디오게네스는 자신을 세계의 시민으로 여겼습니다.','People used to call me lazy, but now all of a sudden I''m a responsible citizen.','사람들은 저를 게으른 사람이라고 불렀습니다. 그런데 이제는 갑자기 책임감 있는 시민이 되었습니다.','published'),
('grade1-04:claim','grade1-04:claim','grade1','grade1-04','claim','주장하다','verb','The claim that nonbinary people do not have gender dysphoria is dated and runs contrary to current medical standards.','논바이너리 사람들이 성별위화감을 느끼지 않는다는 주장은 시대에 뒤떨어진 것이며 현재의 의료 기준에 어긋납니다.','How sick do you have to be to claim that unarmed protesters were trying to get shot?','비무장 시위대가 총에 맞으려고 했다고 주장하려면 얼마나 속상해야 할까요?','published'),
('grade1-04:collect','grade1-04:collect','grade1','grade1-04','collect','모으다','verb','How should I collect and store a poo, I mean stool, sample?','똥, 즉 대변, 샘플을 어떻게 수집하고 보관해야 합니까?','How should I collect and store a pee, I mean urine, sample?','소변, 즉 소변, 샘플을 어떻게 수집하고 보관해야 합니까?','published'),
('grade1-05:comfortable','grade1-05:comfortable','grade1','grade1-05','comfortable','편안한','adjective','Made himself comfortable in an armchair.','안락의자에 편안하게 앉았습니다.','The antihistamine made her feel more comfortable.','항히스타민제는 그녀의 기분을 더욱 편안하게 해주었습니다.','published'),
('grade1-05:communicate','grade1-05:communicate','grade1','grade1-05','communicate','의사소통하다','verb','Please communicate this message to all employees.','이 메시지를 모든 직원에게 전달하시기 바랍니다.','Do you communicate well with your advisor?','지도교수님과 의사소통이 잘 되시나요?','published'),
('grade1-05:community','grade1-05:community','grade1','grade1-05','community','공동체','noun','The team is drawn from all parts of the community.','팀은 커뮤니티의 모든 부분에서 구성됩니다.','They shared a community of possessions.','그들은 소유의 공동체를 공유했습니다.','published'),
('grade1-05:complete','grade1-05:complete','grade1','grade1-05','complete','완성하다','verb','A child would complete the family.','아이는 가족을 완성할 것이다.','What you said is complete nonsense.','당신이 말한 것은 완전히 말도 안 된다.','published'),
('grade1-05:concern','grade1-05:concern','grade1','grade1-05','concern','걱정;관심','noun','The safety of the ship is the captain''s concern.','배의 안전은 선장의 관심사입니다.','She felt strong concern for those less fortunate.','그녀는 불우한 사람들에 대한 강한 관심을 느꼈습니다.','published'),
('grade1-05:condition','grade1-05:condition','grade1','grade1-05','condition','상태;조건','noun','My aunt couldn''t walk up the stairs in her condition.','이모는 그 상태로 계단을 올라갈 수 없었습니다.','A man of his condition has no place to make request.','이런 상태의 사람은 요청할 곳이 없습니다.','published'),
('grade1-05:confident','grade1-05:confident','grade1','grade1-05','confident','자신 있는','adjective','His manner is more confident these days.','요즘 그의 태도는 더욱 자신감에 차 있다.','Was confident he would win.','자신이 이길 것이라고 확신했다.','published'),
('grade1-05:connect','grade1-05:connect','grade1','grade1-05','connect','연결하다','verb','Can you connect the two loudspeakers?','스피커 두 개를 연결할 수 있나요?','I cannot connect these two pieces of evidence in my mind.','나는 내 마음 속에서 이 두 가지 증거를 연결할 수 없습니다.','published'),
('grade1-05:consider','grade1-05:consider','grade1','grade1-05','consider','고려하다','verb','I consider her to be shallow.','나는 그녀가 천박하다고 생각합니다.','Consider the possibility of moving.','이동 가능성을 고려하십시오.','published'),
('grade1-05:contain','grade1-05:contain','grade1','grade1-05','contain','포함하다','verb','I''m so excited, I can hardly contain myself!','너무 신나서 참을 수가 없어요!','Oranges contain a lot of vitamin C.','오렌지는 많은 비타민C를 함유하고 있다.','published'),
('grade1-05:control','grade1-05:control','grade1','grade1-05','control','통제하다','verb','The rebels took control of the capital.','반역자들이 수도를 점령했다.','The government tends to control the media.','정부는 매체를 조종하는 경향이 있다.','published'),
('grade1-05:convenient','grade1-05:convenient','grade1','grade1-05','convenient','편리한','adjective','A convenient excuse for not going.','안 가는 편리한 핑계.','Tom thinks the world would be much more convenient without marginalized people.','톰은 소외된 사람들이 없으면 세상이 훨씬 더 편리해질 것이라고 생각합니다.','published'),
('grade1-05:conversation','grade1-05:conversation','grade1','grade1-05','conversation','대화','noun','A queer person is not a conversation piece.','퀴어는 대화의 대상이 아닙니다.','Transgender people are human beings, not conversation pieces.','트랜스젠더는 인간이지 대화의 대상이 아닙니다.','published'),
('grade1-05:correct','grade1-05:correct','grade1','grade1-05','correct','옳은;고치다','adjective','I think your hypothesis is correct.','네 가설이 맞는 것 같아.','Please feel free to correct my mistakes.','내 실수를 바로잡아 주시기 바랍니다.','published'),
('grade1-05:courage','grade1-05:courage','grade1','grade1-05','courage','용기','noun','Tom is full of courage.','톰은 용기가 넘쳤어요.','Tom isn''t lacking in courage.','톰은 용기가 부족하지 않습니다.','published'),
('grade1-05:create','grade1-05:create','grade1','grade1-05','create','창조하다','verb','Employers don''t create work; they exploit it.','고용주는 일자리를 창출하지 않습니다. 그들은 그것을 악용합니다.','I still don''t know how to create a MediaWiki template.','나는 아직 MediaWiki 템플릿을 만드는 방법을 모릅니다.','published'),
('grade1-05:creative','grade1-05:creative','grade1','grade1-05','creative','창의적인','adjective','Novices often have more luck finding something arcane than seasoned researchers because of the power of creative thinking and serendipity.','창의적 사고와 우연의 힘 때문에 초보자는 노련한 연구자보다 신비한 것을 찾는 행운을 더 많이 누리는 경우가 많습니다.','The documentary examines the creative and commercial value of this practice, called musical sampling.','다큐멘터리는 음악 샘플링이라고 불리는 이러한 관행의 창의적이고 상업적인 가치를 조사합니다.','published'),
('grade1-05:culture','grade1-05:culture','grade1','grade1-05','culture','문화','noun','I''m headed to the lab to make sure my cell culture hasn''t died.','배양된 세포가 죽지 않았는지 확인하기 위해 연구실로 향하고 있습니다.','They''ve lost the ability to think of anything outside of their all-consuming culture war.','그들은 모든 것을 소비하는 문화 전쟁 외에는 아무것도 생각할 수 있는 능력을 상실했습니다.','published'),
('grade1-05:customer','grade1-05:customer','grade1','grade1-05','customer','고객','noun','I had to wait 20 minutes on the phone before reaching the customer service rep.','통화해서 고객 서비스 상담원에게 말하기 전까지 연결 대기 큐에서 20분이나 기다렸어야 했어.','How would you deal with an angry or irate customer?','화나거나 화난 고객을 어떻게 대할 것인가?','published'),
('grade1-05:damage','grade1-05:damage','grade1','grade1-05','damage','손상','noun','How much is the damage?','피해액은 얼마나 되나요?','Tom got out of his car to assess the damage.','Tom은 피해를 평가하기 위해 차에서 나왔습니다.','published'),
('grade1-06:danger','grade1-06:danger','grade1','grade1-06','danger','위험','noun','You are in no danger.','당신은 위험하지 않습니다.','There was widespread danger of disease.','질병의 위험이 널리 퍼져 있었습니다.','published'),
('grade1-06:decide','grade1-06:decide','grade1','grade1-06','decide','결정하다','verb','Let us know what you decide.','네가 결정한 걸 알려줘 봐.','I can''t decide whether to invest in a corporate bond or a gilt.','회사채에 투자할지, 금채에 투자할지 결정할 수 없습니다.','published'),
('grade1-06:decrease','grade1-06:decrease','grade1','grade1-06','decrease','감소하다','verb','Regular exercise can decrease the risk of disease.','규칙적인 운동은 질병의 위험을 줄일 수 있습니다.','The temperature will decrease after sunset.','일몰 이후에는 기온이 낮아지겠습니다.','published'),
('grade1-06:deep','grade1-06:deep','grade1','grade1-06','deep','깊은','adjective','Surrounded by a deep yard.','깊은 마당으로 둘러싸여 있습니다.','Hit the ball to deep center field.','공을 깊은 중앙 필드로 쳐보세요.','published'),
('grade1-06:defend','grade1-06:defend','grade1','grade1-06','defend','방어하다','verb','I have to defend myself.','나는 나 자신을 보호해야 한다.','I want to learn to defend myself.','나는 내 자신을 방어하는 법을 배우고 싶어.','published'),
('grade1-06:degree','grade1-06:degree','grade1','grade1-06','degree','정도;학위','noun','It is all a matter of degree.','그것은 모두 정도의 문제입니다.','She has two bachelor''s degrees and is studying towards a master''s degree.','그녀는 두 개의 학사 학위를 가지고 있으며 석사 학위를 위해 공부하고 있습니다.','published'),
('grade1-06:demand','grade1-06:demand','grade1','grade1-06','demand','요구하다','verb','I demand to see the manager.','나는 매니저를 만나기를 요구합니다.','I demand an immediate explanation.','즉각적인 설명을 요구합니다.','published'),
('grade1-06:depend','grade1-06:depend','grade1','grade1-06','depend','의존하다','verb','Depend on your family in times of crisis.','위기 상황에서는 가족에게 의지하세요.','We depend on the mailman to come at the usual time.','우리는 평소 시간에 오는 우체부에 의존합니다.','published'),
('grade1-06:describe','grade1-06:describe','grade1','grade1-06','describe','묘사하다','verb','I can''t describe my sadness.','나의 슬픔을 뭐라 표현할 수가 없네.','Linguistics is a science that tries to describe language.','언어학은 언어를 기술하고자 하는 학문이야.','published'),
('grade1-06:design','grade1-06:design','grade1','grade1-06','design','설계하다','verb','I do graphic design for some T-shirt sites.','저는 일부 티셔츠 사이트에서 그래픽 디자인을 하고 있습니다.','His team is working to increase the aircraft’s efficiency through its aerodynamic and structural design and reduce its operating costs.','그의 팀은 공기 역학적 및 구조적 설계를 통해 항공기의 효율성을 높이고 운영 비용을 줄이기 위해 노력하고 있습니다.','published'),
('grade1-06:detail','grade1-06:detail','grade1','grade1-06','detail','세부사항','noun','The essay contained too much detail.','에세이에 너무 많은 내용이 포함되어 있었습니다.','A detail was sent to remove the fallen trees.','쓰러진 나무를 제거하기 위해 세부 사항이 전송되었습니다.','published'),
('grade1-06:develop','grade1-06:develop','grade1','grade1-06','develop','발전시키다','verb','Children must develop a sense of right and wrong.','아이들은 옳고 그름에 대한 감각을 키워야 합니다.','Develop a passion for painting.','그림에 대한 열정을 키우십시오.','published'),
('grade1-06:difference','grade1-06:difference','grade1','grade1-06','difference','차이','noun','The difference in her is amazing.','그녀의 차이는 놀랍습니다.','His support made a real difference.','그의 지원은 정말 변화를 가져왔습니다.','published'),
('grade1-06:direction','grade1-06:direction','grade1','grade1-06','direction','방향','noun','He looked the other direction.','그는 다른 방향을 바라보았다.','He checked the direction and velocity of the wind.','그는 바람의 방향과 속도를 확인했습니다.','published'),
('grade1-06:discover','grade1-06:discover','grade1','grade1-06','discover','발견하다','verb','The story is false, so far as I can discover.','내가 아는 한 그 이야기는 거짓이다.','Here''s someone you should discover if you don''t already know him.','아직 모르는 사람이라면 꼭 알아보아야 할 사람이 있습니다.','published'),
('grade1-06:discuss','grade1-06:discuss','grade1','grade1-06','discuss','논의하다','verb','The topic is really interesting, but it''s hard to discuss.','주제는 정말 흥미롭지만 논의하기는 어렵습니다.','It''s a difficult topic to discuss.','논의하기 어려운 주제입니다.','published'),
('grade1-06:disease','grade1-06:disease','grade1','grade1-06','disease','질병','noun','The tomato plants had some kind of disease that left their leaves splotchy and fruit withered.','토마토 식물에는 잎에 얼룩이 생기고 열매가 시드는 일종의 질병이 있었습니다.','Disease is a threat to human beings.','질병은 인류에게 있어서 위협이야.','published'),
('grade1-06:divide','grade1-06:divide','grade1','grade1-06','divide','나누다','verb','Can you divide 49 by seven?','49를 7로 나눌 수 있나요?','Both of these projects are part of our efforts to bridge the digital speech divide.','이 두 프로젝트 모두 디지털 음성 격차를 해소하려는 노력의 일환입니다.','published'),
('grade1-06:domestic','grade1-06:domestic','grade1','grade1-06','domestic','국내의','adjective','Everything sounded very peaceful and domestic.','모든 것이 매우 평화롭고 가정적인 것처럼 들렸습니다.','In many languages, domestic cats are named after the "meow" sound they make.','많은 언어에서 집고양이의 이름은 그들이 내는 "야옹" 소리를 따서 명명되었습니다.','published'),
('grade1-06:doubt','grade1-06:doubt','grade1','grade1-06','doubt','의심','noun','I doubt that branch can support your weight.','그 가지가 당신의 체중을 지탱할 수 있을지 의심스럽습니다.','Like anyone who knows anything, I''m full of doubt.','무엇이든 아는 사람처럼 나도 의심이 가득합니다.','published'),
('grade1-07:dream','grade1-07:dream','grade1','grade1-07','dream','꿈','noun','I had a dream about you last night.','어젯밤에 당신에 대한 꿈을 꾸었어요.','He lives in a dream that has nothing to do with reality.','그는 현실과 아무런 관련이 없는 꿈 속에 살고 있다.','published'),
('grade1-07:earn','grade1-07:earn','grade1','grade1-07','earn','벌다','verb','To earn a spot in the top 20.','상위 20위 안에 들기 위해서는.','How much does he earn per month?','그 남자 월급이 얼마야?','published'),
('grade1-07:education','grade1-07:education','grade1','grade1-07','education','교육','noun','He received no formal education.','그는 정식 교육을 받지 못했습니다.','It was clear that he had a very broad education.','그는 매우 폭넓은 교육을 받은 것이 분명했습니다.','published'),
('grade1-07:effect','grade1-07:effect','grade1','grade1-07','effect','효과','noun','The magnetic effect was greater when the rod was lengthwise.','막대의 길이가 길수록 자기 효과가 더 커졌습니다.','She retained that bold effect in her reproductions of the original painting.','그녀는 원본 그림을 재현할 때 그 대담한 효과를 그대로 유지했습니다.','published'),
('grade1-07:effort','grade1-07:effort','grade1','grade1-07','effort','노력','noun','Made an effort to cover all the reading material.','모든 독서 자료를 다루려고 노력했습니다.','He got an A for effort.','그는 노력으로 A를 받았습니다.','published'),
('grade1-07:elderly','grade1-07:elderly','grade1','grade1-07','elderly','나이가 지긋한','adjective','Elderly residents could remember the construction of the first skyscraper.','노인들은 최초의 초고층 빌딩 건설을 기억할 것입니다.','The con artist victimizes elderly pensioners.','사기꾼은 노인 연금 수급자를 희생시킵니다.','published'),
('grade1-07:emotion','grade1-07:emotion','grade1','grade1-07','emotion','감정','noun','The left frontal lobe plays a role in controlling mood and emotion.','왼쪽 전두엽은 기분과 감정을 조절하는 역할을 합니다.','Two small, moist gray eyes, that glistened with every emotion, seemed to contradict the hard expression of the other features.','온갖 감정으로 반짝이는 작고 촉촉한 두 개의 회색 눈은 다른 이목구비의 딱딱한 표정과 모순되는 듯했다.','published'),
('grade1-07:employ','grade1-07:employ','grade1','grade1-07','employ','고용하다','verb','I mostly write free verse, but I employ meter and rhyme from time to time.','나는 주로 자유시를 쓰지만, 때때로 운율과 운율을 사용합니다.','The students were asked to employ something important.','학생들은 중요한 것을 사용하도록 요청 받았습니다.','published'),
('grade1-07:encourage','grade1-07:encourage','grade1','grade1-07','encourage','격려하다','verb','We encourage the use of bicycles in the town centre.','시내 중심가에서는 자전거 이용을 권장합니다.','That will encourage radish leaf growth instead of root development.','그러면 뿌리 발달 대신 무잎 성장이 촉진됩니다.','published'),
('grade1-07:enjoy','grade1-07:enjoy','grade1','grade1-07','enjoy','즐기다','verb','I enjoy watching children play.','나는 아이들이 노는 것을 보는 게 즐겁다.','I can''t enjoy reading without the tactile sensation of a physical book.','나는 실제 책이 주는 촉감 없이는 독서를 즐길 수 없다.','published'),
('grade1-07:enormous','grade1-07:enormous','grade1','grade1-07','enormous','거대한','adjective','Voice recognition technologies bring a human dimension to our devices, but developers need an enormous amount of voice data to build them.','음성 인식 기술은 우리 장치에 인간적인 차원을 더해 주지만 개발자는 이를 구축하기 위해 엄청난 양의 음성 데이터가 필요합니다.','This enormous longhorn beetle is found around mango and fig trees.','이 거대한 롱혼 딱정벌레는 망고와 무화과나무 주변에서 발견됩니다.','published'),
('grade1-07:enough','grade1-07:enough','grade1','grade1-07','enough','충분한','adjective','There was enough time to finish the test.','시험을 끝낼 시간은 충분했다.','The box was light enough for her to carry.','상자는 그녀가 들고 다닐 수 있을 만큼 가벼웠습니다.','published'),
('grade1-07:enter','grade1-07:enter','grade1','grade1-07','enter','들어가다','verb','I saw a man enter the room.','나는 방 안으로 들어가는 어떤 남자를 보았다.','The user must explicitly enter a value into this field.','사용자는 이 필드에 값을 명시적으로 입력해야 합니다.','published'),
('grade1-07:equal','grade1-07:equal','grade1','grade1-07','equal','동등한','adjective','All men are equal before the law.','모든 사람은 법 앞에 평등합니다.','He was equal to the task.','그는 그 일에 동등했습니다.','published'),
('grade1-07:escape','grade1-07:escape','grade1','grade1-07','escape','탈출하다','verb','Cats understandably don''t like to be in situations they can''t escape from.','고양이는 당연히 피할 수 없는 상황에 있는 것을 좋아하지 않습니다.','She could not escape with her reputation intact.','그녀는 명성을 그대로 유지한 채 탈출할 수 없었다.','published'),
('grade1-07:especially','grade1-07:especially','grade1','grade1-07','especially','특히','adverb','The library is especially quiet in the morning.','도서관은 아침에 특히 조용합니다.','I enjoy science, especially biology.','나는 과학, 특히 생물학을 좋아합니다.','published'),
('grade1-07:essential','grade1-07:essential','grade1','grade1-07','essential','필수적인','adjective','The parasympathetic nerves of a developing salivary gland innervate the salivary gland epithelium which is essential for organogenesis.','발달 중인 타액선의 부교감 신경은 기관 형성에 필수적인 타액선 상피를 자극합니다.','Thanks to the pandemic, we now know that "unskilled" workers are essential.','팬데믹 덕분에 이제 우리는 "미숙련" 근로자가 필수적이라는 것을 알고 있습니다.','published'),
('grade1-07:evidence','grade1-07:evidence','grade1','grade1-07','evidence','증거','noun','The evidence that smoking causes lung cancer is very compelling.','흡연이 폐암을 유발한다는 증거는 매우 설득력이 있습니다.','His trembling was evidence of his fear.','그의 떨림은 그의 두려움의 증거였습니다.','published'),
('grade1-07:exact','grade1-07:exact','grade1','grade1-07','exact','정확한','adjective','Hit the exact center of the target.','표적의 정확한 중앙을 명중시키십시오.','It turns out that everyone’s hair is different and that there’s no exact temperature where hair straightening becomes hair damage.','모든 사람의 머리카락이 다르며, 머리카락을 펴는 것이 머리카락 손상으로 이어지는 정확한 온도가 없다는 것이 밝혀졌습니다.','published'),
('grade1-07:examine','grade1-07:examine','grade1','grade1-07','examine','조사하다','verb','If we don''t thoroughly examine the cause of bullying, bullying will probably never go away.','우리가 따돌림의 원인을 철저히 조사하지 않는다면, 따돌림은 결코 사라지지 않을 것이다.','The students were asked to examine something important.','학생들은 중요한 것을 조사해 보라고 요청 받았습니다.','published'),
('grade1-08:excellent','grade1-08:excellent','grade1','grade1-08','excellent','훌륭한','adjective','The school has excellent teachers.','학교에는 훌륭한 선생님이 계십니다.','She had an excellent wife.','그녀에게는 훌륭한 아내가 있었습니다.','published'),
('grade1-08:except','grade1-08:except','grade1','grade1-08','except','~을 제외하고','preposition','Everyone attended the meeting except Mina.','미나를 제외한 모두가 회의에 참석했습니다.','The museum is open every day except Monday.','박물관은 월요일을 제외하고 매일 개관합니다.','published'),
('grade1-08:exchange','grade1-08:exchange','grade1','grade1-08','exchange','교환하다','verb','I''ll gladly exchange my place for yours.','기꺼이 내 자리를 당신의 자리로 바꾸겠습니다.','I''d like to exchange this shirt for one in a larger size.','이 셔츠를 더 큰 사이즈로 교환하고 싶습니다.','published'),
('grade1-08:excited','grade1-08:excited','grade1','grade1-08','excited','신이 난','adjective','He was very excited about his promotion.','그는 자신의 승진에 매우 기뻐했습니다.','The excited electrons give off light when they drop to a lower energy state.','여기된 전자는 더 낮은 에너지 상태로 떨어질 때 빛을 발산합니다.','published'),
('grade1-08:exist','grade1-08:exist','grade1','grade1-08','exist','존재하다','verb','He could barely exist on such a low wage.','그는 그렇게 낮은 임금으로는 거의 생존할 수 없었습니다.','Science fiction has undoubtedly been the inspiration for many of the technologies that exist today.','공상 과학은 의심의 여지 없이 오늘날 존재하는 많은 기술에 영감을 주었어.','published'),
('grade1-08:expect','grade1-08:expect','grade1','grade1-08','expect','기대하다','verb','I expect my students to arrive in time for their lessons.','나는 학생들이 수업 시간에 맞춰 도착하기를 기대합니다.','I expect you to wait.','네가 기다리고 있길 기대하고 있어.','published'),
('grade1-08:experience','grade1-08:experience','grade1','grade1-08','experience','경험','noun','Experience is the best teacher.','경험은 최고의 스승이다.','He had a religious experience.','그에게는 종교적인 경험이 있었습니다.','published'),
('grade1-08:experiment','grade1-08:experiment','grade1','grade1-08','experiment','실험','noun','It was an experiment in living.','그것은 생활 속의 실험이었습니다.','As an experiment he decided to grow a beard.','실험으로 그는 수염을 기르기로 결정했습니다.','published'),
('grade1-08:express','grade1-08:express','grade1','grade1-08','express','표현하다','verb','Can you express this distance in kilometers?','이 거리를 킬로미터로 표현할 수 있나요?','Many of the laboratory animals express the trait.','많은 실험실 동물이 이 특성을 표현합니다.','published'),
('grade1-08:extra','grade1-08:extra','grade1','grade1-08','extra','추가의','adjective','Found some extra change lying on the dresser.','서랍장에 여분의 잔돈이 놓여 있는 것을 발견했습니다.','I don''t mind doing some extra work, as long as I get extra pay.','나는 추가 급여를 받는 한 추가 작업을 하는 것을 꺼리지 않습니다.','published'),
('grade1-08:factor','grade1-08:factor','grade1','grade1-08','factor','요인','noun','The factor of the trading post bought the furs.','교역소의 요인이 모피를 구입했습니다.','The economy was a factor in this year''s budget figures.','경제는 올해 예산 수치의 한 요소였습니다.','published'),
('grade1-08:failure','grade1-08:failure','grade1','grade1-08','failure','실패','noun','His failure to pass the test.','그는 시험을 통과하지 못했습니다.','The surprise party was a complete failure.','깜짝 파티는 완전 실패였다.','published'),
('grade1-08:famous','grade1-08:famous','grade1','grade1-08','famous','유명한','adjective','He is a famous artist.','그는 유명한 아티스트다.','Her uncle is a famous doctor.','그녀의 삼촌은 유명한 의사입니다.','published'),
('grade1-08:feature','grade1-08:feature','grade1','grade1-08','feature','특징','noun','They ran a feature on retirement planning.','그들은 은퇴 계획에 관한 기능을 실행했습니다.','The photo editor includes a feature which allows users to add a blur effect to images.','사진 편집기에는 사용자가 이미지에 흐림 효과를 추가할 수 있는 기능이 포함되어 있습니다.','published'),
('grade1-08:feeling','grade1-08:feeling','grade1','grade1-08','feeling','감정','noun','She had a feeling of euphoria.','그녀는 행복감을 느꼈습니다.','I disliked him and the feeling was mutual.','나는 그를 싫어했고 그 느낌은 서로 같았습니다.','published'),
('grade1-08:festival','grade1-08:festival','grade1','grade1-08','festival','축제','noun','There''s a festival going on this weekend.','이번 주말에 축제가 있어요.','The 14-day festival also features classes and workshops for beginning students of the sensual dance.','14일간의 축제에는 감각적인 댄스를 처음 배우는 학생들을 위한 수업과 워크숍도 마련되어 있습니다.','published'),
('grade1-08:focus','grade1-08:focus','grade1','grade1-08','focus','집중하다','verb','Please focus on your studies and not on your hobbies.','취미보다는 공부에 집중하시기 바랍니다.','Please focus the image; we cannot enjoy the movie.','이미지의 초점을 맞추세요. 우리는 영화를 즐길 수 없습니다.','published'),
('grade1-08:foreign','grade1-08:foreign','grade1','grade1-08','foreign','외국의','adjective','Jealousy is foreign to her nature.','질투는 그녀의 본성에 이질적입니다.','Have you ever been to a foreign country?','외국에 나가본 적 있어?','published'),
('grade1-08:forget','grade1-08:forget','grade1','grade1-08','forget','잊다','verb','Don''t forget to call the chairman of the board to the meeting!','이사회 의장을 회의에 부르는 것을 잊지 마십시오!','Don''t forget to sign your name.','서명하는 것을 잊지 마세요.','published'),
('grade1-08:formal','grade1-08:formal','grade1','grade1-08','formal','공식적인','adjective','The requirement was only formal and often ignored.','요구 사항은 형식적일 뿐이며 종종 무시되었습니다.','I''d like to make a formal complaint.','정식으로 항의하고 싶습니다.','published'),
('grade1-09:frequent','grade1-09:frequent','grade1','grade1-09','frequent','빈번한','adjective','A downside to frequent flyer miles is that using them is complicated.','상용 고객 마일리지의 단점은 사용이 복잡하다는 것입니다.','The final decision seemed frequent to everyone involved.','최종 결정은 관련된 모든 사람에게 자주 발생하는 것처럼 보였습니다.','published'),
('grade1-09:friendship','grade1-09:friendship','grade1','grade1-09','friendship','우정','noun','It''s a symbol of friendship.','이건 우정의 표시야.','I hope that this is the beginning of a beautiful friendship.','이게 아름다운 우정의 시작이길 바라.','published'),
('grade1-09:future','grade1-09:future','grade1','grade1-09','future','미래','noun','No one can foretell the future.','아무도 미래를 예언할 수 없다.','We study the past for the sake of the future.','우리는 미래를 위해 과거를 공부해.','published'),
('grade1-09:general','grade1-09:general','grade1','grade1-09','general','일반적인','adjective','Bearing a general resemblance to the original.','원본과 전반적으로 유사합니다.','What excites you about medicine in general?','일반적으로 의학에서 당신을 흥분시키는 것은 무엇입니까?','published'),
('grade1-09:generation','grade1-09:generation','grade1','grade1-09','generation','세대','noun','They had to wait a generation for that prejudice to fade.','그 편견이 사라질 때까지 그들은 한 세대를 기다려야 했습니다.','If such a thing as meritocracy existed, it would be gone within a generation.','만약 능력주의라는 것이 존재한다면 그것은 한 세대 안에 사라질 것입니다.','published'),
('grade1-09:generous','grade1-09:generous','grade1','grade1-09','generous','관대한','adjective','Would he be so generous to those in need if he hadn''t experienced the devastating effects of poverty firsthand as a child?','어렸을 때 빈곤의 파괴적인 영향을 직접 경험하지 않았다면 그가 도움이 필요한 사람들에게 그토록 관대했을까요?','Tom can be overbearing, but he''s a generous man.','톰은 위압적일 수 있지만 관대한 사람입니다.','published'),
('grade1-09:global','grade1-09:global','grade1','grade1-09','global','세계적인','adjective','A variable of global scope can be referenced anywhere in the program.','전역 범위의 변수는 프로그램의 어느 곳에서나 참조될 수 있습니다.','We''re at the beginning of a global mass extinction event.','우리는 세계적인 대량 멸종 사건의 시작점에 있습니다.','published'),
('grade1-09:government','grade1-09:government','grade1','grade1-09','government','정부','noun','He had considerable experience of government.','그는 정부에 대한 상당한 경험을 가지고 있었습니다.','If the citizens must follow the law, then the government must follow the constitution.','국민이 법을 따라야 한다면 정부는 헌법을 따라야 한다.','published'),
('grade1-09:graduate','grade1-09:graduate','grade1','grade1-09','graduate','졸업하다','verb','To graduate the heat of an oven.','오븐의 열기를 졸업하려면.','We graduate from high school at eighteen.','우리는 18살에 고등학교를 졸업합니다.','published'),
('grade1-09:habit','grade1-09:habit','grade1','grade1-09','habit','습관','noun','It was their habit to dine at 7 every evening.','매일 저녁 7시에 식사하는 것이 그들의 습관이었습니다.','She had a habit twirling the ends of her hair.','그녀는 머리카락 끝을 빙빙 돌리는 버릇이 있었다.','published'),
('grade1-09:handle','grade1-09:handle','grade1','grade1-09','handle','다루다','verb','This blender can''t handle nuts.','이 믹서기는 견과류를 다룰 수 없습니다.','I can''t handle this hot weather.','이 더운 날씨를 감당할 수가 없어요.','published'),
('grade1-09:healthy','grade1-09:healthy','grade1','grade1-09','healthy','건강한','adjective','Tom is relatively fit and healthy.','톰이 상대적으로 가장 알맞고 건강하다.','I owe it to my parents that I''m so healthy.','내가 이렇게 건강한 것은 우리 부모님 덕이다.','published'),
('grade1-09:history','grade1-09:history','grade1','grade1-09','history','역사','noun','History takes the long view.','역사는 장기적인 관점을 취합니다.','History repeats itself if we don’t learn from its mistakes.','역사는 실수로부터 배우지 않으면 반복됩니다.','published'),
('grade1-09:honest','grade1-09:honest','grade1','grade1-09','honest','정직한','adjective','Worked at an honest trade.','정직한 거래에서 일했습니다.','We’re the most honest people you will ever come across.','우리는 당신이 만날 수 있는 가장 정직한 사람들입니다.','published'),
('grade1-09:honor','grade1-09:honor','grade1','grade1-09','honor','명예','noun','The crowds gave the returning general much honor and praise.','군중들은 귀환한 장군에게 많은 존경과 찬사를 보냈습니다.','He was a most perfect knight, for he had great honor and chivalry.','그는 가장 완벽한 기사였습니다. 왜냐하면 그는 큰 명예와 기사도를 갖고 있었기 때문입니다.','published'),
('grade1-09:however','grade1-09:however','grade1','grade1-09','however','그러나','adverb','The plan was difficult; however, the team completed it.','계획은 어려웠습니다. 그러나 팀은 그것을 완료했습니다.','The evidence was limited; however, it supported the main conclusion.','증거는 제한적이었습니다. 그러나 그것은 주요 결론을 뒷받침했습니다.','published'),
('grade1-09:human','grade1-09:human','grade1','grade1-09','human','인간','noun','A cat is not human.','고양이는 인간이 아니야.','This dog is almost human.','이 강아지는 거의 사람같아.','published'),
('grade1-09:humor','grade1-09:humor','grade1','grade1-09','humor','유머','noun','She didn''t appreciate my humor.','그녀는 내 유머를 좋아하지 않았습니다.','You can''t survive in the army without a sense of humor.','유머 감각 없이는 군대에서 살아남을 수 없습니다.','published'),
('grade1-09:identify','grade1-09:identify','grade1','grade1-09','identify','확인하다','verb','Can you identify the man who did this to you?','당신에게 이런 짓을 한 사람이 누구인지 알 수 있나요?','Could you identify him in a lineup?','라인업에서 그 사람을 알아볼 수 있나요?','published'),
('grade1-09:imagine','grade1-09:imagine','grade1','grade1-09','imagine','상상하다','verb','I imagine she earned a lot of money with her new novel.','나는 그녀가 새 소설로 많은 돈을 벌었다고 생각한다.','You can''t imagine how busy I was.','내가 얼마나 바빴는지 상상도 못 할 걸?','published'),
('grade1-10:immediate','grade1-10:immediate','grade1','grade1-10','immediate','즉각적인','adjective','Tom needs immediate medical attention.','톰은 즉각적인 치료가 필요합니다.','Using tiny electro-cardiogram systems, the scientists showed that being carried about led to an immediate slowing of the infant''s heart rate.','과학자들은 작은 심전도 시스템을 사용하여 아기를 안고 있으면 아기의 심장 박동이 즉각적으로 느려진다는 사실을 보여주었습니다.','published'),
('grade1-10:impact','grade1-10:impact','grade1','grade1-10','impact','영향','noun','The book had an important impact on my thinking.','그 책은 내 생각에 중요한 영향을 미쳤다.','And while many are feeling the impact of that slowdown, the region''s growing middle class is helping to act as a buffer.','그리고 많은 사람들이 경기 둔화의 영향을 느끼고 있는 반면, 지역의 성장하는 중산층은 완충 역할을 하고 있습니다.','published'),
('grade1-10:important','grade1-10:important','grade1','grade1-10','important','중요한','adjective','Recited the decree with an important air.','중요한 공기로 법령을 낭송했습니다.','I think this is important.','이건 중요한 것 같아.','published'),
('grade1-10:include','grade1-10:include','grade1','grade1-10','include','포함하다','verb','I include you in the list of culprits.','당신을 범인 목록에 포함시켰습니다.','We must include this chemical element in the group.','우리는 이 화학 원소를 그룹에 포함시켜야 합니다.','published'),
('grade1-10:increase','grade1-10:increase','grade1','grade1-10','increase','증가하다','verb','Exposure to these chemicals can increase your risk of developing cancer.','이러한 화학 물질에 노출되면 암 발병 위험이 높아질 수 있습니다.','Repaying debt leaves less money available for investment in new factories or infrastructure that could increase productivity and create jobs.','부채를 상환하면 생산성을 높이고 일자리를 창출할 수 있는 새로운 공장이나 인프라에 투자할 수 있는 자금이 줄어듭니다.','published'),
('grade1-10:independent','grade1-10:independent','grade1','grade1-10','independent','독립적인','adjective','I''ve always been an independent person.','난 전부터 항상 독립적인 사람이야.','Kabylia will soon be an independent country.','Kabylia는 곧 독립 국가가 될 것입니다.','published'),
('grade1-10:individual','grade1-10:individual','grade1','grade1-10','individual','개인','noun','The common interests of the many should outweigh the individual interest of the few.','다수의 공동 이익이 소수의 개인 이익보다 중요해야 합니다.','People can believe whatever they want as long they don’t infringe upon anyone’s individual freedom.','개인의 자유를 침해하지 않는 한 사람들은 무엇이든 믿을 수 있습니다.','published'),
('grade1-10:influence','grade1-10:influence','grade1','grade1-10','influence','영향','noun','Used her parents'' influence to get the job.','취직을 위해 부모님의 영향력을 이용했습니다.','Her wishes had a great influence on his thinking.','그녀의 소망은 그의 생각에 큰 영향을 미쳤습니다.','published'),
('grade1-10:inform','grade1-10:inform','grade1','grade1-10','inform','알리다','verb','The principles that inform modern teaching.','현대 교육에 영향을 미치는 원리.','My goal is not to convince, but to inform.','내 목표는 설득하는 것이 아니라 알리는 것입니다.','published'),
('grade1-10:information','grade1-10:information','grade1','grade1-10','information','정보','noun','The signal contained thousands of bits of information.','그 신호에는 수천 비트의 정보가 포함되어 있었습니다.','This information is very important to us.','이 정보는 우리한테 많이 중요해.','published'),
('grade1-10:inspire','grade1-10:inspire','grade1','grade1-10','inspire','영감을 주다','verb','How can video games inspire us to make better applications for e-learning?','비디오 게임은 우리가 e-러닝을 위한 더 나은 애플리케이션을 만들도록 어떻게 영감을 줄 수 있습니까?','Work should inspire creativity and innovation.','일은 창의성과 혁신을 불러일으켜야 합니다.','published'),
('grade1-10:instead','grade1-10:instead','grade1','grade1-10','instead','대신에','adverb','We took the train instead of driving.','우리는 운전하는 대신 기차를 탔습니다.','She chose to study at home instead.','그녀는 대신 집에서 공부하기로 결정했습니다.','published'),
('grade1-10:instruction','grade1-10:instruction','grade1','grade1-10','instruction','지시','noun','Our instruction was carefully programmed.','우리의 교육은 신중하게 프로그래밍되었습니다.','Instruction will be provided on how to handle difficult customers.','어려운 고객을 응대하는 방법을 지도해 드립니다.','published'),
('grade1-10:interest','grade1-10:interest','grade1','grade1-10','interest','관심','noun','They said nothing of great interest.','그들은 별로 흥미로울 만한 말을 하지 않았습니다.','Primary colors can add interest to a room.','기본 색상은 방에 흥미를 더할 수 있습니다.','published'),
('grade1-10:introduce','grade1-10:introduce','grade1','grade1-10','introduce','소개하다','verb','Let me introduce you to my friends.','내 친구들에게 소개하겠습니다.','Let me introduce our guest speaker.','초대 연사를 소개하겠습니다.','published'),
('grade1-10:invent','grade1-10:invent','grade1','grade1-10','invent','발명하다','verb','I knew I had to invent an excuse, and quickly.','나는 변명을 빨리 만들어야 한다는 것을 알았습니다.','Hitler didn''t invent the yellow star.','히틀러는 노란별을 발명한 것이 아니다.','published'),
('grade1-10:invite','grade1-10:invite','grade1','grade1-10','invite','초대하다','verb','Would you like to invite a friend?','친구를 초대해줄래?','Please invite me the next time you have a party.','다음에 파티를 여시면 저를 초대해 주세요.','published'),
('grade1-10:involve','grade1-10:involve','grade1','grade1-10','involve','포함하다;관련시키다','verb','Don''t involve me in your family affairs!','당신의 가족 문제에 나를 포함하지 마십시오!','Divide-and-conquer strategies involve pitting groups against one another.','분할 정복 전략에는 그룹을 서로 대결시키는 것이 포함됩니다.','published'),
('grade1-10:journey','grade1-10:journey','grade1','grade1-10','journey','여행','noun','My journey of dealing with grief.','슬픔을 다루는 나의 여정.','The path that will save us the journey is the one that we take directly.','우리의 여정을 구원해줄 길은 우리가 직접 택하는 길이다.','published'),
('grade1-10:judge','grade1-10:judge','grade1','grade1-10','judge','판단하다','verb','I cannot judge some works of modern art.','나는 현대 미술의 일부 작품을 판단할 수 없습니다.','The judge tried both father and son in separate trials.','판사는 아버지와 아들 모두를 별도의 재판에서 재판했습니다.','published'),
('grade1-11:knowledge','grade1-11:knowledge','grade1','grade1-11','knowledge','지식','noun','Knowledge consists in recognizing the difference between good and bad decisions.','지식은 좋은 결정과 나쁜 결정의 차이를 인식하는 것으로 구성됩니다.','A secretary should have a good knowledge of shorthand.','비서는 속기에 대한 좋은 지식을 가지고 있어야 합니다.','published'),
('grade1-11:language','grade1-11:language','grade1','grade1-11','language','언어','noun','The language introduced is standard throughout the text.','소개된 언어는 본문 전반에 걸쳐 표준입니다.','The speed with which a program can be executed depends on the language in which it is written.','프로그램이 실행되는 속도는 프로그램이 작성된 언어에 따라 다릅니다.','published'),
('grade1-11:learn','grade1-11:learn','grade1','grade1-11','learn','배우다','verb','I want to learn guitar.','기타 치는 법을 배우고 싶어.','I want to learn to drive.','운전하는 법을 배우고 싶어.','published'),
('grade1-11:legal','grade1-11:legal','grade1','grade1-11','legal','합법적인','adjective','You''re over the legal limit.','법적 한도를 초과했습니다.','You''re under the legal limit.','귀하는 법적 제한을 받고 있습니다.','published'),
('grade1-11:limit','grade1-11:limit','grade1','grade1-11','limit','한계','noun','There is no limit to human desire.','인간의 욕구는 끝이 없어.','I will never limit my shitposting.','나는 내 똥 게시를 제한하지 않을 것입니다.','published'),
('grade1-11:local','grade1-11:local','grade1','grade1-11','local','지역의','adjective','Tom checked out a book from the local library.','Tom은 지역 도서관에서 책을 대출했습니다.','Local kids were seen throwing rocks at passing motorists.','동네 아이들이 지나가는 운전자에게 돌을 던지는 모습이 목격됐다.','published'),
('grade1-11:major','grade1-11:major','grade1','grade1-11','major','주요한','adjective','His major field was mathematics.','그의 전공 분야는 수학이었다.','Unemployment is a major problem.','실업은 주요한 문제야.','published'),
('grade1-11:manage','grade1-11:manage','grade1','grade1-11','manage','관리하다','verb','How did the true fighters manage to allow themselves to be skinned by hyenas in 62''?','진정한 전사들은 어떻게 62분에 하이에나에게 피부가 벗겨질 수 있었나요?','How did I manage to trick some people into liking me?','나는 어떻게 몇몇 사람들을 속여 나를 좋아하게 만들었는가?','published'),
('grade1-11:manner','grade1-11:manner','grade1','grade1-11','manner','방식;태도','noun','His rapid manner of talking.','그의 빠른 말투.','What manner of man are you?','당신은 어떤 사람입니까?','published'),
('grade1-11:material','grade1-11:material','grade1','grade1-11','material','재료','noun','Coal is a hard black material.','석탄은 단단한 검은색 물질입니다.','The archives provided rich material for a definitive biography.','기록 보관소는 확실한 전기를 위한 풍부한 자료를 제공했습니다.','published'),
('grade1-11:measure','grade1-11:measure','grade1','grade1-11','measure','측정하다','verb','Police presence in the neighborhood was increased as a measure to deter crime.','범죄를 예방하기 위한 조치로 인근 지역에 경찰의 배치가 강화되었습니다.','Each participant wore an activity monitor to measure heart rate, perspiration and sleep quality.','각 참가자는 활동 모니터를 착용하여 심박수, 땀 및 수면의 질을 측정했습니다.','published'),
('grade1-11:memory','grade1-11:memory','grade1','grade1-11','memory','기억','noun','Search as he would, the memory was lost.','그가 원하는대로 검색하면 기억이 사라졌습니다.','He can do it from memory.','그는 기억을 통해 그것을 할 수 있습니다.','published'),
('grade1-11:mention','grade1-11:mention','grade1','grade1-11','mention','언급하다','verb','Did I mention I''m crazy?','제가 미쳤다고 말했나요?','Did I mention that I''m crazy?','제가 미쳤다고 말했나요?','published'),
('grade1-11:modern','grade1-11:modern','grade1','grade1-11','modern','현대의','adjective','Totem poles are modern rather than prehistoric.','토템 폴은 선사시대가 아닌 현대적입니다.','Their offices are in a modern skyscraper.','그들의 사무실은 현대적인 고층 건물에 있습니다.','published'),
('grade1-11:moment','grade1-11:moment','grade1','grade1-11','moment','순간','noun','The moment he arrived the party began.','그가 도착하자마자 파티가 시작됐다.','She is studying at the moment.','그녀는 지금 공부하고 있어요.','published'),
('grade1-11:natural','grade1-11:natural','grade1','grade1-11','natural','자연의','adjective','It''s the natural thing to happen.','일어나는 것은 자연스러운 일입니다.','A semiprime is a natural number that is the product of two prime numbers.','준소수는 두 소수의 곱으로 이루어진 자연수이다.','published'),
('grade1-11:necessary','grade1-11:necessary','grade1','grade1-11','necessary','필요한','adjective','If it is absolutely necessary to use public computers, you should plan ahead and forward your e-mail to a temporary, disposable account.','공용 컴퓨터를 사용해야 하는 경우 미리 계획을 세우고 임시 일회용 계정으로 이메일을 전달해야 합니다.','I assure you that isn''t necessary.','저건 필요 없다니까.','published'),
('grade1-11:notice','grade1-11:notice','grade1','grade1-11','notice','알아차리다','verb','Try to notice something new every time.','매번 새로운 것을 알아차리도록 노력하세요.','If you get sidetracked, bring yourself back as soon as you notice it.','길을 잃으면 눈치채자마자 다시 돌아오세요.','published'),
('grade1-11:object','grade1-11:object','grade1','grade1-11','object','물체;반대하다','noun','The sole object of her trip was to see her children.','그녀의 여행의 유일한 목적은 아이들을 만나는 것이었습니다.','In object-oriented programming, objects include data and define its status, its methods of operation and how it interacts with other objects.','객체 지향 프로그래밍에서 객체는 데이터를 포함하고 해당 상태, 작동 방법 및 다른 객체와 상호 작용하는 방법을 정의합니다.','published'),
('grade1-11:observe','grade1-11:observe','grade1','grade1-11','observe','관찰하다','verb','Please observe the reaction of these two chemicals.','이 두 화학물질의 반응을 관찰해 보십시오.','From this vantage point we can observe the behavior of the animals in their natural habitat.','이 유리한 지점에서 우리는 자연 서식지에서 동물의 행동을 관찰할 수 있습니다.','published'),
('grade1-12:obtain','grade1-12:obtain','grade1','grade1-12','obtain','얻다','verb','How did you obtain the visa?','비자는 어떻게 취득하셨나요?','The students were asked to obtain something important.','학생들은 중요한 것을 얻으라는 요청을 받았습니다.','published'),
('grade1-12:offer','grade1-12:offer','grade1','grade1-12','offer','제안하다','verb','What can you offer us that someone else can not?','다른 사람이 할 수 없는 것을 당신은 우리에게 제공할 수 있습니까?','Tom patiently listened to the door-to-door salesman''s entire spiel before politely declining his offer and wishing him a good day.','Tom은 그의 제안을 정중하게 거절하고 그에게 좋은 하루를 기원하기 전에 방문 판매원의 모든 말을 참을성 있게 들었습니다.','published'),
('grade1-12:opinion','grade1-12:opinion','grade1','grade1-12','opinion','의견','noun','He asked for a poll of public opinion.','그는 여론조사를 요청했다.','What''s your opinion on that?','그것에 대한 당신의 의견은 무엇인가?','published'),
('grade1-12:opportunity','grade1-12:opportunity','grade1','grade1-12','opportunity','기회','noun','Having a holiday is a great opportunity to relax.','휴가를 갖는 것은 휴식을 취할 수 있는 좋은 기회입니다.','If I get an opportunity, I will always come to the aid of somebody who needs it.','기회가 된다면 항상 도움이 필요한 누군가에게 도움을 주러 가겠습니다.','published'),
('grade1-12:ordinary','grade1-12:ordinary','grade1','grade1-12','ordinary','평범한','adjective','On an ordinary day I wake up at nine o''clock, work for six hours, and then go to the gym.','평범한 날에는 9시에 일어나서 6시간 동안 일하고 체육관에 갑니다.','That was no ordinary storm.','평범한 폭풍이 아니었다.','published'),
('grade1-12:original','grade1-12:original','grade1','grade1-12','original','원래의','adjective','The book still has its original binding.','그 책은 아직도 원래의 제본을 갖고 있습니다.','Restored the house to its original condition.','집을 원래 상태로 복원했습니다.','published'),
('grade1-12:participate','grade1-12:participate','grade1','grade1-12','participate','참여하다','verb','Many continue to participate in it by using relics of this very same genocide against its victims.','많은 사람들이 피해자들에 대한 동일한 대량 학살의 유물을 사용하여 계속해서 이에 참여하고 있습니다.','I would like to participate.','참여하고 싶습니다.','published'),
('grade1-12:particular','grade1-12:particular','grade1','grade1-12','particular','특정한','adjective','A man who wishes to make a particular woman fall in love with him.','특정 여자를 사랑하게 만들고 싶은 남자.','Very particular about how her food was prepared.','그녀의 음식이 어떻게 준비되었는지 매우 특별합니다.','published'),
('grade1-12:patient','grade1-12:patient','grade1','grade1-12','patient','인내심 있는;환자','adjective','Be patient: your friends will arrive in a few hours.','인내심을 가지세요. 친구들이 몇 시간 안에 도착할 것입니다.','Can a hospital patient with MRSA infection have visitors?','MRSA 감염 병원 환자를 방문할 수 있나요?','published'),
('grade1-12:perhaps','grade1-12:perhaps','grade1','grade1-12','perhaps','아마도','adverb','Perhaps the weather will improve this afternoon.','아마도 오늘 오후에는 날씨가 좋아질 것 같습니다.','The answer is perhaps simpler than it first appears.','대답은 아마도 처음에 나타난 것보다 더 간단할 것입니다.','published'),
('grade1-12:personal','grade1-12:personal','grade1','grade1-12','personal','개인의','adjective','I have something personal to tell you.','개인적으로 말씀드릴 게 있어요.','He has his personal bank account and she has hers.','그는 자신의 개인 은행 계좌를 가지고 있고 그녀는 그녀의 개인 은행 계좌를 가지고 있습니다.','published'),
('grade1-12:physical','grade1-12:physical','grade1','grade1-12','physical','신체의','adjective','I can''t enjoy reading without the tactile sensation of a physical book.','나는 실제 책이 주는 촉감 없이는 독서를 즐길 수 없다.','Bitcoin is fiat by definition, since it cannot be exchanged for a fixed amount of any physical resource.','비트코인은 정의상 법정화폐입니다. 왜냐하면 고정된 양의 물리적 자원과 교환될 수 없기 때문입니다.','published'),
('grade1-12:popular','grade1-12:popular','grade1','grade1-12','popular','인기 있는','adjective','Cabbage patch dolls are no longer popular.','양배추 패치 인형은 더 이상 인기가 없습니다.','Why are you so popular?','너는 어떻게 그렇게 인기가 많니?','published'),
('grade1-12:possible','grade1-12:possible','grade1','grade1-12','possible','가능한','adjective','A breakthrough may be possible next year.','내년에는 돌파구가 마련될 수도 있다.','I want a single room if possible.','되도록 일인실이면 좋겠어.','published'),
('grade1-12:practice','grade1-12:practice','grade1','grade1-12','practice','연습하다','verb','You''ll only improve if you practice.','연습을 해야만 발전할 수 있어.','Mary bought a new sport utility vehicle so that her children would be comfortable when she drove them to soccer practice.','Mary는 아이들이 축구 연습에 갈 때 편안하게 운전할 수 있도록 새로운 스포츠 유틸리티 차량을 구입했습니다.','published'),
('grade1-12:predict','grade1-12:predict','grade1','grade1-12','predict','예측하다','verb','Observers predict low turnout among a disaffected electorate squeezed by a deep economic crisis.','관찰자들은 심각한 경제 위기로 인해 불만을 품은 유권자들의 낮은 투표율을 예측합니다.','Most will laud the crackdown as steps toward transparency, fairness in business and better-run local partner companies, economists predict.','경제학자들은 대부분의 사람들이 이번 단속을 사업의 투명성, 공정성, 더 나은 운영 현지 파트너 회사를 위한 조치로 칭찬할 것이라고 예측합니다.','published'),
('grade1-12:prefer','grade1-12:prefer','grade1','grade1-12','prefer','선호하다','verb','Some people prefer camping to staying in hotels.','어떤 사람들은 호텔에 머무르는 것보다 캠핑을 선호합니다.','I prefer coffee with milk.','나는 커피에 우유를 타는 게 좋다.','published'),
('grade1-12:prevent','grade1-12:prevent','grade1','grade1-12','prevent','예방하다','verb','We must prevent the cancer from spreading.','암이 퍼지는 것을 예방해야 합니다.','The real issue is how to prevent the disease.','진짜 문제는 어떻게 질병을 막는지야.','published'),
('grade1-12:primary','grade1-12:primary','grade1','grade1-12','primary','주요한;초등의','adjective','Tom used to be a primary school teacher.','톰은 한때 초등학교 선생님이었었어.','His mother is a nursery school teacher and his father is a primary school teacher.','그의 어머니는 보육원 교사이고 그의 아버지는 초등학교 교사입니다.','published'),
('grade1-12:private','grade1-12:private','grade1','grade1-12','private','사적인','adjective','Public figures struggle to maintain a private life.','공인은 사생활을 유지하기 위해 고군분투합니다.','Each room has a private bath.','각 객실에는 전용 욕실이 있습니다.','published'),
('grade1-13:process','grade1-13:process','grade1','grade1-13','process','과정','noun','It was a process of trial and error.','그것은 시행착오의 과정이었습니다.','The progress bars indicate how far each language is in the process of website localization and sentence collection.','진행률 표시줄은 각 언어가 웹사이트 현지화 및 문장 수집 과정에서 어느 정도 진행되고 있는지를 나타냅니다.','published'),
('grade1-13:produce','grade1-13:produce','grade1','grade1-13','produce','생산하다','verb','The tree would not produce fruit.','그 나무는 열매를 맺지 못할 것이다.','We produce more cars than we can sell.','우리는 판매할 수 있는 것보다 더 많은 자동차를 생산합니다.','published'),
('grade1-13:protect','grade1-13:protect','grade1','grade1-13','protect','보호하다','verb','You have to wear a helmet to protect your head.','머리 보호를 위해서 헬멧을 써야 한다.','Cats protect me from the shadow people.','고양이는 그림자 사람들로부터 나를 보호합니다.','published'),
('grade1-13:provide','grade1-13:provide','grade1','grade1-13','provide','제공하다','verb','It is difficult to provide for my family working on minimum wage.','최저임금으로 일하는 가족을 부양하기가 어렵습니다.','Don''t bother bringing equipment, as we will provide it.','장비는 저희가 제공해드리니 굳이 가져오지 마세요.','published'),
('grade1-13:quality','grade1-13:quality','grade1','grade1-13','quality','품질','noun','The quality of mercy is not strained.','자비의 질은 긴장되지 않습니다.','The quality of students has risen.','학생들의 질이 높아졌습니다.','published'),
('grade1-13:realize','grade1-13:realize','grade1','grade1-13','realize','깨닫다','verb','Does she realize how important this decision is?','그녀는 이 결정이 얼마나 중요한지 깨닫고 있나요?','I didn''t realize you had more comments to make.','나는 당신이 더 많은 의견을 제시해야 한다는 것을 몰랐습니다.','published'),
('grade1-13:reason','grade1-13:reason','grade1','grade1-13','reason','이유','noun','The reason that war was declared.','전쟁이 선포된 이유.','The reason a steady state was never reached was that the back pressure built up too slowly.','정상 상태에 도달하지 못한 이유는 배압이 너무 느리게 형성되었기 때문입니다.','published'),
('grade1-13:receive','grade1-13:receive','grade1','grade1-13','receive','받다','verb','These aspects of civilization do not find expression or receive an interpretation.','문명의 이러한 측면은 표현되거나 해석되지 않습니다.','Did you receive my message?','내 메세지 받았어?','published'),
('grade1-13:recommend','grade1-13:recommend','grade1','grade1-13','recommend','추천하다','verb','The instructions recommend that you only use distilled water in this iron.','지침에서는 이 다리미에 증류수만 사용할 것을 권장합니다.','Since the stakes are high, I''d like to recommend a belt-and-suspenders approach.','위험이 높기 때문에 벨트와 멜빵 접근 방식을 권장하고 싶습니다.','published'),
('grade1-13:reduce','grade1-13:reduce','grade1','grade1-13','reduce','줄이다','verb','Reduce your daily fat intake.','일일 지방 섭취량을 줄이세요.','Reduce a problem to a single question.','문제를 하나의 질문으로 축소하세요.','published'),
('grade1-13:relationship','grade1-13:relationship','grade1','grade1-13','relationship','관계','noun','He didn''t want his wife to know of the relationship.','그는 아내가 그 관계를 알기를 원하지 않았습니다.','They have been in a relationship for ten years, but have never married.','그들은 10년 동안 연애를 해왔지만 한 번도 결혼한 적이 없습니다.','published'),
('grade1-13:remain','grade1-13:remain','grade1','grade1-13','remain','남아 있다','verb','He will leave his name, he will remain forever, for eternity.','그는 자신의 이름을 남기고 영원히 남을 것입니다.','It did not remain attached neither to the skin nor to the carcass.','그것은 피부나 시체에 붙어 있지 않았습니다.','published'),
('grade1-13:remove','grade1-13:remove','grade1','grade1-13','remove','제거하다','verb','Remove the dirty dishes from the table.','테이블에서 더러운 접시를 제거하십시오.','Remove the troops to the forest surrounding the city.','도시를 둘러싼 숲으로 병력을 이동시키세요.','published'),
('grade1-13:repair','grade1-13:repair','grade1','grade1-13','repair','수리하다','verb','Treat your trip as a remote backcountry trip: there is limited water infrastructure, variable weather, and no repair services or materials.','여행을 외딴 오지 여행으로 생각하십시오. 물 인프라가 제한되어 있고 날씨가 다양하며 수리 서비스나 자재가 없습니다.','Surgeons are using this technique to remove diseased gall bladders and spleens, to perform hysterectomies and to repair hernias and colons.','외과의사는 이 기술을 사용하여 병든 담낭과 비장을 제거하고, 자궁적출술을 시행하고, 탈장과 결장을 치료합니다.','published'),
('grade1-13:repeat','grade1-13:repeat','grade1','grade1-13','repeat','반복하다','verb','Could you please repeat that?','다시 한번 말씀해 주시겠어요?','How many times do I need to repeat it?','몇 번을 반복해야 해?','published'),
('grade1-13:replace','grade1-13:replace','grade1','grade1-13','replace','교체하다','verb','We need to replace the secretary that left a month ago.','한 달 전에 떠난 비서를 교체해야 합니다.','The insurance will replace the lost income.','보험은 손실된 수입을 대체할 것입니다.','published'),
('grade1-13:research','grade1-13:research','grade1','grade1-13','research','연구','noun','Their pottery deserves more research than it has received.','그들의 도자기는 지금까지 받아온 것보다 더 많은 연구를 받을 가치가 있습니다.','Tom works in research and development.','톰은 연구 개발을 하고 있어요.','published'),
('grade1-13:respect','grade1-13:respect','grade1','grade1-13','respect','존경하다','verb','I want to be a leader that people can respect.','난 사람들이 존경할 수 있는 지도자가 되고 싶어.','He has absolutely no respect for other people''s feelings.','그는 타인의 기분은 전혀 존중하지 않는다.','published'),
('grade1-13:responsible','grade1-13:responsible','grade1','grade1-13','responsible','책임이 있는','adjective','The captain is responsible for the ship''s safety.','선장은 배의 안전을 책임집니다.','The cabinet is responsible to the parliament.','내각은 의회에 대해 책임을 진다.','published'),
('grade1-13:result','grade1-13:result','grade1','grade1-13','result','결과','noun','He computed the result to four decimal places.','그는 결과를 소수점 이하 네 자리까지 계산했습니다.','Two things result from this fact.','이 사실로 인해 두 가지 결과가 발생합니다.','published'),
('grade1-14:review','grade1-14:review','grade1','grade1-14','review','검토하다','verb','We need to review the case.','우리는 그 사건을 검토할 필요가 있다.','Upon review it looks like I was overcharged for this.','검토해 보니 이에 대해 과다 청구된 것 같습니다.','published'),
('grade1-14:risk','grade1-14:risk','grade1','grade1-14','risk','위험','noun','Children who spend more time outdoors have a lower risk of myopia.','야외에서 더 많은 시간을 보내는 어린이는 근시 발병 위험이 낮습니다.','Those who feed on waiting risk starving.','기다림에 만족하는 사람들은 굶주릴 위험이 있습니다.','published'),
('grade1-14:role','grade1-14:role','grade1','grade1-14','role','역할','noun','What is your role on the team?','팀에서 당신의 역할은 무엇입니까?','You need to accept your role.','넌 너의 역할을 받아들일 필요가 있어.','published'),
('grade1-14:satisfy','grade1-14:satisfy','grade1','grade1-14','satisfy','만족시키다','verb','While sowing, the peasants said: “O earth, may you satisfy the plow and the sack of seed.".','씨를 뿌리는 동안 농부들은 이렇게 말했습니다. “오 땅이여, 쟁기와 씨앗 부대를 만족시켜 주소서.”','They don''t satisfy me at all.','그들은 나를 전혀 만족시키지 못합니다.','published'),
('grade1-14:save','grade1-14:save','grade1','grade1-14','save','구하다;저축하다','verb','Can you save one of those donuts for me?','저 도넛들 중 하나는 남겨줄 수 있어?','We used the computer in order to save time.','우린 시간을 아끼기 위해서 컴퓨터를 썼어.','published'),
('grade1-14:science','grade1-14:science','grade1','grade1-14','science','과학','noun','My favorite subjects at school are science, mathematics, and history.','제가 학교에서 가장 좋아하는 과목은 과학, 수학, 역사입니다.','She has to study science.','그 사람은 과학을 공부해야 해.','published'),
('grade1-14:select','grade1-14:select','grade1','grade1-14','select','선택하다','verb','Making it possible to select hiragana transcriptions with the mouse would be very helpful to people who haven''t mastered hiragana, like myself.','히라가나 표기를 마우스로 선택할 수 있게 하면 저처럼 히라가나를 익히지 못한 사람에게도 큰 도움이 될 것입니다.','Select the statements which are observations rather than inferences.','추론이 아닌 관찰에 해당하는 진술을 선택하세요.','published'),
('grade1-14:service','grade1-14:service','grade1','grade1-14','service','서비스','noun','He did them a service.','그는 그들에게 봉사를 했습니다.','He retired after 30 years of service.','그는 30년간의 근무를 마치고 은퇴했습니다.','published'),
('grade1-14:share','grade1-14:share','grade1','grade1-14','share','공유하다','verb','I''d like to share this idea with you.','나는 이 아이디어를 여러분과 공유하고 싶습니다.','Would you guys like to share an orange?','오렌지 하나 나눠 먹을래?','published'),
('grade1-14:similar','grade1-14:similar','grade1','grade1-14','similar','비슷한','adjective','Similar things happened in other countries.','다른 나라에서도 비슷한 일이 일어났습니다.','I was having similar feelings.','저도 비슷한 감정을 갖고 있었어요.','published'),
('grade1-14:simple','grade1-14:simple','grade1','grade1-14','simple','간단한','adjective','The simple passage of time was enough.','단순한 시간의 흐름이면 충분했다.','I removed the tag "simple past," which seemed inappropriate.','부적절해 보이는 ''단순 과거'' 태그를 삭제했습니다.','published'),
('grade1-14:social','grade1-14:social','grade1','grade1-14','social','사회의','adjective','A human being is a social animal.','인간은 사회적 동물이다.','Made fun of her being so social and high-toned.','그녀가 너무 사교적이고 고조된 성격을 가지고 있다는 것을 놀렸습니다.','published'),
('grade1-14:society','grade1-14:society','grade1','grade1-14','society','사회','noun','They formed a small lunch society.','그들은 작은 점심 모임을 형성했습니다.','He enjoyed the society of his friends.','그는 친구들과 어울리는 것을 즐겼습니다.','published'),
('grade1-14:solution','grade1-14:solution','grade1','grade1-14','solution','해결책','noun','He used a solution of peroxide and water.','그는 과산화물과 물의 용액을 사용했습니다.','They were trying to find a peaceful solution.','그들은 평화로운 해결책을 찾으려고 노력하고 있었습니다.','published'),
('grade1-14:source','grade1-14:source','grade1','grade1-14','source','원천;출처','noun','Linux is open source software.','리눅스는 오픈 소스 소프트웨어야.','All of my software is open source.','내 소프트웨어들은 전부 오픈 소스야.','published'),
('grade1-14:specific','grade1-14:specific','grade1','grade1-14','specific','구체적인','adjective','Quinine is highly specific for malaria.','퀴닌은 말라리아에 매우 특이적입니다.','A specific stain is one having a specific affinity for particular structural elements.','특정 얼룩은 특정 구조 요소에 대해 특정한 친화력을 갖는 얼룩입니다.','published'),
('grade1-14:standard','grade1-14:standard','grade1','grade1-14','standard','기준','noun','Right-wing ideologues are quick to point out the pathology of gender dysphoria but slow to acknowledge its standard treatment, gender transition.','우익 이념가들은 성별위화감의 병리를 빠르게 지적하지만 표준 치료법인 성별 전환을 인정하는 데는 느립니다.','A standard byte is eight bits.','표준 바이트는 8비트입니다.','published'),
('grade1-14:state','grade1-14:state','grade1','grade1-14','state','상태;진술하다','noun','His state is in the deep south.','그의 주는 남쪽 깊은 곳에 있다.','The state has lowered its income tax.','주에서는 소득세를 인하했습니다.','published'),
('grade1-14:stress','grade1-14:stress','grade1','grade1-14','stress','스트레스','noun','He put the stress on the wrong syllable.','그는 잘못된 음절에 강세를 두었습니다.','The stress was more on accuracy than on speed.','속도보다는 정확성에 더 중점을 두었습니다.','published'),
('grade1-14:subject','grade1-14:subject','grade1','grade1-14','subject','주제;과목','noun','He didn''t want to discuss that subject.','그는 그 주제에 대해 논의하고 싶지 않았습니다.','A moving picture of a train is more dramatic than a still picture of the same subject.','기차를 찍은 동영상은 같은 피사체를 찍은 정지 사진보다 더 드라마틱합니다.','published'),
('grade1-15:success','grade1-15:success','grade1','grade1-15','success','성공','noun','Let''s call heads a success and tails a failure.','앞면이 성공이고 뒷면이 실패라고 가정해 보겠습니다.','His success in the marathon was unexpected.','마라톤에서의 그의 성공은 예상치 못한 일이었습니다.','published'),
('grade1-15:suggest','grade1-15:suggest','grade1','grade1-15','suggest','제안하다','verb','Our best pictures of the human mind suggest that we don''t plop our mental activities into single, ordered boxes.','인간의 마음에 대한 가장 좋은 그림은 우리의 정신적 활동을 하나의 질서 있는 상자에 넣지 않는다는 것을 암시합니다.','The dagger-like fangs of the extinct saber toothed cat suggest that it was an ambush hunter.','멸종된 검치호의 단검 같은 송곳니는 그것이 매복 사냥꾼이었음을 암시합니다.','published'),
('grade1-15:support','grade1-15:support','grade1','grade1-15','support','지원하다','verb','He does not support his natural children.','그는 친자녀를 부양하지 않습니다.','Sure they sell the product, but do they support it?','물론 그들은 제품을 판매하지만 지원합니까?','published'),
('grade1-15:system','grade1-15:system','grade1','grade1-15','system','체계','noun','He bought a new stereo system.','그는 새로운 스테레오 시스템을 구입했습니다.','The system consists of a motor and a small computer.','시스템은 모터와 소형 컴퓨터로 구성됩니다.','published'),
('grade1-15:talent','grade1-15:talent','grade1','grade1-15','talent','재능','noun','He has a real talent for drawing.','그는 그림에 진정한 재능을 가지고 있습니다.','The director searched their talent pool to fill the new opening.','감독은 새로운 자리를 채우기 위해 인재 풀을 검색했습니다.','published'),
('grade1-15:technology','grade1-15:technology','grade1','grade1-15','technology','기술','noun','We believe that large, publicly available voice datasets will foster innovation and healthy commercial competition in machine-learning based speech technology.','우리는 공개적으로 사용 가능한 대규모 음성 데이터 세트가 기계 학습 기반 음성 기술의 혁신과 건전한 상업적 경쟁을 촉진할 것이라고 믿습니다.','Technology has not, as predicted, made it easier for leftists.','기술은 예상한 대로 좌파의 삶을 더 쉽게 만들지 못했습니다.','published'),
('grade1-15:temporary','grade1-15:temporary','grade1','grade1-15','temporary','일시적인','adjective','Employed on a temporary basis.','임시 고용되었습니다.','I assure you this is only temporary.','이건 단지 임시방편이라니까.','published'),
('grade1-15:tradition','grade1-15:tradition','grade1','grade1-15','tradition','전통','noun','What''s your favorite family tradition?','당신이 가장 좋아하는 가족 전통은 무엇입니까?','What is your favorite family holiday tradition?','당신이 가장 좋아하는 가족 명절 전통은 무엇입니까?','published'),
('grade1-15:transport','grade1-15:transport','grade1','grade1-15','transport','운송하다','verb','To transport goods; to transport troops.','물품을 운송하기 위해; 군대를 수송하기 위해.','How do I organise transport to and from hospital?','병원을 오가는 교통편을 어떻게 준비합니까?','published'),
('grade1-15:trust','grade1-15:trust','grade1','grade1-15','trust','신뢰하다','verb','I trust you will behave better from now on.','나는 당신이 이제부터 더 잘 행동할 것이라고 믿습니다.','I don''t know who to trust.','나는 누구를 믿어야 할 지 모른다.','published'),
('grade1-15:unique','grade1-15:unique','grade1','grade1-15','unique','독특한','adjective','Bach was unique in his handling of counterpoint.','바흐는 대위법을 다루는 데 있어서 독특했습니다.','Certain types of problems have unique solutions.','특정 유형의 문제에는 고유한 해결책이 있습니다.','published'),
('grade1-15:universe','grade1-15:universe','grade1','grade1-15','universe','우주','noun','They study the evolution of the universe.','그들은 우주의 진화를 연구합니다.','Have you ever wondered if our universe is just a simulated political satire of one that actually exists?','우리 우주가 실제로 존재하는 우주를 정치적으로 풍자한 시뮬레이션일 뿐인지 궁금해 본 적이 있나요?','published'),
('grade1-15:useful','grade1-15:useful','grade1','grade1-15','useful','유용한','adjective','The girl felt motherly and useful.','그 소녀는 어머니 같고 유용하다고 느꼈습니다.','This is a very useful tool.','이건 아주 유용한 도구야.','published'),
('grade1-15:various','grade1-15:various','grade1','grade1-15','various','다양한','adjective','His disguises are many and various.','그의 변장은 많고 다양합니다.','Various experiments have failed to disprove the theory.','다양한 실험이 이론을 반증하는 데 실패했습니다.','published'),
('grade1-15:volunteer','grade1-15:volunteer','grade1','grade1-15','volunteer','자원봉사자','noun','He''d gone as a volunteer to help build a simple mud dam needed to trap monsoonal water for cattle.','그는 소를 위해 몬순 물을 가두는 데 필요한 간단한 진흙 댐 건설을 돕기 위해 자원 봉사자로 나섰습니다.','Does your volunteer work bring you satisfaction?','당신의 자원봉사 활동이 당신에게 만족을 가져다 주나요?','published'),
('grade1-15:warn','grade1-15:warn','grade1','grade1-15','warn','경고하다','verb','I warn you against false assumptions.','잘못된 가정에 대해 경고합니다.','Don''t let me catch you running in the corridor again, I warn you.','다시는 복도에서 달리는 모습을 볼 수 없도록 경고합니다.','published'),
('grade1-15:wealth','grade1-15:wealth','grade1','grade1-15','wealth','부','noun','Great wealth is not a sign of great intelligence.','큰 부는 큰 지능의 표시가 아닙니다.','She has a wealth of talent.','그녀는 풍부한 재능을 가지고 있습니다.','published'),
('grade1-15:weather','grade1-15:weather','grade1','grade1-15','weather','날씨','noun','They were hoping for good weather.','그들은 좋은 날씨를 기대하고 있었습니다.','Every day we have weather conditions and yesterday was no exception.','매일 날씨가 좋지 않으며 어제도 예외는 아니었습니다.','published'),
('grade1-15:worth','grade1-15:worth','grade1','grade1-15','worth','가치 있는','adjective','Silver is worth less than gold.','은이 금보다 가치가 낮아.','This is a battle worth fighting.','이건 싸울 가치가 있는 결투야.','published'),
('grade1-15:youth','grade1-15:youth','grade1','grade1-15','youth','청소년기','noun','Youth everywhere rises in revolt.','곳곳에서 젊은이들이 반란을 일으키고 있습니다.','Her youth and beauty attracted him to her.','그녀의 젊음과 아름다움은 그를 매료시켰습니다.','published'),
('grade2-01:abandon','grade2-01:abandon','grade2','grade2-01','abandon','버리다','verb','Some say hundreds of people drowned in the deluge because they would not abandon their pets.','어떤 사람들은 애완동물을 버리지 않았기 때문에 수백 명이 홍수에 빠져 익사했다고 말합니다.','The leader called on both sides to ''abandon old hatreds and meet their responsibility toward peace.''.','지도자는 양측에 ''오래된 증오를 버리고 평화를 향한 책임을 다하라''고 촉구했습니다.','published'),
('grade2-01:abolish','grade2-01:abolish','grade2','grade2-01','abolish','폐지하다','verb','The city plans to abolish the outdated rule.','시는 낡은 규정을 폐지할 계획이다.','Many students want the school to abolish the unnecessary fee.','많은 학생들은 학교가 불필요한 수업료를 폐지하길 원합니다.','published'),
('grade2-01:abstract','grade2-01:abstract','grade2','grade2-01','abstract','추상적인','adjective','Online racists are apt to describe their activity in the most abstract possible terms, hoping no one will look further into it.','온라인 인종차별주의자는 누구도 더 자세히 조사하지 않기를 바라면서 자신의 활동을 가장 추상적인 용어로 설명하는 경향이 있습니다.','In the laboratory there is a piece of abstract art that is composed of images of neuron networks, showing their vast complexity.','실험실에는 뉴런 네트워크의 이미지로 구성된 추상 미술 작품이 있는데, 이는 그 엄청난 복잡성을 보여줍니다.','published'),
('grade2-01:accelerate','grade2-01:accelerate','grade2','grade2-01','accelerate','가속하다','verb','Warm temperatures can accelerate plant growth.','따뜻한 온도는 식물 성장을 가속화할 수 있습니다.','The new technology may accelerate the research process.','새로운 기술은 연구 과정을 가속화할 수 있습니다.','published'),
('grade2-01:accommodate','grade2-01:accommodate','grade2','grade2-01','accommodate','수용하다','verb','Can you accommodate me with a rental car?','렌트카로 저를 수용할 수 있나요?','This hotel can accommodate 250 guests.','이 호텔은 250명을 수용할 수 있습니다.','published'),
('grade2-01:accomplish','grade2-01:accomplish','grade2','grade2-01','accomplish','달성하다','verb','To accomplish a design, an object, a promise.','디자인, 목적, 약속을 달성하기 위해.','I can''t believe such a lazy man will accomplish his job!','이렇게 게으른 사람이 자기 일을 해낸다니 믿을 수가 없어요!','published'),
('grade2-01:accumulate','grade2-01:accumulate','grade2','grade2-01','accumulate','축적하다','verb','Plastics remain in the ecosystem for a long time and not only contain chemicals, but also adsorb other contaminants and accumulate them.','플라스틱은 오랫동안 생태계에 남아 화학물질을 함유하고 있을 뿐만 아니라 다른 오염물질을 흡착하여 축적하기도 합니다.','Local business owners clean the beach each morning, but the trash begins to accumulate shortly after.','지역 사업주들은 매일 아침 해변을 청소하지만 얼마 지나지 않아 쓰레기가 쌓이기 시작합니다.','published'),
('grade2-01:accuse','grade2-01:accuse','grade2','grade2-01','accuse','비난하다','verb','The same people who falsely accuse immigrants of spreading disease are arguing for their own inalienable right to spread disease.','이민자들이 질병을 퍼뜨린다고 거짓 비난을 하는 사람들은 질병을 퍼뜨릴 수 있는 자신들의 양도할 수 없는 권리를 주장하고 있습니다.','You accuse me of impropriety?','당신은 나를 부적절하다고 비난합니까?','published'),
('grade2-01:acquire','grade2-01:acquire','grade2','grade2-01','acquire','획득하다','verb','You can''t acquire a language without consuming it.','언어를 소비하지 않고는 습득할 수 없습니다.','The students were asked to acquire something important.','학생들은 중요한 것을 얻으라는 요청을 받았습니다.','published'),
('grade2-01:activate','grade2-01:activate','grade2','grade2-01','activate','활성화하다','verb','Some states could activate their anti-abortion laws immediately, with others following shortly thereafter.','일부 주에서는 낙태 방지법을 즉시 활성화할 수 있고, 다른 주에서는 곧 뒤따를 수도 있습니다.','The team may activate the proposal after careful review.','팀은 신중하게 검토한 후 제안을 활성화할 수 있습니다.','published'),
('grade2-01:addiction','grade2-01:addiction','grade2','grade2-01','addiction','중독','noun','Addiction is not a personal failing but an aspect of an exploitative system.','중독은 개인적인 실패가 아니라 착취적인 시스템의 한 측면입니다.','It''s a bad addiction and I need to quit for good.','그것은 나쁜 중독이고 영원히 끊어야합니다.','published'),
('grade2-01:adjust','grade2-01:adjust','grade2','grade2-01','adjust','조정하다','verb','We must adjust to the bad economic situation.','우리는 나쁜 경제 상황에 적응해야 합니다.','The students were asked to adjust something important.','학생들은 중요한 것을 조정하라는 요청을 받았습니다.','published'),
('grade2-01:administer','grade2-01:administer','grade2','grade2-01','administer','관리하다','verb','A nurse will administer the medicine at noon.','정오에 간호사가 약을 투여할 것입니다.','The committee was appointed to administer the scholarship program.','장학금 프로그램을 관리하기 위해 위원회가 임명되었습니다.','published'),
('grade2-01:admission','grade2-01:admission','grade2','grade2-01','admission','입장;인정','noun','The surgery was performed on his second admission to the clinic.','수술은 두 번째 병원에 입원했을 때 시행되었습니다.','Some of them required intubation and admission to the intensive care unit.','그들 중 일부는 삽관과 중환자실 입원이 필요했습니다.','published'),
('grade2-01:adopt','grade2-01:adopt','grade2','grade2-01','adopt','채택하다','verb','If you wouldn''t support your kid if they came out as gay, you shouldn''t adopt.','자녀가 동성애자라고 커밍아웃하더라도 지지하지 않으려면 입양해서는 안 됩니다.','The team may adopt the proposal after careful review.','팀은 신중한 검토를 거쳐 제안을 채택할 수 있습니다.','published'),
('grade2-01:advocate','grade2-01:advocate','grade2','grade2-01','advocate','옹호하다','verb','I like trees, but I do not advocate living in them.','나는 나무를 좋아하지만 나무 속에서 사는 것을 옹호하지는 않습니다.','Torres promised to reactivate the economy, tackle the country''s security situation, advocate for those at risk and run an efficient government.','토레스는 경제를 재가동하고 국가의 안보 상황을 해결하며 위험에 처한 사람들을 옹호하고 효율적인 정부를 운영하겠다고 약속했습니다.','published'),
('grade2-01:affordable','grade2-01:affordable','grade2','grade2-01','affordable','가격이 알맞은','adjective','Abdallah is known for being the most honest, reliable, and affordable repairman in his neighborhood and nearby villages.','압달라는 자신의 동네와 인근 마을에서 가장 정직하고 신뢰할 수 있으며 저렴한 수리공으로 알려져 있습니다.','There''s a shortage of affordable housing.','저렴한 주택이 부족합니다.','published'),
('grade2-01:aggressive','grade2-01:aggressive','grade2','grade2-01','aggressive','공격적인','adjective','He was aggressive and imperious; positive in his convictions.','그는 공격적이고 오만한 사람이었습니다. 그의 신념에 긍정적이다.','Yellow jackets are more aggressive than hornets.','노란색 재킷은 말벌보다 더 공격적입니다.','published'),
('grade2-01:allergy','grade2-01:allergy','grade2','grade2-01','allergy','알레르기','noun','The universe is an allergy.','우주는 알레르기입니다.','Cat allergy sufferers usually rely on antihistamines, which have side effects such as drowsiness.','고양이 알레르기 환자는 대개 항히스타민제에 의존하는데, 이는 졸음 등의 부작용이 있습니다.','published'),
('grade2-01:alter','grade2-01:alter','grade2','grade2-01','alter','바꾸다','verb','I asked an escobar to go get me something; he brought me his alter ego.','나는 escobar에게 가서 뭔가를 사달라고 요청했습니다. 그는 나에게 자신의 분신을 가져왔습니다.','If we alter the construction of such sentences, the missing antecedent is often restored.','그러한 문장의 구성을 변경하면 누락된 선행사가 복원되는 경우가 많습니다.','published'),
('grade2-02:ambassador','grade2-02:ambassador','grade2','grade2-02','ambassador','대사','noun','An ambassador of good will.','선의의 대사.','The ambassador answered every question clearly.','대사는 모든 질문에 명확하게 대답했습니다.','published'),
('grade2-02:amend','grade2-02:amend','grade2','grade2-02','amend','수정하다','verb','The committee voted to amend the existing law.','위원회는 기존 법률을 개정하기로 투표했습니다.','Please amend the report before submitting it.','보고서를 제출하기 전에 수정하시기 바랍니다.','published'),
('grade2-02:analytical','grade2-02:analytical','grade2','grade2-02','analytical','분석적인','adjective','Each observatory would be equipped with the latest environmental sensors and monitoring instruments, plus a variety of analytical tools.','각 관측소에는 최신 환경 센서 및 모니터링 장비와 다양한 분석 도구가 장착됩니다.','The reviewers considered the final result analytical.','검토자들은 최종 결과가 분석적이라고 생각했습니다.','published'),
('grade2-02:anticipate','grade2-02:anticipate','grade2','grade2-02','anticipate','예상하다','verb','Aid organizations anticipate continued flooding will displace about 200,000 people and affect the lives of 485,000 people.','구호단체들은 지속적인 홍수로 인해 약 20만명의 이재민이 발생하고 485,000명의 삶에 영향을 미칠 것으로 예상하고 있습니다.','The students were asked to anticipate something important.','학생들은 중요한 것을 예상하도록 요청 받았습니다.','published'),
('grade2-02:apparent','grade2-02:apparent','grade2','grade2-02','apparent','명백한','adjective','The effects of the drought are apparent to anyone who sees the parched fields.','가뭄의 영향은 메마른 들판을 보는 사람이라면 누구나 명백히 알 수 있습니다.','For all his apparent wealth he had no money to pay the rent.','겉으로 보기에는 재산이 많아 보였지만 집세를 낼 돈이 없었습니다.','published'),
('grade2-02:applicant','grade2-02:applicant','grade2','grade2-02','applicant','지원자','noun','Having found, as I do that the restrictions imposed on the applicant are unlawful, it is hereby ordered that they are lifted.','신청자에게 부과된 제한 사항이 불법임을 확인하여 해당 제한 사항을 해제하도록 명령합니다.','He says most U.S. colleges and universities often base their admissions decisions on an applicant’s test results and school work.','그는 대부분의 미국 대학이 지원자의 시험 결과와 학업을 토대로 입학 결정을 내리는 경우가 많다고 말합니다.','published'),
('grade2-02:appoint','grade2-02:appoint','grade2','grade2-02','appoint','임명하다','verb','The board will appoint a new director next month.','이사회는 다음 달 새 이사를 임명할 예정이다.','They decided to appoint Mina as team leader.','그들은 미나를 팀 리더로 임명하기로 결정했습니다.','published'),
('grade2-02:architect','grade2-02:architect','grade2','grade2-02','architect','건축가','noun','Plato made the causes of things to be matter, ideas, and an efficient architect.','플라톤은 사물의 원인을 물질, 아이디어, 효율적인 건축가로 만들었습니다.','Tom said he wanted to be an architect.','톰은 자신이 건축가가 되고 싶었다고 말했다.','published'),
('grade2-02:argument','grade2-02:argument','grade2','grade2-02','argument','논증;논쟁','noun','It was a strong argument that his hypothesis was true.','그의 가설이 사실이라는 강력한 주장이었습니다.','They were involved in a violent argument.','그들은 폭력적인 논쟁에 연루되었습니다.','published'),
('grade2-02:arithmetic','grade2-02:arithmetic','grade2','grade2-02','arithmetic','산수','noun','Basic arithmetic is essential for managing a budget.','예산을 관리하려면 기본적인 연산이 필수적입니다.','The child practiced arithmetic with simple number problems.','아이는 간단한 숫자 문제로 산수를 연습했습니다.','published'),
('grade2-02:artificial','grade2-02:artificial','grade2','grade2-02','artificial','인공적인','adjective','That artificial humility that her husband hated.','남편이 싫어했던 그 인위적인 겸손.','A mind-controlled artificial hand with near-natural dexterity is very close to reality.','거의 자연스러운 손재주를 지닌 마인드 컨트롤 인공 손은 현실에 매우 가깝습니다.','published'),
('grade2-02:assert','grade2-02:assert','grade2','grade2-02','assert','주장하다','verb','Women should assert themselves more!','여자들은 좀 더 자신을 주장해야 해요!','The team may assert the proposal after careful review.','팀은 신중한 검토 후 제안을 주장할 수 있습니다.','published'),
('grade2-02:assign','grade2-02:assign','grade2','grade2-02','assign','배정하다','verb','Did she assign any homework?','그녀가 숙제를 내줬나요?','You can''t assign a string to a variable of type integer.','정수 유형의 변수에는 문자열을 할당할 수 없습니다.','published'),
('grade2-02:association','grade2-02:association','grade2','grade2-02','association','협회;연관','noun','You cannot be convicted of criminal guilt by association.','협회에 의해 형사 유죄 판결을 받을 수 없습니다.','His association of his father with being beaten was too strong to break.','그의 아버지와 구타당했다는 그의 연관성은 너무 강해서 깨뜨릴 수 없었습니다.','published'),
('grade2-02:assure','grade2-02:assure','grade2','grade2-02','assure','확신시키다','verb','Tom isn''t here, I assure you.','톰은 여기 없어, 내가 장담해.','I assure you this isn''t a joke.','이건 농담이 아니라니까.','published'),
('grade2-02:atmosphere','grade2-02:atmosphere','grade2','grade2-02','atmosphere','대기;분위기','noun','There was an atmosphere of excitement.','들뜬 분위기가 있었습니다.','There was great heat as the comet entered the atmosphere.','혜성이 대기권에 진입하면서 엄청난 열기가 발생했습니다.','published'),
('grade2-02:attach','grade2-02:attach','grade2','grade2-02','attach','붙이다','verb','To attach great importance to a particular circumstance.','특정한 상황에 큰 중요성을 부여하다.','Josh had surgery to attach the liver to the small intestine so the bile could drain.','Josh는 담즙이 배출될 수 있도록 간을 소장에 연결하는 수술을 받았습니다.','published'),
('grade2-02:attendance','grade2-02:attendance','grade2','grade2-02','attendance','출석','noun','A student''s attendance is an important factor in her grade.','학생의 출석은 성적에 중요한 요소입니다.','Attendance was up by 50 per cent.','출석률이 50% 증가했습니다.','published'),
('grade2-02:attribute','grade2-02:attribute','grade2','grade2-02','attribute','속성;~의 탓으로 돌리다','noun','It''s not fair to attribute your failure to your parents.','당신의 실패를 당신의 부모님 탓으로 돌리는것은 옳지 않습니다','Never attribute to malice that which is adequately explained by stupidity.','어리석음으로 적절하게 설명되는 것을 결코 악의로 돌리지 마십시오.','published'),
('grade2-02:automatic','grade2-02:automatic','grade2','grade2-02','automatic','자동의','adjective','A budget deficit that caused automatic spending cuts.','자동 지출 삭감을 초래한 예산 적자.','This is an automatic door.','이것은 자동문이다.','published'),
('grade2-03:bacteria','grade2-03:bacteria','grade2','grade2-03','bacteria','세균','noun','Viruses are much smaller than bacteria.','바이러스는 박테리아보다 훨씬 작아.','Clostridioides difficile is an example of anaerobic bacteria.','Clostridioides difficile은 혐기성 박테리아의 한 예입니다.','published'),
('grade2-03:barrier','grade2-03:barrier','grade2','grade2-03','barrier','장벽','noun','Intolerance is a barrier to understanding.','편협함은 이해의 장벽이다.','They stored the barrier in a safe place.','그들은 장벽을 안전한 곳에 보관했습니다.','published'),
('grade2-03:biodiversity','grade2-03:biodiversity','grade2','grade2-03','biodiversity','생물 다양성','noun','A high level of biodiversity is desirable.','높은 수준의 생물 다양성이 바람직합니다.','Her biodiversity helped the team solve the problem.','그녀의 생물 다양성은 팀이 문제를 해결하는 데 도움이 되었습니다.','published'),
('grade2-03:boundary','grade2-03:boundary','grade2','grade2-03','boundary','경계','noun','The river forms a natural boundary between the regions.','강은 지역 사이의 자연적 경계를 형성합니다.','We should respect the boundary between work and private life.','우리는 일과 사생활의 경계를 존중해야 합니다.','published'),
('grade2-03:capture','grade2-03:capture','grade2','grade2-03','capture','포착하다','verb','A NASA spacecraft skims the surface of an asteroid to capture a sample.','NASA 우주선이 샘플을 포착하기 위해 소행성 표면을 훑어봅니다.','Through this noninvasive type of project investigators can study some aspects of wildlife populations that previously involved intensive capture operations.','이러한 비침습적 유형의 프로젝트 조사관을 통해 이전에 집중적인 포획 작업을 수행했던 야생동물 개체군의 일부 측면을 연구할 수 있습니다.','published'),
('grade2-03:category','grade2-03:category','grade2','grade2-03','category','범주','noun','Should I pick a category, or do you want to?','카테고리를 선택해야 합니까, 아니면 선택하시겠습니까?','Each manta ray has been placed in a category depending on its unique underbelly markings.','각 쥐가오리는 고유한 하복부 표시에 따라 카테고리에 배치되어 있습니다.','published'),
('grade2-03:cease','grade2-03:cease','grade2','grade2-03','cease','중단하다','verb','Headdresses and earrings, brooches and belts, necklaces and rings, old and new, traditional and provocative, jewelry never cease to surprise and amaze.','머리 장식과 귀걸이, 브로치와 벨트, 목걸이와 반지, 오래된 것과 새로운 것, 전통적이고 도발적인 보석은 결코 놀라움과 놀라움을 선사하지 않습니다.','Never cease to disappoint me.','나를 실망시키는 것을 멈추지 마십시오.','published'),
('grade2-03:charity','grade2-03:charity','grade2','grade2-03','charity','자선','noun','I''m going through my closet to find clothes to give to charity.','옷장을 뒤져서 기부할 옷들을 찾아봐야겠어.','We aren''t running a charity here.','우리는 여기서 자선단체를 운영하지 않습니다.','published'),
('grade2-03:chemical','grade2-03:chemical','grade2','grade2-03','chemical','화학적인','adjective','It has a chemical taste to it.','화학적 맛이 있어요.','In the fall, a series of chemical signals, triggered by shortening day lengths, stops the growth process.','가을에는 낮의 길이가 짧아지면서 발생하는 일련의 화학적 신호가 성장 과정을 중단시킵니다.','published'),
('grade2-03:circulation','grade2-03:circulation','grade2','grade2-03','circulation','순환','noun','By increasing its circulation the newspaper hoped to increase its advertising.','발행부수를 늘림으로써 신문은 광고를 늘리기를 희망했습니다.','Ocean circulation is an important part of global climate.','해양 순환은 지구 기후의 중요한 부분입니다.','published'),
('grade2-03:civil','grade2-03:civil','grade2','grade2-03','civil','시민의','adjective','Even if he didn''t like them he should have been civil.','그가 그들을 좋아하지 않더라도 그는 예의바르게 행동했어야 했습니다.','A civil day begins at mean midnight.','시민의 날은 평균 자정에 시작됩니다.','published'),
('grade2-03:clarify','grade2-03:clarify','grade2','grade2-03','clarify','명확히 하다','verb','I thought this article would clarify things for me, but I just ended up even more confused.','나는 이 기사가 나에게 문제를 명확하게 해줄 것이라고 생각했지만 결국 더욱 혼란스러워졌습니다.','Can we clarify a few things?','몇 가지 사항을 명확히 해볼까요?','published'),
('grade2-03:classify','grade2-03:classify','grade2','grade2-03','classify','분류하다','verb','How would you classify these pottery shards--are they prehistoric?','이 도자기 파편을 어떻게 분류하시겠습니까? 선사시대의 것입니까?','The team may classify the proposal after careful review.','팀은 신중한 검토 후 제안을 분류할 수 있습니다.','published'),
('grade2-03:colleague','grade2-03:colleague','grade2','grade2-03','colleague','동료','noun','I asked a colleague to review my report.','나는 동료에게 내 보고서를 검토해 달라고 요청했습니다.','Her colleague offered helpful advice after the meeting.','그녀의 동료는 회의가 끝난 후 유용한 조언을 제공했습니다.','published'),
('grade2-03:combine','grade2-03:combine','grade2','grade2-03','combine','결합하다','verb','I''m worried our dimensions will combine and the shadow people will be able to get me.','우리의 차원이 합쳐져서 그림자 사람들이 나를 잡을 수 있을까 걱정됩니다.','Coffee roasters combine beans from different areas to make coffees with different tastes and qualities.','커피 로스터는 다양한 지역의 원두를 결합하여 다양한 맛과 품질의 커피를 만듭니다.','published'),
('grade2-03:commercial','grade2-03:commercial','grade2','grade2-03','commercial','상업적인','adjective','We believe that large, publicly available voice datasets will foster innovation and healthy commercial competition in machine-learning based speech technology.','우리는 공개적으로 사용 가능한 대규모 음성 데이터 세트가 기계 학습 기반 음성 기술의 혁신과 건전한 상업적 경쟁을 촉진할 것이라고 믿습니다.','The documentary examines the creative and commercial value of this practice, called musical sampling.','다큐멘터리는 음악 샘플링이라고 불리는 이러한 관행의 창의적이고 상업적인 가치를 조사합니다.','published'),
('grade2-03:committee','grade2-03:committee','grade2','grade2-03','committee','위원회','noun','A committee is a group that keeps minutes and loses hours.','위원회는 회의록은 유지하고 시간은 낭비하는 그룹입니다.','I''m forming an exploratory committee to decide whether I should run for president.','나는 대통령 선거에 출마할지 여부를 결정하기 위해 탐색 위원회를 구성할 예정입니다.','published'),
('grade2-03:companion','grade2-03:companion','grade2','grade2-03','companion','동반자','noun','The idea is that sharing a book with a nonjudgmental companion boosts students'' confidence and helps instill a love of reading.','비판적이지 않은 동료와 책을 공유하는 것이 학생들의 자신감을 높이고 독서에 대한 사랑을 심어주는 데 도움이 된다는 생각입니다.','The night is her companion.','밤은 그녀의 동반자입니다.','published'),
('grade2-03:compensate','grade2-03:compensate','grade2','grade2-03','compensate','보상하다','verb','It is hard work, but they will compensate you well for it.','힘든 일이지만 그에 대해 충분한 보상을 해 줄 것입니다.','His loud voice cannot compensate for a lack of personality.','그의 큰 목소리는 개성의 부족을 보완할 수 없습니다.','published'),
('grade2-03:competent','grade2-03:competent','grade2','grade2-03','competent','유능한','adjective','Here is the mountain dweller, who will never govern, even though he is educated and competent.','여기에 교육을 받고 능력이 있음에도 불구하고 결코 통치하지 않는 산에 사는 사람이 있습니다.','The reviewers considered the final result competent.','검토자들은 최종 결과가 적절하다고 생각했습니다.','published'),
('grade2-04:competition','grade2-04:competition','grade2','grade2-04','competition','경쟁','noun','Business competition can be fiendish at times.','사업상의 경쟁은 때때로 치열할 수 있습니다.','He wanted to know what the competition was doing.','그는 경쟁이 무엇을 하고 있는지 알고 싶었습니다.','published'),
('grade2-04:component','grade2-04:component','grade2','grade2-04','component','구성 요소','noun','Jealousy was a component of his character.','질투는 그의 성격의 일부였습니다.','The smaller component is hard to reach.','더 작은 구성 요소는 접근하기 어렵습니다.','published'),
('grade2-04:comprehensive','grade2-04:comprehensive','grade2','grade2-04','comprehensive','포괄적인','adjective','When there are diametrically opposing views on a big issue that concerns millions of people, doing comprehensive research just makes sense.','수백만 명의 사람들이 관심을 갖는 큰 문제에 대해 정반대의 견해가 있을 때 포괄적인 연구를 수행하는 것이 합리적입니다.','The reviewers considered the final result comprehensive.','검토자들은 최종 결과가 포괄적이라고 생각했습니다.','published'),
('grade2-04:compromise','grade2-04:compromise','grade2','grade2-04','compromise','타협하다','verb','Nobody will get everything he wants; we all must compromise.','누구도 원하는 것을 모두 얻을 수 없습니다. 우리 모두는 타협해야 합니다.','He tried to compromise the security in the computer by guessing the password.','그는 비밀번호를 추측하여 컴퓨터의 보안을 손상시키려고 했습니다.','published'),
('grade2-04:concentrate','grade2-04:concentrate','grade2','grade2-04','concentrate','집중하다','verb','These groups concentrate in the inner cities.','이 그룹은 도심에 집중되어 있습니다.','To concentrate rays of light into a focus.','광선을 한 초점으로 집중시키다.','published'),
('grade2-04:concept','grade2-04:concept','grade2','grade2-04','concept','개념','noun','I made the concept of an NFT into an NFT.','NFT의 개념을 NFT로 만들었습니다.','I don''t think she fully grasped the concept.','나는 그녀가 개념을 완전히 이해했다고 생각하지 않습니다.','published'),
('grade2-04:conclusion','grade2-04:conclusion','grade2','grade2-04','conclusion','결론','noun','His conclusion took the evidence into account.','그의 결론은 증거를 고려했습니다.','How did you arrive at this conclusion?','어떻게 이런 결론에 도달하셨나요?','published'),
('grade2-04:conduct','grade2-04:conduct','grade2','grade2-04','conduct','수행하다;행동','verb','You cannot conduct business like this.','이런 식으로 사업을 할 수는 없습니다.','All gods are better than their conduct.','모든 신은 그들의 행위보다 낫습니다.','published'),
('grade2-04:confirm','grade2-04:confirm','grade2','grade2-04','confirm','확인하다','verb','Tom can neither confirm nor deny any of the claims made about him.','Tom은 자신에 대한 어떤 주장도 확인하거나 거부할 수 없습니다.','I just need to ask you a few questions to confirm you''re not a robot.','당신이 로봇이 아닌지 확인하기 위해 몇 가지 질문만 하면 됩니다.','published'),
('grade2-04:confuse','grade2-04:confuse','grade2','grade2-04','confuse','혼란스럽게 하다','verb','These questions confuse even the experts.','이러한 질문은 전문가조차 혼란스럽게 합니다.','You''re trying to confuse me, aren''t you?','넌 날 혼란스럽게 하려고 하는 거지?','published'),
('grade2-04:consequence','grade2-04:consequence','grade2','grade2-04','consequence','결과','noun','Decisions of great consequence are made by the president himself.','중대한 결정은 대통령이 직접 내린다.','That result is of no consequence.','그 결과는 아무런 의미가 없습니다.','published'),
('grade2-04:conservative','grade2-04:conservative','grade2','grade2-04','conservative','보수적인','adjective','The curriculum committee at this university is extremely conservative.','이 대학의 교육과정위원회는 매우 보수적이다.','At a conservative estimate, growth may even be negative next year.','보수적으로 추정하면 내년 성장률은 마이너스가 될 수도 있습니다.','published'),
('grade2-04:considerable','grade2-04:considerable','grade2','grade2-04','considerable','상당한','adjective','The economy was a considerable issue in the campaign.','이번 캠페인에서는 경제가 중요한 이슈였습니다.','Went to considerable trouble for us.','우리에게 상당한 어려움을 겪었습니다.','published'),
('grade2-04:constitute','grade2-04:constitute','grade2','grade2-04','constitute','구성하다','verb','These constitute my entire belonging.','이것들은 나의 전체 소유물을 구성합니다.','The team may constitute the proposal after careful review.','팀은 신중한 검토를 거쳐 제안서를 구성할 수 있습니다.','published'),
('grade2-04:consult','grade2-04:consult','grade2','grade2-04','consult','상담하다','verb','They had to consult before arriving at a decision.','그들은 결정을 내리기 전에 협의를 거쳐야 했습니다.','You should consult the dictionary.','사전을 찾아보셔야 합니다.','published'),
('grade2-04:consumer','grade2-04:consumer','grade2','grade2-04','consumer','소비자','noun','This new system favours the consumer over the producer.','이 새로운 시스템은 생산자보다 소비자를 선호합니다.','Devaluing the currency also means that prices rise for consumers, and it tends to crimp consumer spending.','통화 가치를 떨어뜨리는 것은 소비자의 가격이 상승한다는 것을 의미하며 이는 소비자 지출을 위축시키는 경향이 있습니다.','published'),
('grade2-04:contemporary','grade2-04:contemporary','grade2','grade2-04','contemporary','동시대의','adjective','Biologists view the chupacabras as a contemporary legend.','생물학자들은 추파카브라를 현대의 전설로 봅니다.','She alternates between solo and band recordings, which allows the singer/fiddler to showcase both contemporary pop and traditional country/bluegrass sounds.','그녀는 솔로와 밴드 녹음을 번갈아 가며 가수/바이올린 연주자가 현대 팝과 전통적인 컨트리/블루그래스 사운드를 모두 선보일 수 있도록 합니다.','published'),
('grade2-04:contract','grade2-04:contract','grade2','grade2-04','contract','계약','noun','The mafia boss put a contract out on the man who betrayed him.','마피아 보스는 자신을 배신한 남자와 계약을 맺는다.','Why wouldn''t you stipulate that in the contract?','왜 계약서에 그걸 명시하지 않았나요?','published'),
('grade2-04:contribute','grade2-04:contribute','grade2','grade2-04','contribute','기여하다','verb','I want to contribute to a charitable cause.','나는 자선 활동에 기여하고 싶습니다.','Doing things, however minor those things are, helps contribute to peace of mind.','아무리 사소한 일이라도 하는 것은 마음의 평화에 도움이 됩니다.','published'),
('grade2-04:controversy','grade2-04:controversy','grade2','grade2-04','controversy','논란','noun','The policy caused considerable controversy among parents.','이 정책은 부모들 사이에서 상당한 논란을 불러일으켰습니다.','Scientists continued their research despite the controversy.','과학자들은 논란에도 불구하고 연구를 계속했다.','published'),
('grade2-05:convert','grade2-05:convert','grade2','grade2-05','convert','전환하다','verb','Could you convert my dollars into pounds?','내 달러를 파운드로 바꿔 주실 수 있나요?','How do you convert feet into metres?','피트를 미터로 어떻게 변환하나요?','published'),
('grade2-05:cooperate','grade2-05:cooperate','grade2','grade2-05','cooperate','협력하다','verb','Don''t cooperate with the police.','경찰에 협조하지 마세요.','As the three countries'' growing economies guzzle more fuel, the leaders agreed to cooperate on developing alternative sources of energy.','세 나라의 경제 성장이 더 많은 연료를 소모함에 따라, 정상들은 대체 에너지원 개발에 협력하기로 합의했습니다.','published'),
('grade2-05:coordinate','grade2-05:coordinate','grade2','grade2-05','coordinate','조정하다','verb','Coordinate the painters, masons, and plumbers.','화가, 석공, 배관공을 조정하세요.','Coordinate his actions with that of his colleagues.','그의 행동을 동료의 행동과 조화시키십시오.','published'),
('grade2-05:correspond','grade2-05:correspond','grade2','grade2-05','correspond','일치하다;서신을 주고받다','verb','The numbers in the chart correspond to each region.','차트의 숫자는 각 지역에 해당합니다.','The two friends correspond by email every week.','두 친구는 매주 이메일로 연락을 주고받는다.','published'),
('grade2-05:creativity','grade2-05:creativity','grade2','grade2-05','creativity','창의성','noun','Which is more important, creativity or efficiency?','창의성과 효율성 중 어느 것이 더 중요합니까?','Following the rules was a constraint on my creativity.','규칙을 따르는 것은 나의 창의성에 제약이 되었습니다.','published'),
('grade2-05:criterion','grade2-05:criterion','grade2','grade2-05','criterion','기준','noun','Academic achievement is only one criterion for admission.','학업 성취도는 입학을 위한 하나의 기준일 뿐입니다.','Price should not be the sole criterion for choosing a product.','가격이 제품 선택의 유일한 기준이 되어서는 안 됩니다.','published'),
('grade2-05:cultivate','grade2-05:cultivate','grade2','grade2-05','cultivate','경작하다;기르다','verb','On 1,000 hectares, the employees will be working full-time to cultivate and harvest vegetables irrigated by sprinklers rotating on 20 huge pivots.','1,000헥타르에서 직원들은 20개의 거대한 회전축에서 회전하는 스프링클러로 관개되는 야채를 재배하고 수확하기 위해 풀타임으로 일할 것입니다.','They cultivate a creative environment.','그들은 창의적인 환경을 조성합니다.','published'),
('grade2-05:debate','grade2-05:debate','grade2','grade2-05','debate','토론','noun','Liberals would rather endlessly debate abstractions than spend five minutes listening to another person''s lived experience.','자유주의자들은 다른 사람의 실제 경험을 5분 동안 듣는 것보다 추상적인 개념에 대해 끊임없이 토론하는 것을 선호합니다.','The comment section is a microcosm of the larger cultural debate taking place.','댓글 섹션은 현재 진행되고 있는 더 큰 문화적 논쟁의 축소판입니다.','published'),
('grade2-05:decline','grade2-05:decline','grade2','grade2-05','decline','감소하다;거절하다','verb','On reflection I think I will decline your generous offer.','생각해 보면 나는 당신의 관대한 제안을 거절할 것 같습니다.','The team chose to decline the fifteen-yard penalty because their receiver had caught the ball for a thirty-yard gain.','팀은 리시버가 30야드 이득을 위해 공을 잡았기 때문에 15야드 페널티를 거부하기로 결정했습니다.','published'),
('grade2-05:defeat','grade2-05:defeat','grade2','grade2-05','defeat','패배시키다','verb','It was the biggest defeat in government history, according to the BBC.','BBC에 따르면 이는 정부 역사상 가장 큰 패배였다.','The game ended in a devastating defeat.','경기는 참담한 패배로 끝났다.','published'),
('grade2-05:define','grade2-05:define','grade2','grade2-05','define','정의하다','verb','The camera could define the smallest object.','카메라는 가장 작은 물체를 정의할 수 있습니다.','I define myself as a techno-anarchist.','나는 나 자신을 기술 무정부주의자라고 정의합니다.','published'),
('grade2-05:democracy','grade2-05:democracy','grade2','grade2-05','democracy','민주주의','noun','American democracy is a kakistocratic institution.','미국의 민주주의는 카키스토크라틱한 제도입니다.','The demonstrators chant "long live democracy, long live freedom and down with fundamentalism.".','시위대는 “민주주의 만세, 자유 만세, 근본주의 타도”를 외쳤다.','published'),
('grade2-05:density','grade2-05:density','grade2','grade2-05','density','밀도','noun','Water has a higher density than oil.','물은 기름보다 밀도가 높습니다.','Population density is greatest near the city center.','인구 밀도는 도심 근처에서 가장 높습니다.','published'),
('grade2-05:depression','grade2-05:depression','grade2','grade2-05','depression','우울;불황','noun','Do you suffer from depression?','우울증에 앓고 있어?','Tom has been battling depression for many years.','톰은 수년 간 우울증과 싸우고 있어.','published'),
('grade2-05:deserve','grade2-05:deserve','grade2','grade2-05','deserve','~할 가치가 있다','verb','You deserve a promotion after all the hard work you have done.','당신은 열심히 일한 후에 승진할 자격이 있습니다.','I put trust in her that she didn''t deserve.','나는 그녀가 자격이 없다고 그녀를 믿었습니다.','published'),
('grade2-05:detect','grade2-05:detect','grade2','grade2-05','detect','탐지하다','verb','The high-pitched whine of a mosquito is annoying, but scientists have developed an app that uses that sound to detect dangerous mosquitoes.','모기의 높은 윙윙거리는 소리는 짜증나는 소리지만, 과학자들은 그 소리를 이용해 위험한 모기를 탐지하는 앱을 개발했습니다.','I can detect that there are other dimensions parallel to this one.','나는 이 차원과 평행한 다른 차원이 있다는 것을 감지할 수 있습니다.','published'),
('grade2-05:determine','grade2-05:determine','grade2','grade2-05','determine','결정하다','verb','They want to determine whether there were any unreported malfunctions and whether or not all test objectives were met.','그들은 보고되지 않은 오작동이 있었는지, 그리고 모든 테스트 목표가 충족되었는지 여부를 확인하려고 합니다.','The students were asked to determine something important.','학생들은 중요한 것을 결정하도록 요청 받았습니다.','published'),
('grade2-05:devote','grade2-05:devote','grade2','grade2-05','devote','바치다','verb','She plans to devote more time to her studies.','그녀는 공부에 더 많은 시간을 할애할 계획이다.','The museum will devote an entire room to local history.','박물관은 방 전체를 지역 역사에 전념할 것입니다.','published'),
('grade2-05:differ','grade2-05:differ','grade2','grade2-05','differ','다르다','verb','These two tests differ in only one respect.','이 두 테스트는 한 가지 측면에서만 다릅니다.','These shoes only differ from those ones in having slightly longer laces.','이 신발은 끈이 약간 더 길다는 점만 다른 신발과 다릅니다.','published'),
('grade2-05:disability','grade2-05:disability','grade2','grade2-05','disability','장애','noun','I have an invisible disability.','나는 눈에 보이지 않는 장애를 가지고 있습니다.','I work to the extent my disability allows.','나는 장애가 허용하는 한도 내에서 일합니다.','published'),
('grade2-06:discrimination','grade2-06:discrimination','grade2','grade2-06','discrimination','차별','noun','Conversely, hard-pressed refugees talk of discrimination, exploitation by landlords and even greater abuses flowing from local resentment.','반대로, 심한 압박을 받는 난민들은 차별, 집주인의 착취, 심지어 지역적 분노에서 비롯되는 더 큰 학대에 대해 이야기합니다.','Since some people have to deal with discrimination everywhere they go, we don''t have equality of opportunity.','어떤 사람들은 가는 곳마다 차별을 받아야 하기 때문에 기회의 평등이 이루어지지 않습니다.','published'),
('grade2-06:display','grade2-06:display','grade2','grade2-06','display','전시하다','verb','National leaders will have to display the highest skills of statesmanship.','국가 지도자들은 최고의 정치 능력을 발휘해야 합니다.','I was in awe of the artistry on display.','나는 전시된 예술성에 경외심을 느꼈다.','published'),
('grade2-06:distinguish','grade2-06:distinguish','grade2','grade2-06','distinguish','구별하다','verb','We distinguish several kinds of maple.','우리는 여러 종류의 단풍나무를 구별합니다.','Philosophers distinguish between a priori and a posteriori knowledge.','철학자들은 선험적 지식과 사후적 지식을 구별합니다.','published'),
('grade2-06:distribution','grade2-06:distribution','grade2','grade2-06','distribution','분배','noun','The graph shows the distribution of income by region.','그래프는 지역별 소득 분포를 보여줍니다.','Volunteers organized the distribution of food and water.','자원봉사자들은 음식과 물의 배급을 조직했습니다.','published'),
('grade2-06:diversity','grade2-06:diversity','grade2','grade2-06','diversity','다양성','noun','We want to make voice data freely and publicly available, and make sure the data represents the diversity of real people.','우리는 음성 데이터를 무료로 공개적으로 제공하고 데이터가 실제 사람들의 다양성을 나타내기를 원합니다.','Humanity''s strength lies in its diversity.','인류의 강점은 다양성에 있습니다.','published'),
('grade2-06:dominant','grade2-06:dominant','grade2','grade2-06','dominant','지배적인','adjective','Television plays a dominant role in molding public opinion.','텔레비전은 여론 형성에 지배적인 역할을 합니다.','The final decision seemed dominant to everyone involved.','최종 결정은 관련된 모든 사람에게 지배적인 것처럼 보였습니다.','published'),
('grade2-06:duration','grade2-06:duration','grade2','grade2-06','duration','지속 기간','noun','The ceremony was of short duration.','행사는 짧았습니다.','I have a shepherd-dog that has known me well, but the friendship is often interrupted by partings of some months'' duration.','저에게는 저를 잘 아는 양치기 개가 있습니다. 그러나 우정은 종종 몇 달 간의 이별로 인해 중단됩니다.','published'),
('grade2-06:ecology','grade2-06:ecology','grade2','grade2-06','ecology','생태학','noun','It changed the ecology of the island.','그것은 섬의 생태를 변화시켰습니다.','Tom''s knowledge of decomposition ecology is peerless.','분해 생태학에 대한 톰의 지식은 타의 추종을 불허합니다.','published'),
('grade2-06:economic','grade2-06:economic','grade2','grade2-06','economic','경제의','adjective','He wrote the book primarily for economic reasons.','그는 주로 경제적인 이유로 책을 썼습니다.','Gave up the large house for economic reasons.','경제적인 이유로 큰 집을 포기했습니다.','published'),
('grade2-06:efficient','grade2-06:efficient','grade2','grade2-06','efficient','효율적인','adjective','The price of jet fuel is one reason aviation technology research is so often focused on making planes lighter and more efficient.','제트 연료의 가격은 항공 기술 연구가 비행기를 더 가볍고 효율적으로 만드는 데 집중되는 이유 중 하나입니다.','Torres promised to reactivate the economy, tackle the country''s security situation, advocate for those at risk and run an efficient government.','토레스는 경제를 재가동하고 국가의 안보 상황을 해결하며 위험에 처한 사람들을 옹호하고 효율적인 정부를 운영하겠다고 약속했습니다.','published'),
('grade2-06:elect','grade2-06:elect','grade2','grade2-06','elect','선출하다','verb','Citizens will elect a new mayor this year.','시민들은 올해 새로운 시장을 선출하게 됩니다.','The students elect a class president every semester.','학생들은 매 학기마다 반장을 선출합니다.','published'),
('grade2-06:eliminate','grade2-06:eliminate','grade2','grade2-06','eliminate','제거하다','verb','Attempting to eliminate gay and trans people is a fundamentally flawed goal, as we will keep being born no matter what.','동성애자와 트랜스젠더를 제거하려는 시도는 근본적으로 결함이 있는 목표입니다. 우리는 무슨 일이 있어도 계속해서 태어날 것이기 때문입니다.','The right is attempting to eliminate trans people, but this is impossible, because trans people will always continue to be born.','우파는 트랜스젠더를 제거하려고 시도하지만 이는 불가능합니다. 트랜스젠더는 언제나 계속해서 탄생할 것이기 때문입니다.','published'),
('grade2-06:emergency','grade2-06:emergency','grade2','grade2-06','emergency','비상사태','noun','He never knew what to do in an emergency.','그는 비상시에 무엇을 해야 할지 전혀 몰랐습니다.','The governor declared a state of emergency.','주지사는 비상사태를 선포했다.','published'),
('grade2-06:emphasis','grade2-06:emphasis','grade2','grade2-06','emphasis','강조','noun','The red light gave the central figure increased emphasis.','빨간불은 중앙 인물을 더욱 강조했습니다.','They worked together to improve the emphasis.','그들은 강조점을 개선하기 위해 함께 노력했습니다.','published'),
('grade2-06:employment','grade2-06:employment','grade2','grade2-06','employment','고용','noun','They are looking for employment.','그들은 일자리를 찾고 있습니다.','He is looking for employment.','그는 일자리를 찾고 있습니다.','published'),
('grade2-06:encounter','grade2-06:encounter','grade2','grade2-06','encounter','마주치다','verb','Tom recognized me from a single encounter at a party three years ago.','톰은 3년 전 파티에서 한 번 만났을 때 나를 알아보았습니다.','Anyone you encounter may be traumatized.','만나는 사람마다 트라우마를 겪을 수 있습니다.','published'),
('grade2-06:engage','grade2-06:engage','grade2','grade2-06','engage','참여하다','verb','Do they engage with their voters?','그들은 유권자와 소통합니까?','People often engage under pressure.','사람들은 종종 압박감을 느끼며 참여합니다.','published'),
('grade2-06:ensure','grade2-06:ensure','grade2','grade2-06','ensure','보장하다','verb','This nest egg will ensure a nice retirement for us.','이 둥지 알은 우리에게 좋은 은퇴를 보장해 줄 것입니다.','Republicans have been implementing ways to ensure undemocratic minority rule, because their core demographic is shrinking.','공화당은 핵심 인구가 줄어들고 있기 때문에 비민주적인 소수 지배를 보장하는 방법을 시행해 왔습니다.','published'),
('grade2-06:entire','grade2-06:entire','grade2','grade2-06','entire','전체의','adjective','An entire town devastated by an earthquake.','지진으로 마을 전체가 황폐화되었습니다.','Was able to keep the collection entire during his lifetime.','평생 동안 컬렉션 전체를 보관할 수있었습니다.','published'),
('grade2-06:equivalent','grade2-06:equivalent','grade2','grade2-06','equivalent','동등한','adjective','A wish that was equivalent to a command.','명령과도 같은 소원.','When a cat or dog licks you, it''s their equivalent of petting you.','고양이나 개가 당신을 핥는 것은 당신을 쓰다듬는 것과 같습니다.','published'),
('grade2-07:era','grade2-07:era','grade2','grade2-07','era','시대','noun','In this era of post-truth politics, it''s easy to cherry-pick data and come to whatever conclusion you desire.','탈진실 정치 시대에는 데이터를 선별하여 원하는 결론에 도달하기가 쉽습니다.','This mousepad is a vestige of a bygone era.','이 마우스패드는 지나간 시대의 흔적입니다.','published'),
('grade2-07:estimate','grade2-07:estimate','grade2','grade2-07','estimate','추정하다','verb','I estimate this chicken to weigh three pounds.','내 생각에 이 닭의 무게는 3파운드 정도 될 것 같아요.','The inertial measurement unit contains accelerometers, which—just like the accelerometers within the inclinometer—can be used to estimate the initial attitude.','관성 측정 장치에는 경사계 내의 가속도계와 마찬가지로 초기 자세를 추정하는 데 사용할 수 있는 가속도계가 포함되어 있습니다.','published'),
('grade2-07:evaluate','grade2-07:evaluate','grade2','grade2-07','evaluate','평가하다','verb','How do you evaluate this grant proposal?','이 보조금 제안을 어떻게 평가하시나요?','L''Hôpital''s rule uses derivatives to help evaluate limits involving indeterminate forms.','로피탈의 법칙은 미분을 사용하여 불확정 형태와 관련된 극한을 평가하는 데 도움을 줍니다.','published'),
('grade2-07:evolution','grade2-07:evolution','grade2','grade2-07','evolution','진화','noun','Do you believe in evolution?','진화론을 믿니?','Tom doesn''t believe in evolution.','톰은 진화론을 믿지 않아.','published'),
('grade2-07:exaggerate','grade2-07:exaggerate','grade2','grade2-07','exaggerate','과장하다','verb','I''ve told you a million times not to exaggerate.','과장하지 말라고 100만 번은 말했을 텐데.','The team may exaggerate the proposal after careful review.','팀에서는 신중하게 검토한 후 제안을 과장할 수 있습니다.','published'),
('grade2-07:exception','grade2-07:exception','grade2','grade2-07','exception','예외','noun','With the exception of the children, everyone was told the news.','아이들을 제외하고 모두가 그 소식을 들었습니다.','All her children were brilliant; the only exception was her last child.','그녀의 아이들은 모두 훌륭했습니다. 유일한 예외는 그녀의 마지막 아이였습니다.','published'),
('grade2-07:execute','grade2-07:execute','grade2','grade2-07','execute','실행하다','verb','Execute the decision of the people.','국민의 결정을 실행하십시오.','Execute a will or a deed.','유언장이나 증서를 실행하십시오.','published'),
('grade2-07:expand','grade2-07:expand','grade2','grade2-07','expand','확장하다','verb','Expand the house by adding another wing.','또 다른 날개를 추가하여 집을 확장하세요.','You can expand this compact umbrella to cover a large table.','이 컴팩트한 우산을 펼치면 큰 테이블까지 덮을 수 있습니다.','published'),
('grade2-07:expense','grade2-07:expense','grade2','grade2-07','expense','비용','noun','Buying the car was a big expense, but will be worth it in the long run.','차를 구입하는 데는 큰 비용이 들었지만 장기적으로는 그만한 가치가 있을 것입니다.','Can this be written off as a business expense?','이것을 사업 비용으로 처리할 수 있나요?','published'),
('grade2-07:exploit','grade2-07:exploit','grade2','grade2-07','exploit','이용하다;착취하다','verb','He exploit the new taxation system.','그는 새로운 과세 시스템을 이용합니다.','We must exploit the resources we are given wisely.','우리는 주어진 자원을 현명하게 활용해야 합니다.','published'),
('grade2-07:exposure','grade2-07:exposure','grade2','grade2-07','exposure','노출','noun','She denounced the exposure of children to pornography.','그녀는 어린이들이 포르노에 노출되는 것을 비난했습니다.','They feared exposure of their campaign plans.','그들은 캠페인 계획이 노출되는 것을 두려워했습니다.','published'),
('grade2-07:external','grade2-07:external','grade2','grade2-07','external','외부의','adjective','This building has some external pipework.','이 건물에는 외부 배관이 있습니다.','I bought an external hard drive.','외장하드를 구매했습니다.','published'),
('grade2-07:extract','grade2-07:extract','grade2','grade2-07','extract','추출하다','verb','To extract a tooth from its socket, a stump from the earth, or a splinter from the finger.','소켓에서 치아를 뽑거나, 땅에서 그루터기를 뽑거나, 손가락에서 파편을 뽑다.','To extract an essential oil from a plant.','식물에서 에센셜 오일을 추출합니다.','published'),
('grade2-07:faculty','grade2-07:faculty','grade2','grade2-07','faculty','교수진;능력','noun','After doctoral research on his favorite insect species—ants—he joined the faculty as a zoology professor in 1956.','자신이 가장 좋아하는 곤충 종인 개미에 대한 박사 연구를 마친 후 1956년에 동물학 교수로 교수진에 합류했습니다.','Tom is my faculty advisor.','Tom은 나의 교수진 고문입니다.','published'),
('grade2-07:fascinate','grade2-07:fascinate','grade2','grade2-07','fascinate','매료시키다','verb','His baboon story will fascinate and entertain you for sure.','그의 개코원숭이 이야기는 확실히 당신을 매료시키고 즐겁게 해줄 것입니다.','Plastic seems to fascinate cats.','플라스틱은 고양이를 매료시키는 것 같습니다.','published'),
('grade2-07:feasible','grade2-07:feasible','grade2','grade2-07','feasible','실행 가능한','adjective','I was told right at the beginning that running a solar cooker company and making it feasible and financially stable was impossible.','처음부터 태양열 조리기 회사를 운영하고 이를 실현 가능하고 재정적으로 안정되게 만드는 것은 불가능하다는 말을 들었습니다.','I don''t think it''s feasible.','나는 그것이 가능하다고 생각하지 않습니다.','published'),
('grade2-07:flexibility','grade2-07:flexibility','grade2','grade2-07','flexibility','유연성','noun','He enjoyed the flexibility of his working arrangement.','그는 근무 방식의 유연성을 즐겼습니다.','The report clearly described the flexibility.','보고서에는 유연성이 명확하게 설명되어 있습니다.','published'),
('grade2-07:fluctuate','grade2-07:fluctuate','grade2','grade2-07','fluctuate','변동하다','verb','Variegated leaves fluctuate between green and white, or green and yellow, and display these colors in nearly all possible patterns.','잡색의 잎은 녹색과 흰색, 녹색과 노란색 사이를 오가며 거의 모든 가능한 패턴으로 이러한 색상을 표시합니다.','The new policy may fluctuate the final outcome.','새로운 정책에 따라 최종 결과가 달라질 수 있습니다.','published'),
('grade2-07:forecast','grade2-07:forecast','grade2','grade2-07','forecast','예측','noun','The weather forecast was right.','일기예보가 맞았어.','That would be a sharp markdown from the 2.2 percent growth the IMF forecast last month.','이는 지난달 IMF가 전망한 2.2% 성장률보다 대폭 하락한 것이다.','published'),
('grade2-07:foundation','grade2-07:foundation','grade2','grade2-07','foundation','기초;재단','noun','There is little foundation for his objections.','그의 반대에는 근거가 거의 없습니다.','He lacks the foundation necessary for advanced study.','그는 고급 연구에 필요한 기초가 부족합니다.','published'),
('grade2-08:frequency','grade2-08:frequency','grade2','grade2-08','frequency','빈도','noun','The frequency of modulation was 40 cycles per second.','변조 주파수는 초당 40사이클이었습니다.','The frequency of his seizures increased as he grew older.','그의 발작 빈도는 나이가 들수록 증가했습니다.','published'),
('grade2-08:fundamental','grade2-08:fundamental','grade2','grade2-08','fundamental','근본적인','adjective','An example that was fundamental to the argument.','논쟁의 기본이 되는 예.','Computers are fundamental to modern industrial structure.','컴퓨터는 현대 산업 구조의 기본입니다.','published'),
('grade2-08:genetics','grade2-08:genetics','grade2','grade2-08','genetics','유전학','noun','Their work reveals a lot about songbird genetics, and opens a new door to understanding the basis of human speech.','그들의 연구는 명금류 유전학에 대해 많은 것을 밝혀주고 인간 언어의 기초를 이해하는 새로운 문을 열어줍니다.','Think about the basic genetics you may have learned in school and every vocabulary term you needed to memorize.','학교에서 배웠을지도 모르는 기본 유전학과 외워야 할 모든 어휘에 대해 생각해 보세요.','published'),
('grade2-08:geography','grade2-08:geography','grade2','grade2-08','geography','지리','noun','We barely do any work in geography lessons, we just doss about.','우리는 지리 수업 시간에 거의 아무 일도 하지 않고, 그저 뒹굴기만 합니다.','The class discussed the geography from several viewpoints.','수업에서는 여러 관점에서 지리에 대해 논의했습니다.','published'),
('grade2-08:gesture','grade2-08:gesture','grade2','grade2-08','gesture','몸짓','noun','A gesture is enough for a scholar to understand us.','학자가 우리를 이해하려면 몸짓만으로도 충분합니다.','A gesture is enough to be understood by a scholar.','학자라면 몸짓만으로도 충분히 이해할 수 있다.','published'),
('grade2-08:gradual','grade2-08:gradual','grade2','grade2-08','gradual','점진적인','adjective','Gradual improvements can be hard to notice, but they''re still there.','점진적인 개선은 눈에 띄기 어려울 수 있지만 여전히 존재합니다.','The final decision seemed gradual to everyone involved.','관련된 모든 사람에게 최종 결정은 점진적인 것처럼 보였습니다.','published'),
('grade2-08:guideline','grade2-08:guideline','grade2','grade2-08','guideline','지침','noun','This guideline explains how to use the equipment safely.','이 지침은 장비를 안전하게 사용하는 방법을 설명합니다.','Teachers should treat the rule as a guideline, not a command.','교사는 규칙을 명령이 아닌 지침으로 다루어야 합니다.','published'),
('grade2-08:hazard','grade2-08:hazard','grade2','grade2-08','hazard','위험 요소','noun','Space debris, like old satellites, can pose a hazard to future space missions.','오래된 위성과 같은 우주 쓰레기는 미래의 우주 임무에 위험을 초래할 수 있습니다.','They worked together to improve the hazard.','그들은 위험을 개선하기 위해 함께 일했습니다.','published'),
('grade2-08:hierarchy','grade2-08:hierarchy','grade2','grade2-08','hierarchy','위계','noun','Put honesty first in her hierarchy of values.','그녀의 가치 체계에서 정직을 최우선으로 생각하세요.','There''s no such thing as a natural hierarchy.','자연스러운 계층 구조 같은 것은 없습니다.','published'),
('grade2-08:hostile','grade2-08:hostile','grade2','grade2-08','hostile','적대적인','adjective','Some of these cellular modifications also include changes to the membranes that envelop the microbe and protect it from its hostile environment.','이러한 세포 변형 중 일부에는 미생물을 감싸고 적대적인 환경으로부터 보호하는 막의 변화도 포함됩니다.','Lack of moderation creates a hostile environment in which it is less possible to carry out a project''s main purpose.','절제가 부족하면 프로젝트의 주요 목적을 수행하는 것이 불가능한 적대적인 환경이 조성됩니다.','published'),
('grade2-08:hypothesis','grade2-08:hypothesis','grade2','grade2-08','hypothesis','가설','noun','A scientific hypothesis that survives experimental testing becomes a scientific theory.','실험적 테스트를 거쳐 살아남은 과학적 가설은 과학적인 이론이 됩니다.','I think your hypothesis is correct.','네 가설이 맞는 것 같아.','published'),
('grade2-08:illustrate','grade2-08:illustrate','grade2','grade2-08','illustrate','설명하다;삽화를 넣다','verb','Illustrate a book with drawings.','그림으로 책을 그려보세요.','The students were asked to illustrate something important.','학생들은 중요한 것을 설명해 달라는 요청을 받았습니다.','published'),
('grade2-08:immense','grade2-08:immense','grade2','grade2-08','immense','막대한','adjective','Biden has been under immense pressure to waive vaccine patents, one of his campaign promises.','Biden은 그의 캠페인 공약 중 하나인 백신 특허를 포기하라는 엄청난 압력을 받아 왔습니다.','A vast bedlam of sound flies up to my window, and above all is the immense whistling of unseen and unfelt winds.','광대한 소음이 내 창문까지 날아오고, 무엇보다도 보이지 않고 느껴지지 않는 바람의 엄청난 휘파람 소리입니다.','published'),
('grade2-08:implement','grade2-08:implement','grade2','grade2-08','implement','실행하다','verb','The idea is very interesting, but I''m worried about how we are going to implement it.','아이디어는 매우 흥미롭지만, 이를 어떻게 구현해낼지 걱정이 됩니다.','He added that it behooves both the sub-regional group and its member states to implement the agreed measures to combat the famine.','그는 기근 퇴치를 위해 합의된 조치를 이행하는 것이 소지역 그룹과 회원국 모두의 의무라고 덧붙였습니다.','published'),
('grade2-08:imply','grade2-08:imply','grade2','grade2-08','imply','암시하다','verb','Being LGBT theoretically does not imply a political affiliation, but when a party is promising to destroy your life, believe them.','이론적으로 LGBT가 된다는 것은 정치적 성향을 의미하지는 않지만, 정당이 당신의 삶을 파괴하겠다고 약속한다면 그 말을 믿으세요.','The students were asked to imply something important.','학생들은 중요한 것을 암시하도록 요청 받았습니다.','published'),
('grade2-08:impression','grade2-08:impression','grade2','grade2-08','impression','인상','noun','His impression of her was favorable.','그녀에 대한 그의 인상은 호의적이었습니다.','He made a good impression.','그는 좋은 인상을 남겼습니다.','published'),
('grade2-08:incentive','grade2-08:incentive','grade2','grade2-08','incentive','장려책','noun','That''s not much of an incentive.','그다지 인센티브가 되지는 않습니다.','She explained the incentive behind her decision.','그녀는 자신의 결정에 대한 동기를 설명했습니다.','published'),
('grade2-08:income','grade2-08:income','grade2','grade2-08','income','소득','noun','I''m looking for an easy way to supplement my income.','나는 수입을 보충할 수 있는 쉬운 방법을 찾고 있습니다.','Bangladesh is a developing country with a low per capita income.','방글라데시는 1인당 국민소득이 낮은 개발도상국이다.','published'),
('grade2-08:independence','grade2-08:independence','grade2','grade2-08','independence','독립','noun','Many of our greatest strides, from gaining our independence to abolition of civil rights, have been led by people of faith.','독립을 쟁취하는 것부터 시민권을 폐지하는 것까지 우리의 가장 큰 진전 중 많은 부분이 신앙을 가진 사람들에 의해 주도되었습니다.','The most unpardonable sin in society is independence of thought.','사회에서 가장 용서받을 수 없는 죄는 사상의 독립이다.','published'),
('grade2-08:industrial','grade2-08:industrial','grade2','grade2-08','industrial','산업의','adjective','What are the industrial applications of boron?','붕소의 산업적 응용은 무엇입니까?','The tit-for-tat consulate closures further escalated the tensions between the two countries over issues from trade and industrial espionage to human rights.','영사관 폐쇄로 무역과 산업스파이, 인권 문제를 둘러싸고 양국 간 긴장이 더욱 고조됐다.','published'),
('grade2-09:inequality','grade2-09:inequality','grade2','grade2-09','inequality','불평등','noun','The growing inequality between rich and poor.','부자와 가난한 사람 사이의 불평등이 커지고 있습니다.','Trickle-down economics have been proven to increase inequality.','낙수효과 경제학은 불평등을 증가시키는 것으로 입증되었습니다.','published'),
('grade2-09:infer','grade2-09:infer','grade2','grade2-09','infer','추론하다','verb','Telescopes are not yet powerful enough to see planets orbiting distant stars, so astronomers must infer their presence.','망원경은 아직 먼 별을 공전하는 행성을 볼 만큼 강력하지 않기 때문에 천문학자들은 행성의 존재를 추론해야 합니다.','What can you infer from these observations?','이러한 관찰로부터 무엇을 추론할 수 있습니까?','published'),
('grade2-09:inflation','grade2-09:inflation','grade2','grade2-09','inflation','물가 상승','noun','In inflation everything gets more valuable except money.','인플레이션에서는 돈을 제외한 모든 것이 더 가치 있게 됩니다.','The government is taking steps to quell voter unrest over surging inflation.','정부가 물가상승으로 인한 유권자 불안을 진정시키기 위한 조치를 취하고 있다.','published'),
('grade2-09:ingredient','grade2-09:ingredient','grade2','grade2-09','ingredient','재료','noun','Scientists have long known that the dandelion''s milky sap contains latex, the main ingredient of raw rubber.','과학자들은 민들레의 우유빛 수액에 생고무의 주성분인 라텍스가 포함되어 있다는 사실을 오랫동안 알고 있었습니다.','You can use any ingredient that can be skewered on a stick.','꼬치에 꽂을 수 있는 재료라면 무엇이든 사용 가능합니다.','published'),
('grade2-09:initiative','grade2-09:initiative','grade2','grade2-09','initiative','주도권','noun','But an initiative by USAID is ensuring that youth who don''t complete secondary school are trained in a vocation.','그러나 USAID의 계획은 중등학교를 마치지 못한 청소년들이 직업 훈련을 받을 수 있도록 보장하는 것입니다.','They participated in the national crime prevention initiative.','그들은 국가 범죄 예방 이니셔티브에 참여했습니다.','published'),
('grade2-09:inquiry','grade2-09:inquiry','grade2','grade2-09','inquiry','조사;질문','noun','This activity will aid students in internalizing the enormity of space through the use of math and inquiry skills.','이 활동은 학생들이 수학과 탐구 기술을 사용하여 공간의 거대함을 내면화하는 데 도움이 됩니다.','Her inquiry changed after she reviewed the evidence.','그녀의 질문은 증거를 검토한 후 바뀌었습니다.','published'),
('grade2-09:inspect','grade2-09:inspect','grade2','grade2-09','inspect','점검하다','verb','Please inspect your father''s will carefully.','아버지의 뜻을 잘 살펴보시기 바랍니다.','The team may inspect the proposal after careful review.','팀은 신중한 검토 후 제안을 검사할 수 있습니다.','published'),
('grade2-09:institute','grade2-09:institute','grade2','grade2-09','institute','기관;설립하다','noun','The research institute published its annual report.','연구소는 연례 보고서를 발표했습니다.','The school will institute a new safety policy.','학교는 새로운 안전 정책을 제정할 것입니다.','published'),
('grade2-09:institution','grade2-09:institution','grade2','grade2-09','institution','기관;제도','noun','He had become an institution in the theater.','그는 극장의 기관이 되었습니다.','Marriage is a patriarchal institution.','결혼은 가부장적 제도이다.','published'),
('grade2-09:intellectual','grade2-09:intellectual','grade2','grade2-09','intellectual','지적인','adjective','Intellectual workers engaged in creative literary or artistic or scientific labor.','창의적인 문학, 예술, 과학 노동에 종사하는 지적 노동자.','Intellectual philosophy, sometimes called "mental" philosophy.','지적 철학, 때로는 "정신적" 철학이라고도 불립니다.','published'),
('grade2-09:intense','grade2-09:intense','grade2','grade2-09','intense','강렬한','adjective','The artist was a small, intense man with piercing blue eyes.','그 예술가는 날카로운 파란 눈을 가진 작고 강렬한 남자였습니다.','If it gets too intense, just let us know and we''ll stop the experiment.','너무 강렬해지면 알려주시면 실험을 중단하겠습니다.','published'),
('grade2-09:interpret','grade2-09:interpret','grade2','grade2-09','interpret','해석하다','verb','How do you interpret his behavior?','그의 행동을 어떻게 해석하시나요?','Can you interpret the speech of the visiting dignitaries?','방문 고위 인사들의 연설을 통역할 수 있습니까?','published'),
('grade2-09:interval','grade2-09:interval','grade2','grade2-09','interval','간격','noun','The disappointment was followed by an interval of blankness.','실망감 뒤에는 공백기가 이어졌다.','The interval passed more quickly than expected.','생각보다 간격이 빨리 지나갔습니다.','published'),
('grade2-09:invest','grade2-09:invest','grade2','grade2-09','invest','투자하다','verb','I can''t decide whether to invest in a corporate bond or a gilt.','회사채에 투자할지, 금채에 투자할지 결정할 수 없습니다.','Following the recent food supply and price crises, world leaders pledged to invest much more in agriculture, especially smallholder agriculture.','최근 식량 공급 및 가격 위기 이후 세계 지도자들은 농업, 특히 소규모 농업에 훨씬 더 많은 투자를 약속했습니다.','published'),
('grade2-09:investigation','grade2-09:investigation','grade2','grade2-09','investigation','조사','noun','Despite thorough investigation, the perpetrator of the attacks remains unknown.','철저한 조사에도 불구하고 공격의 가해자는 아직 알려지지 않았습니다.','The monitoring group has released findings of its four-month investigation into what it condemned as a "sinister" campaign.','모니터링 그룹은 "불길한" 캠페인으로 비난한 캠페인에 대해 4개월간 조사한 결과를 발표했습니다.','published'),
('grade2-09:isolate','grade2-09:isolate','grade2','grade2-09','isolate','고립시키다','verb','The chemist managed to isolate the compound.','그 화학자는 화합물을 분리하는 데 성공했습니다.','Cults isolate people from the surrounding world.','이단은 사람들을 주변 세계로부터 격리시킵니다.','published'),
('grade2-09:labor','grade2-09:labor','grade2','grade2-09','labor','노동','noun','There is a shortage of skilled labor in this field.','이 분야에는 숙련된 노동력이 부족합니다.','His labor did not require a great deal of skill.','그의 작업에는 많은 기술이 필요하지 않았습니다.','published'),
('grade2-09:launch','grade2-09:launch','grade2','grade2-09','launch','시작하다;발사하다','verb','Double-click an icon to launch the associated application.','아이콘을 두 번 클릭하면 관련 애플리케이션이 실행됩니다.','To launch into an argument or discussion.','논쟁이나 토론을 시작하다.','published'),
('grade2-09:leadership','grade2-09:leadership','grade2','grade2-09','leadership','지도력','noun','His leadership inspired the team.','그의 리더십은 팀에 영감을 주었습니다.','The national leadership adopted his plan.','국가 지도부는 그의 계획을 채택했습니다.','published'),
('grade2-09:liberal','grade2-09:liberal','grade2','grade2-09','liberal','자유주의적인','adjective','He was liberal with his compliments.','그는 칭찬에 자유분방했습니다.','Add a liberal sprinkling of salt.','소금을 넉넉하게 뿌립니다.','published'),
('grade2-10:likewise','grade2-10:likewise','grade2','grade2-10','likewise','마찬가지로','adverb','Mina finished her work early, and Jisu did likewise.','미나는 일을 일찍 끝냈고 지수도 마찬가지였다.','The first solution reduced costs; likewise, the second saved time.','첫 번째 솔루션은 비용을 절감했습니다. 마찬가지로 두 번째 시간도 절약되었습니다.','published'),
('grade2-10:literature','grade2-10:literature','grade2','grade2-10','literature','문학','noun','Her place in literature is secure.','문학에서 그녀의 위치는 확실합니다.','Phoenician literature, written on papyrus, has mostly been lost to time and the elements.','파피루스에 기록된 페니키아 문학은 대부분 시간과 환경에 의해 손실되었습니다.','published'),
('grade2-10:loyal','grade2-10:loyal','grade2','grade2-10','loyal','충성스러운','adjective','Loyal friends stood by him.','그의 곁에는 충성스러운 친구들이 있었습니다.','She stayed loyal through thick and thin.','그녀는 어려울 때나 어려울 때나 충성심을 유지했습니다.','published'),
('grade2-10:magnitude','grade2-10:magnitude','grade2','grade2-10','magnitude','규모','noun','They tried to predict the magnitude of the explosion.','그들은 폭발의 규모를 예측하려고 노력했습니다.','Due to their huge size and luminance, they easily qualify as “first magnitude” stars.','거대한 크기와 휘도 덕분에 이 별들은 쉽게 "1등성" 별로 자격을 갖습니다.','published'),
('grade2-10:manufacture','grade2-10:manufacture','grade2','grade2-10','manufacture','제조하다','verb','Robots are used to manufacture cars.','로봇은 자동차를 대량생산할 때 쓰여.','Cement is the glue holding concrete together, and it is the manufacture of cement that creates concrete''s substantial carbon footprint.','시멘트는 콘크리트를 서로 결합시키는 접착제이며, 콘크리트의 상당한 탄소 발자국을 생성하는 것은 시멘트 제조입니다.','published'),
('grade2-10:massive','grade2-10:massive','grade2','grade2-10','massive','거대한','adjective','Earth is the most massive of the terrestrial planets.','지구는 지구형 행성 중에서 가장 질량이 크다.','Tom is a massive twat.','톰은 엄청난 멍청이입니다.','published'),
('grade2-10:measurement','grade2-10:measurement','grade2','grade2-10','measurement','측정','noun','The inertial measurement unit contains accelerometers, which—just like the accelerometers within the inclinometer—can be used to estimate the initial attitude.','관성 측정 장치에는 경사계 내의 가속도계와 마찬가지로 초기 자세를 추정하는 데 사용할 수 있는 가속도계가 포함되어 있습니다.','The team completed the measurement before the deadline.','팀은 마감일 이전에 측정을 완료했습니다.','published'),
('grade2-10:mediate','grade2-10:mediate','grade2','grade2-10','mediate','중재하다','verb','A counselor helped mediate the dispute between the students.','상담사는 학생들 사이의 분쟁을 중재하는 데 도움을 주었습니다.','International organizations may mediate peace negotiations.','국제기구는 평화협상을 중재할 수도 있다.','published'),
('grade2-10:migrate','grade2-10:migrate','grade2','grade2-10','migrate','이주하다','verb','The workers migrate to where the crops need harvesting.','일꾼들은 작물 수확이 필요한 곳으로 이주합니다.','Some birds migrate to roost during specific seasons.','일부 새는 특정 계절에 보금자리로 이동합니다.','published'),
('grade2-10:minority','grade2-10:minority','grade2','grade2-10','minority','소수 집단','noun','When the vote was taken they were in the minority.','투표가 이루어졌을 때 그들은 소수에 속했습니다.','He held a minority position.','그는 소수의 위치를 차지했습니다.','published'),
('grade2-10:monitor','grade2-10:monitor','grade2','grade2-10','monitor','감시하다','verb','The police monitor the suspect''s moves.','경찰은 용의자의 움직임을 감시하고 있다.','Whoever invented the touchscreen monitor didn''t have a cat.','터치스크린 모니터를 발명한 사람에게는 고양이가 없었습니다.','published'),
('grade2-10:motivate','grade2-10:motivate','grade2','grade2-10','motivate','동기를 부여하다','verb','They motivate each other to succeed.','그들은 서로 성공하도록 동기를 부여합니다.','The students were asked to motivate something important.','학생들은 중요한 것에 동기를 부여해 달라는 요청을 받았습니다.','published'),
('grade2-10:motivation','grade2-10:motivation','grade2','grade2-10','motivation','동기','noun','We did not understand his motivation.','우리는 그의 동기를 이해하지 못했습니다.','His motivation was at a high level.','그의 동기는 높은 수준이었습니다.','published'),
('grade2-10:narrative','grade2-10:narrative','grade2','grade2-10','narrative','서술','noun','The plot is full of holes, but the narrative is extremely compelling.','줄거리는 구멍으로 가득 차 있지만 내러티브는 매우 설득력이 있습니다.','Everyone discussed the narrative after class.','수업이 끝난 후 모두가 이야기에 대해 토론했습니다.','published'),
('grade2-10:neglect','grade2-10:neglect','grade2','grade2-10','neglect','소홀히 하다','verb','Do not neglect regular maintenance of the equipment.','장비의 정기적인 유지 관리를 게을리하지 마십시오.','Students may struggle if they neglect their basic skills.','학생들이 기본 기술을 소홀히 하면 어려움을 겪을 수 있습니다.','published'),
('grade2-10:neutral','grade2-10:neutral','grade2','grade2-10','neutral','중립적인','adjective','I am neutral regarding the issue of gay marriage.','나는 동성결혼 문제에 대해 중립적이다.','You aren''t neutral because you refuse to acknowledge your agenda.','당신은 당신의 의제를 인정하기를 거부하기 때문에 중립적이지 않습니다.','published'),
('grade2-10:norm','grade2-10:norm','grade2','grade2-10','norm','규범','noun','Working from home has become a common norm.','재택근무는 일반적인 표준이 되었습니다.','The study challenges the traditional norm of the industry.','이번 연구는 업계의 전통적인 규범에 도전합니다.','published'),
('grade2-10:numerous','grade2-10:numerous','grade2','grade2-10','numerous','수많은','adjective','There are numerous definitions of the word ''man''.','''남자''라는 단어에 대한 정의는 다양합니다.','Whistleblowers alleged numerous cases of gross mismanagement, retaliation and investigations into staff that had a debilitating effect.','내부 고발자들은 직원을 쇠약하게 만드는 심각한 관리 부실, 보복 및 조사 사례가 많다고 주장했습니다.','published'),
('grade2-10:obligation','grade2-10:obligation','grade2','grade2-10','obligation','의무','noun','Every right implies a responsibility; every opportunity, an obligation; every possession, a duty.','모든 권리에는 책임이 따릅니다. 모든 기회와 의무; 모든 소유물은 의무입니다.','He is under an obligation to finish the job.','그에게는 그 일을 완수할 의무가 있다.','published'),
('grade2-10:obstacle','grade2-10:obstacle','grade2','grade2-10','obstacle','장애물','noun','Lack of imagination is an obstacle to one''s advancement.','상상력이 부족하면 발전하는 데 장애물이 됩니다.','The poverty of a district is an obstacle to good education.','지역의 빈곤은 좋은 교육에 장애가 됩니다.','published'),
('grade2-11:occupy','grade2-11:occupy','grade2','grade2-11','occupy','차지하다','verb','Books occupy most of the space on the shelf.','책은 선반 공간의 대부분을 차지합니다.','The activity will occupy the students for an hour.','이 활동은 학생들이 한 시간 동안 진행하게 됩니다.','published'),
('grade2-11:operate','grade2-11:operate','grade2','grade2-11','operate','작동하다','verb','We operate on both sides of the border.','우리는 국경 양쪽에서 활동합니다.','The students were asked to operate something important.','학생들은 중요한 작업을 수행하도록 요청 받았습니다.','published'),
('grade2-11:opponent','grade2-11:opponent','grade2','grade2-11','opponent','상대','noun','The racer looked as though he might eat the wall after trying to juke his opponent.','그 경주자는 상대방을 조롱하려고 시도한 후 벽을 먹어치울 것처럼 보였습니다.','Tom made his opponent tap out.','Tom은 상대방을 탭아웃하게 만들었습니다.','published'),
('grade2-11:option','grade2-11:option','grade2','grade2-11','option','선택권','noun','What option did I have?','나에게 어떤 선택권이 있었나요?','That often leaves kids who live in abject poverty with no option but to go around barefoot.','이로 인해 극심한 빈곤 속에 사는 아이들은 맨발로 돌아다니는 것 외에는 선택의 여지가 없는 경우가 많습니다.','published'),
('grade2-11:organic','grade2-11:organic','grade2','grade2-11','organic','유기적인','adjective','Organic remains found in rock.','암석에서 유기물이 발견됩니다.','Is eating organic food worth the money?','유기농 음식을 먹는 게 그만한 값어치가 있어?','published'),
('grade2-11:orient','grade2-11:orient','grade2','grade2-11','orient','방향을 잡다','verb','We had to orient ourselves in the forest.','우리는 숲 속에서 방향을 잡아야 했습니다.','The dean of students tries to orient the freshmen.','학생처장은 신입생들에게 방향을 제시하려고 노력합니다.','published'),
('grade2-11:outstanding','grade2-11:outstanding','grade2','grade2-11','outstanding','뛰어난','adjective','An outstanding fact of our time is that nations poisoned by anti semitism proved less fortunate in regard to their own freedom.','우리 시대의 두드러진 사실은 반유대주의에 오염된 국가들이 자신들의 자유와 관련하여 불행한 것으로 드러났다는 것입니다.','Einstein was one of the outstanding figures of the 20th centurey.','아인슈타인은 20세기의 뛰어난 인물 중 한 명이었습니다.','published'),
('grade2-11:overlook','grade2-11:overlook','grade2','grade2-11','overlook','간과하다','verb','The above ground pool and deck overlook the pasture and rolling hills.','지상 수영장과 데크에서는 목초지와 언덕이 내려다보입니다.','The team may overlook the proposal after careful review.','팀에서는 신중하게 검토한 후 제안을 간과할 수도 있습니다.','published'),
('grade2-11:parallel','grade2-11:parallel','grade2','grade2-11','parallel','평행한','adjective','Find the area of a trapezoid whose parallel sides are 9 and 12 centimeters.','평행한 변의 길이가 9센티미터와 12센티미터인 사다리꼴의 넓이를 구하세요.','Three groups in parallel developed tests as a key parameter for avian influenza and came up with three different solutions.','세 그룹이 동시에 테스트를 조류 인플루엔자에 대한 핵심 매개변수로 개발하고 세 가지 다른 솔루션을 생각해 냈습니다.','published'),
('grade2-11:passive','grade2-11:passive','grade2','grade2-11','passive','수동적인','adjective','Much benevolence of the passive order may be traced to a disinclination to inflict pain upon oneself.','수동적 질서의 많은 자비심은 자신에게 고통을 가하는 것을 싫어하는 데서 유래할 수 있습니다.','Academics seem to favor passive sentences.','학자들은 수동태 문장을 선호하는 것 같습니다.','published'),
('grade2-11:percentage','grade2-11:percentage','grade2','grade2-11','percentage','백분율','noun','Here the air was usually rough and a good percentage of air travelers were troubled with airsickness.','이곳의 공기는 대개 거칠었고 항공 여행자 중 상당수가 멀미로 고생했습니다.','The percentage between the two ideas became clear.','두 아이디어 사이의 비율이 명확해졌습니다.','published'),
('grade2-11:performance','grade2-11:performance','grade2','grade2-11','performance','성과;수행','noun','We congratulated him on his performance at the rehearsal.','리허설에서 그의 공연을 축하했습니다.','They criticised his performance as mayor.','그들은 시장으로서의 그의 성과를 비판했습니다.','published'),
('grade2-11:permission','grade2-11:permission','grade2','grade2-11','permission','허가','noun','He asked permission to leave.','그는 떠나도 좋다는 허락을 구했다.','Guerrilla gardening is gardening on another person''s land without permission.','게릴라 가드닝은 타인의 땅에 허가 없이 정원을 가꾸는 것을 말합니다.','published'),
('grade2-11:persist','grade2-11:persist','grade2','grade2-11','persist','지속하다','verb','The symptoms may persist for several days.','증상은 며칠 동안 지속될 수 있습니다.','If problems persist, ask the teacher for help.','문제가 지속되면 교사에게 도움을 요청하세요.','published'),
('grade2-11:phenomenon','grade2-11:phenomenon','grade2','grade2-11','phenomenon','현상','noun','A volcanic eruption is an impressive phenomenon.','화산 폭발은 인상적인 현상이다.','This is a phenomenon that has repeated itself many times throughout history.','이는 역사 전반에 걸쳐 여러 번 반복된 현상이다.','published'),
('grade2-11:policy','grade2-11:policy','grade2','grade2-11','policy','정책','noun','It was a policy of retribution.','보복 정책이었습니다.','They debated the policy or impolicy of the proposed legislation.','그들은 제안된 법안의 정책이나 중요성에 대해 토론했습니다.','published'),
('grade2-11:pollution','grade2-11:pollution','grade2','grade2-11','pollution','오염','noun','Dredging, pollution and overharvesting led to the disappearance of the oysters decades ago.','준설, 오염 및 과도한 수확으로 인해 수십 년 전에 굴이 사라졌습니다.','I developed a paralyzing fear of pollution after learning about it in first grade.','나는 1학년 때 오염에 대해 배운 후로 오염에 대한 마비된 두려움을 갖게 되었습니다.','published'),
('grade2-11:portion','grade2-11:portion','grade2','grade2-11','portion','부분','noun','I read a portion of the manuscript.','원고의 일부를 읽었습니다.','Success that was her portion.','성공은 그녀의 몫이었습니다.','published'),
('grade2-11:potential','grade2-11:potential','grade2','grade2-11','potential','잠재적인','adjective','Tom had all the potential in the world.','톰은 세상의 모든 잠재력을 갖고 있었습니다.','Researchers have developed a moisturizing lotion with the potential to treat deadly skin cancers, psoriasis and promote diabetic wound healing.','연구자들은 치명적인 피부암, 건선을 치료하고 당뇨병성 상처 치유를 촉진할 수 있는 잠재력을 지닌 보습 로션을 개발했습니다.','published'),
('grade2-11:preference','grade2-11:preference','grade2','grade2-11','preference','선호','noun','My own preference is for good literature.','나는 좋은 문학을 선호합니다.','He has a preference for crisp wines.','그는 산뜻한 와인을 선호합니다.','published'),
('grade2-12:preserve','grade2-12:preserve','grade2','grade2-12','preserve','보존하다','verb','Preserve the peace in the family.','가족의 평화를 유지하십시오.','We preserve these archeological findings.','우리는 이러한 고고학적 발견을 보존합니다.','published'),
('grade2-12:prevention','grade2-12:prevention','grade2','grade2-12','prevention','예방','noun','Money was allocated to study the cause and prevention of influenza.','인플루엔자의 원인과 예방을 연구하기 위해 돈이 할당되었습니다.','Both commemorations are intended to raise awareness of kidney disease and the importance of prevention and early detection.','두 기념식 모두 신장 질환에 대한 인식을 높이고 예방과 조기 발견의 중요성을 알리기 위한 것입니다.','published'),
('grade2-12:principle','grade2-12:principle','grade2','grade2-12','principle','원칙','noun','Tom doesn''t give money to chuggers out of principle.','톰은 원칙적으로 처거들에게 돈을 주지 않습니다.','We cannot mistake absolutism for principle, or substitute spectacle for politics, or treat name-calling as reasoned debate.','우리는 절대주의를 원칙으로 착각할 수 없고, 구경거리를 정치로 대체할 수 없으며, 욕설을 이성적인 논쟁으로 취급할 수 없습니다.','published'),
('grade2-12:procedure','grade2-12:procedure','grade2','grade2-12','procedure','절차','noun','The procedure of obtaining a driver''s license.','운전면허 취득 절차입니다.','The procedure is called catheter ablation because it burns off a small amount of heart muscle.','이 시술은 소량의 심장 근육을 태우기 때문에 카테터 절제술이라고 합니다.','published'),
('grade2-12:productivity','grade2-12:productivity','grade2','grade2-12','productivity','생산성','noun','You can see the computer age everywhere but in the productivity statistics.','생산성 통계를 제외한 모든 곳에서 컴퓨터 수명을 볼 수 있습니다.','Repaying debt leaves less money available for investment in new factories or infrastructure that could increase productivity and create jobs.','부채를 상환하면 생산성을 높이고 일자리를 창출할 수 있는 새로운 공장이나 인프라에 투자할 수 있는 자금이 줄어듭니다.','published'),
('grade2-12:professional','grade2-12:professional','grade2','grade2-12','professional','전문적인','adjective','Professional occupations include medicine and the law and teaching.','전문직에는 의학, 법률, 교육 등이 포함됩니다.','Tom is the only professional musician I know.','톰은 내가 아는 유일한 전문 음악가다.','published'),
('grade2-12:progress','grade2-12:progress','grade2','grade2-12','progress','진전','noun','He listened for the progress of the troops.','그는 군대의 전진을 들었다.','Testing for the new antidote is currently in progress.','현재 새로운 해독제에 대한 테스트가 진행 중입니다.','published'),
('grade2-12:promote','grade2-12:promote','grade2','grade2-12','promote','촉진하다','verb','Researchers have developed a moisturizing lotion with the potential to treat deadly skin cancers, psoriasis and promote diabetic wound healing.','연구자들은 치명적인 피부암, 건선을 치료하고 당뇨병성 상처 치유를 촉진할 수 있는 잠재력을 지닌 보습 로션을 개발했습니다.','Do you promote hygiene at work?','직장에서 위생을 장려합니까?','published'),
('grade2-12:proportion','grade2-12:proportion','grade2','grade2-12','proportion','비율','noun','An inordinate proportion of the book is given over to quotations.','책의 과도한 부분이 인용문으로 제공됩니다.','A dry martini has a large proportion of gin.','드라이 마티니에는 진의 비율이 높습니다.','published'),
('grade2-12:prospect','grade2-12:prospect','grade2','grade2-12','prospect','전망','noun','No peril daunts her, no prospect of fatigue or discomfort disheartens or repels her.','어떤 위험도 그녀를 위협하지 않으며, 어떤 피로나 불편함도 그녀를 낙담시키거나 거부하지 않습니다.','The prospect lasted longer than expected.','전망은 예상보다 오래 지속되었습니다.','published'),
('grade2-12:psychological','grade2-12:psychological','grade2','grade2-12','psychological','심리적인','adjective','I''m concerned about their psychological well-being.','그들의 심리적 안녕이 걱정됩니다.','Prices seem to have stopped rising, having hit the psychological ceiling of just under 100 dollars.','가격은 100달러 미만의 심리적 상한선에 도달하여 상승이 멈춘 것 같습니다.','published'),
('grade2-12:pursue','grade2-12:pursue','grade2','grade2-12','pursue','추구하다','verb','I''m still going to pursue the things I''m interested in.','나는 여전히 내가 관심 있는 일을 추구할 것이다.','If you are a woman, how has your gender impacted your decision to pursue a medical career?','당신이 여성이라면, 당신의 성별이 의료 경력을 추구하기로 한 결정에 어떤 영향을 미쳤습니까?','published'),
('grade2-12:quantity','grade2-12:quantity','grade2','grade2-12','quantity','수량','noun','He had a quantity of ammunition.','그는 많은 양의 탄약을 갖고 있었습니다.','I prefer quality to quantity.','나는 양보다 질을 선호해.','published'),
('grade2-12:random','grade2-12:random','grade2','grade2-12','random','무작위의','adjective','The plowing is according to the furrow; the harvest, rather at random.','밭갈이는 고랑을 따라 갑니다. 수확은 오히려 무작위입니다.','You can''t trust some random person off a personals site.','개인 사이트에서 임의의 사람을 믿을 수는 없습니다.','published'),
('grade2-12:rational','grade2-12:rational','grade2','grade2-12','rational','합리적인','adjective','The set of real numbers is uncountable, and, therefore, it''s larger than the set of rational numbers.','실수 집합은 셀 수 없으므로 유리수 집합보다 큽니다.','But how can you find rational pleasure in spinning round like a teetotum in a room of eighty degrees temperature?','그러나 온도가 80도인 방에서 티토툼처럼 둥글게 돌고 있는 데서 어떻게 이성적인 즐거움을 찾을 수 있습니까?','published'),
('grade2-12:reality','grade2-12:reality','grade2','grade2-12','reality','현실','noun','For them demons were as much a part of reality as trees were.','그들에게 악마는 나무와 마찬가지로 현실의 일부였습니다.','The reality of his situation slowly dawned on him.','자신이 처한 상황의 현실이 서서히 그에게 떠올랐다.','published'),
('grade2-12:recognition','grade2-12:recognition','grade2','grade2-12','recognition','인식','noun','The partners were delighted with the recognition of their work.','파트너들은 자신의 작업이 인정되어 기뻐했습니다.','She seems to avoid much in the way of recognition or acknowledgement of feminist work prior to her own.','그녀는 자신의 작품에 앞서 페미니스트 작품을 인정하거나 인정하는 방식을 많이 피하는 것 같습니다.','published'),
('grade2-12:recruit','grade2-12:recruit','grade2','grade2-12','recruit','모집하다','verb','The club plans to recruit new members this semester.','동아리는 이번 학기에 신입회원을 모집할 계획이다.','The company will recruit engineers for the new project.','회사는 새 프로젝트를 위해 엔지니어를 모집할 예정이다.','published'),
('grade2-12:reference','grade2-12:reference','grade2','grade2-12','reference','참고;언급','noun','It is used as a reference for comparing the heating and the electrical energy involved.','이는 난방과 관련된 전기 에너지를 비교하기 위한 참고 자료로 사용됩니다.','He contributed articles to the basic reference work on that topic.','그는 해당 주제에 대한 기본 참고 자료에 기사를 기고했습니다.','published'),
('grade2-12:reform','grade2-12:reform','grade2','grade2-12','reform','개혁','noun','Justice was for sale before the reform of the law courts.','법원이 개혁되기 전에는 정의가 팔렸습니다.','The family rejoiced in the drunkard''s reform.','가족은 술고래의 개혁을 기뻐했습니다.','published'),
('grade2-13:regard','grade2-13:regard','grade2','grade2-13','regard','여기다;관점','verb','At its best, postmodernism is a stance of humility with regard to our ability to correctly understand reality.','최선을 다해 포스트모더니즘은 현실을 올바르게 이해하는 능력에 관한 겸손의 입장입니다.','All the naughts in the universe are equal to one naught alone, in regard to their substance and value.','우주의 모든 무(無)는 그 실체와 가치 면에서 단 하나의 무와 같습니다.','published'),
('grade2-13:regulate','grade2-13:regulate','grade2','grade2-13','regulate','규제하다','verb','We cannot regulate the way people dress.','우리는 사람들이 옷을 입는 방식을 규제할 수 없습니다.','This town likes to regulate.','이 마을은 규제하는 걸 좋아해요.','published'),
('grade2-13:reinforce','grade2-13:reinforce','grade2','grade2-13','reinforce','강화하다','verb','The right homework will reinforce and complement the lesson!','올바른 숙제는 수업을 강화하고 보완할 것입니다!','Advertising for fast food can reinforce unhealthy dietary tendencies.','패스트푸드 광고는 건강에 해로운 식습관 경향을 강화할 수 있습니다.','published'),
('grade2-13:relevant','grade2-13:relevant','grade2','grade2-13','relevant','관련 있는','adjective','The scientist corresponds with colleagues in order to learn about matters relevant to her own research.','과학자는 자신의 연구와 관련된 문제에 대해 배우기 위해 동료들과 연락합니다.','We all have experienced the serendipity of relevant information arriving just when we were least expecting it.','우리 모두는 전혀 예상하지 못한 순간에 관련 정보가 우연히 도착하는 것을 경험해 왔습니다.','published'),
('grade2-13:reluctant','grade2-13:reluctant','grade2','grade2-13','reluctant','꺼리는','adjective','They were usually reluctant to socialize.','그들은 대개 사교 활동을 꺼렸습니다.','Foreigners stubbornly reluctant to accept our ways.','외국인들은 우리의 방식을 고집스럽게 받아들이기를 꺼려합니다.','published'),
('grade2-13:represent','grade2-13:represent','grade2','grade2-13','represent','대표하다','verb','I represent the silent majority.','나는 침묵하는 다수를 대표합니다.','Braille is a code that uses bumps and indentation on a surface to represent letters, which can be recognized by touch.','점자는 문자를 표현하기 위해 표면의 돌기와 들여쓰기를 사용하여 터치로 인식할 수 있는 코드입니다.','published'),
('grade2-13:request','grade2-13:request','grade2','grade2-13','request','요청하다','verb','It wasn''t a serious request.','그것은 진지한 요구가 아니었습니다.','It isn''t a serious request.','심각한 요구는 아닙니다.','published'),
('grade2-13:rescue','grade2-13:rescue','grade2','grade2-13','rescue','구조하다','verb','Esther''s cat is a rescue.','에스더의 고양이는 구조입니다.','I entered this contest and wrote a jingle for them about rescue animals and I won $100,000.','저는 이 콘테스트에 참가하여 동물 구조에 관한 노래를 작곡하여 $100,000를 받았습니다.','published'),
('grade2-13:resist','grade2-13:resist','grade2','grade2-13','resist','저항하다','verb','I couldn''t resist a touch of schadenfreude when he was defeated so heavily in the election.','그가 선거에서 크게 패배했을 때 나는 샤덴프로이데의 손길을 거부할 수 없었습니다.','We''re starting a collective to resist negligent landlords.','우리는 태만한 집주인에 저항하기 위해 집단을 시작하고 있습니다.','published'),
('grade2-13:resource','grade2-13:resource','grade2','grade2-13','resource','자원','noun','The local library is a valuable resource.','지역 도서관은 귀중한 자원입니다.','Bitcoin is fiat by definition, since it cannot be exchanged for a fixed amount of any physical resource.','비트코인은 정의상 법정화폐입니다. 왜냐하면 고정된 양의 물리적 자원과 교환될 수 없기 때문입니다.','published'),
('grade2-13:responsibility','grade2-13:responsibility','grade2','grade2-13','responsibility','책임','noun','Every right implies a responsibility; every opportunity, an obligation; every possession, a duty.','모든 권리에는 책임이 따릅니다. 모든 기회와 의무; 모든 소유물은 의무입니다.','He holds a position of great responsibility.','그는 막중한 책임을 맡고 있는 위치에 있습니다.','published'),
('grade2-13:restrict','grade2-13:restrict','grade2','grade2-13','restrict','제한하다','verb','The move gives authorities greater latitude to forcibly restrict public gatherings and enforce quarantines on those with the virus.','이번 조치로 인해 당국은 공개 모임을 강제로 제한하고 바이러스에 감염된 사람들에 대한 격리를 시행할 수 있는 더 큰 재량권을 갖게 되었습니다.','The team may restrict the proposal after careful review.','팀에서는 신중한 검토 후 제안을 제한할 수 있습니다.','published'),
('grade2-13:restriction','grade2-13:restriction','grade2','grade2-13','restriction','제한','noun','The city imposed a restriction on water use.','시에서는 물 사용을 제한했습니다.','This age restriction protects younger viewers.','이 연령 제한은 어린 시청자를 보호합니다.','published'),
('grade2-13:reveal','grade2-13:reveal','grade2','grade2-13','reveal','드러내다','verb','The actress won''t reveal how old she is.','여배우는 자신의 나이를 밝히지 않을 것입니다.','He didn''t reveal his secret.','그는 자신의 비밀을 밝히지 않았다.','published'),
('grade2-13:reverse','grade2-13:reverse','grade2','grade2-13','reverse','뒤집다','verb','To reverse a portion of video footage.','비디오 장면의 일부를 반전합니다.','To reverse a judgment, sentence, or decree.','판결이나 선고, 법령을 취소하다.','published'),
('grade2-13:reward','grade2-13:reward','grade2','grade2-13','reward','보상','noun','Virtue is its own reward.','미덕은 그 자체로 보상입니다.','The machine gives a food reward when your rat presses a lever.','쥐가 레버를 누르면 기계가 음식 보상을 제공합니다.','published'),
('grade2-13:satisfaction','grade2-13:satisfaction','grade2','grade2-13','satisfaction','만족','noun','The chef tasted the sauce with great satisfaction.','요리사는 매우 만족스럽게 소스를 맛보았습니다.','We were unable to get satisfaction from the local store.','우리는 현지 매장에서 만족을 얻을 수 없었습니다.','published'),
('grade2-13:scheme','grade2-13:scheme','grade2','grade2-13','scheme','계획;체계','noun','Capitalism is a pyramid scheme.','자본주의는 피라미드 구조이다.','Cryptocurrency is a pyramid scheme.','암호화폐는 피라미드 방식입니다.','published'),
('grade2-13:scope','grade2-13:scope','grade2','grade2-13','scope','범위','noun','A variable of global scope can be referenced anywhere in the program.','전역 범위의 변수는 프로그램의 어느 곳에서나 참조될 수 있습니다.','Tom looked through the scope on his rifle.','톰은 소총의 조준경을 들여다보았습니다.','published'),
('grade2-13:seek','grade2-13:seek','grade2','grade2-13','seek','찾다','verb','I seek forgiveness through prayer.','나는 기도를 통해 용서를 구합니다.','Our company does not seek to limit its employees from using the internet or engaging in social networking.','우리 회사는 직원의 인터넷 사용이나 소셜 네트워킹 참여를 제한하려고 하지 않습니다.','published'),
('grade2-14:sequence','grade2-14:sequence','grade2','grade2-14','sequence','순서','noun','The sequence of names was alphabetical.','이름의 순서는 알파벳순이었습니다.','He invented a technique to determine the sequence of base pairs in DNA.','그는 DNA의 염기쌍 서열을 결정하는 기술을 발명했습니다.','published'),
('grade2-14:shift','grade2-14:shift','grade2','grade2-14','shift','이동;변화','noun','Just last week she bought a new shift at the market.','바로 지난주에 그녀는 시장에서 새로운 교대 근무를 구입했습니다.','There was a shift in the political atmosphere.','정치적 분위기에 변화가 생겼다.','published'),
('grade2-14:significant','grade2-14:significant','grade2','grade2-14','significant','중요한','adjective','The interaction effect is significant at the .01 level.','상호작용 효과는 .01 수준에서 유의미합니다.','No significant difference was found.','유의미한 차이는 발견되지 않았습니다.','published'),
('grade2-14:simulate','grade2-14:simulate','grade2','grade2-14','simulate','모의실험하다','verb','He and his colleagues used an artificial material in the lab to simulate a surface like the tissue inside an infected person.','그와 그의 동료들은 실험실에서 인공 물질을 사용하여 감염된 사람 내부의 조직과 같은 표면을 시뮬레이션했습니다.','The students were asked to simulate something important.','학생들은 중요한 것을 시뮬레이션하도록 요청 받았습니다.','published'),
('grade2-14:simultaneous','grade2-14:simultaneous','grade2','grade2-14','simultaneous','동시의','adjective','The two experiments produced simultaneous changes.','두 실험은 동시에 변화를 가져왔습니다.','Simultaneous translation allows listeners to follow the speech immediately.','동시통역을 통해 청취자는 연설 내용을 즉시 따라갈 수 있습니다.','published'),
('grade2-14:solid','grade2-14:solid','grade2','grade2-14','solid','단단한','adjective','Ice is water in the solid state.','얼음은 고체 상태의 물입니다.','Carved out of solid rock.','단단한 바위를 깎아 만든 것입니다.','published'),
('grade2-14:specialist','grade2-14:specialist','grade2','grade2-14','specialist','전문가','noun','I''m studying to become a peer support specialist.','저는 동료 지원 전문가가 되기 위해 공부하고 있습니다.','Mary joined the space program as a mission specialist.','Mary는 임무 전문가로 우주 프로그램에 참여했습니다.','published'),
('grade2-14:stable','grade2-14:stable','grade2','grade2-14','stable','안정적인','adjective','I''m a very stable genius.','나는 매우 안정적인 천재입니다.','I''m not very emotionally stable.','나는 감정적으로 매우 안정되지 않습니다.','published'),
('grade2-14:stimulate','grade2-14:stimulate','grade2','grade2-14','stimulate','자극하다','verb','This herbal infusion doesn''t stimulate.','이 허브 주입은 자극을 주지 않습니다.','But the latest findings may stimulate research into cures for the parasitic illnesses.','그러나 최신 연구 결과는 기생충 질환 치료법에 대한 연구를 자극할 수 있습니다.','published'),
('grade2-14:strategy','grade2-14:strategy','grade2','grade2-14','strategy','전략','noun','It is a colonial divide-and-conquer strategy to pit religious people against one another.','종교인들을 서로 대립시키려는 식민지 분할정복 전략이다.','When I have a panic attack, my best strategy for coping with it is to accept whatever I''m afraid of.','공황 발작이 일어났을 때 대처하기 위한 최선의 전략은 내가 두려워하는 모든 것을 받아들이는 것입니다.','published'),
('grade2-14:strengthen','grade2-14:strengthen','grade2','grade2-14','strengthen','강화하다','verb','This exercise will strengthen your upper body.','이 운동은 상체를 강화시켜 줍니다.','We must strengthen our alliance.','우리는 동맹을 강화해야 합니다.','published'),
('grade2-14:submit','grade2-14:submit','grade2','grade2-14','submit','제출하다','verb','I submit to you that the accused is guilty.','피고인이 유죄임을 알려드립니다.','Tom is supposed to submit the report by the end of play.','톰은 플레이가 끝날 때까지 보고서를 제출하기로 되어 있습니다.','published'),
('grade2-14:substance','grade2-14:substance','grade2','grade2-14','substance','물질','noun','DNA is the substance of our genes.','DNA는 우리 유전자의 물질이다.','Terms like "woke" and "cancel culture" are used by the right as filler to disguise the lack of substance in their arguments.','권리에서는 "깨어남" 및 "문화 취소"와 같은 용어를 주장의 실체 부족을 위장하기 위해 보충용으로 사용합니다.','published'),
('grade2-14:sufficient','grade2-14:sufficient','grade2','grade2-14','sufficient','충분한','adjective','There is not sufficient access to the internet in many small rural villages.','많은 소규모 시골 마을에는 인터넷 접속이 충분하지 않습니다.','A two-week training course is sufficient to get a job in the coach-driving profession.','코치 운전직에 취업하려면 2주간의 훈련 과정이면 충분합니다.','published'),
('grade2-14:superior','grade2-14:superior','grade2','grade2-14','superior','우월한','adjective','Superior wisdom derived from experience.','경험에서 우월한 지혜가 나옵니다.','Overcome by a superior opponent.','우월한 상대에게 압도당함.','published'),
('grade2-14:supply','grade2-14:supply','grade2','grade2-14','supply','공급하다','verb','To supply money for the war.','전쟁 자금을 공급하기 위해.','To supply a furnace with fuel; to supply soldiers with ammunition.','용광로에 연료를 공급하려면 군인들에게 탄약을 공급하기 위해','published'),
('grade2-14:sustain','grade2-14:sustain','grade2','grade2-14','sustain','유지하다','verb','The money will sustain our good cause.','그 돈은 우리의 좋은 목적을 뒷받침해 줄 것입니다.','Provisions to sustain an army.','군대를 유지하기 위한 규정.','published'),
('grade2-14:symbol','grade2-14:symbol','grade2','grade2-14','symbol','상징','noun','$ is the symbol for dollars in the US and some other countries.','$는 미국과 일부 다른 국가에서 달러를 나타내는 기호입니다.','The lion is the symbol of courage; the lamb is the symbol of meekness or patience.','사자는 용기의 상징입니다. 어린 양은 온유함이나 인내의 상징입니다.','published'),
('grade2-14:target','grade2-14:target','grade2','grade2-14','target','목표','noun','Tom aimed at the target.','톰은 표적을 겨눴다.','Try to get more exposure to your target language.','목표 언어에 더 많이 노출되도록 노력하십시오.','published'),
('grade2-14:temperature','grade2-14:temperature','grade2','grade2-14','temperature','온도','noun','The temperature in the room dropped nearly 20 degrees; it went from hot to cold.','방의 온도는 거의 20도나 떨어졌습니다. 더위에서 추위로 바뀌었습니다.','Nitrous oxide is inert at room temperature.','아산화질소는 실온에서 불활성입니다.','published'),
('grade2-15:tension','grade2-15:tension','grade2','grade2-15','tension','긴장','noun','He suffered from fatigue and emotional tension.','그는 피로와 정서적 긴장에 시달렸습니다.','It places great tension on the leg muscles.','다리 근육에 큰 긴장을 줍니다.','published'),
('grade2-15:threat','grade2-15:threat','grade2','grade2-15','threat','위협','noun','They were under threat of arrest.','그들은 체포 위협을 받았습니다.','Disease is a threat to human beings.','질병은 인류에게 있어서 위협이야.','published'),
('grade2-15:trace','grade2-15:trace','grade2','grade2-15','trace','흔적;추적하다','noun','There wasn''t a trace of evidence for the claim.','주장에 대한 증거는 흔적도 없었습니다.','Your cell phone company can put a trace on your line.','귀하의 휴대전화 회사에서 귀하의 회선에 대한 추적을 할 수 있습니다.','published'),
('grade2-15:transform','grade2-15:transform','grade2','grade2-15','transform','변형시키다','verb','Education can transform a student''s future.','교육은 학생의 미래를 변화시킬 수 있습니다.','Heat can transform water into steam.','열은 물을 증기로 변화시킬 수 있습니다.','published'),
('grade2-15:transportation','grade2-15:transportation','grade2','grade2-15','transportation','운송','noun','We have to get people out of their cars and encourage them to use alternative forms of transportation.','우리는 사람들을 차에서 내려 대체 교통수단을 이용하도록 권장해야 합니다.','Nice transportation, dude, but your brake lights are busted.','교통은 좋은데 브레이크등이 고장났어요.','published'),
('grade2-15:trigger','grade2-15:trigger','grade2','grade2-15','trigger','촉발하다','verb','A poor rifle, here it is: short barrel, huge trigger.','불쌍한 소총, 여기 있습니다: 짧은 총신, 거대한 방아쇠.','I''ve got an itchy trigger finger.','방아쇠손가락이 가려워요.','published'),
('grade2-15:undergo','grade2-15:undergo','grade2','grade2-15','undergo','겪다','verb','She had to undergo surgery because of her broken leg.','그녀는 다리가 부러져 수술을 받아야 했습니다.','The test is not always accurate, so many men undergo a painful second test, a biopsy of the prostate.','이 검사가 항상 정확하지는 않기 때문에 많은 남성이 고통스러운 두 번째 검사인 전립선 생검을 받습니다.','published'),
('grade2-15:undertake','grade2-15:undertake','grade2','grade2-15','undertake','착수하다','verb','The team will undertake a detailed review of the data.','팀은 데이터를 자세히 검토할 것입니다.','Students undertake independent research in the final semester.','학생들은 마지막 학기에 독립적인 연구를 수행합니다.','published'),
('grade2-15:unemployment','grade2-15:unemployment','grade2','grade2-15','unemployment','실업','noun','Unemployment is a serious social evil.','실업은 심각한 사회악이다.','The rate of unemployment is an indicator of the health of an economy.','실업률은 경제의 건전성을 나타내는 지표입니다.','published'),
('grade2-15:uniform','grade2-15:uniform','grade2','grade2-15','uniform','균일한','adjective','There will never be a uniform and universally accepted standard for determining the boundaries of languages and dialects.','언어와 방언의 경계를 결정하는 통일되고 보편적으로 받아들여지는 표준은 결코 존재하지 않을 것입니다.','We had to wear a uniform.','우리는 유니폼을 입어야 했어요.','published'),
('grade2-15:urban','grade2-15:urban','grade2','grade2-15','urban','도시의','adjective','Zimbabwe''s food situation in both urban and rural areas remained precarious in 2006.','짐바브웨의 도시와 농촌 지역의 식량 상황은 2006년에도 여전히 불안정했습니다.','Urban renewal is another way of saying gentrification.','도시재생은 젠트리피케이션을 말하는 또 다른 표현이다.','published'),
('grade2-15:valid','grade2-15:valid','grade2','grade2-15','valid','타당한','adjective','The license is still valid.','라이센스는 아직 유효합니다.','Occupying powers never consider an insurgency''s cause to be valid.','점령 세력은 결코 반란의 원인이 타당하다고 생각하지 않습니다.','published'),
('grade2-15:variation','grade2-15:variation','grade2','grade2-15','variation','변화;변형','noun','Any variation in his routine was immediately reported.','그의 일상에 변화가 생기면 즉시 보고되었습니다.','An emery wheel is the modern variation of a grindstone.','에머리 휠은 숫돌의 현대적인 변형입니다.','published'),
('grade2-15:version','grade2-15:version','grade2','grade2-15','version','버전','noun','His version of the fight was different from mine.','그의 싸움 버전은 나와 달랐습니다.','Do you have the most recent version of this software?','이 소프트웨어의 가장 최신 버전을 갖고 있어?','published'),
('grade2-15:violate','grade2-15:violate','grade2','grade2-15','violate','위반하다','verb','Violate the basic laws or human civilization.','기본법이나 인류 문명을 위반합니다.','Violate the sanctity of the church.','교회의 거룩함을 훼손합니다.','published'),
('grade2-15:visibility','grade2-15:visibility','grade2','grade2-15','visibility','가시성','noun','Low visibility caused by fog.','안개로 인해 시야가 좋지 않습니다.','That candidate does not have sufficient visibility to win an election.','해당 후보자는 선거에서 승리할 만큼 가시성이 충분하지 않습니다.','published'),
('grade2-15:vital','grade2-15:vital','grade2','grade2-15','vital','필수적인','adjective','They are now drawing lessons to make sure that rumors and misinformation will never again scuttle a vital health campaign.','그들은 이제 소문과 잘못된 정보가 다시는 중요한 건강 캠페인을 방해하지 않도록 교훈을 얻고 있습니다.','Mary played a vital role in the child care program during the crisis.','메리는 위기 상황 동안 보육 프로그램에서 중요한 역할을 했습니다.','published'),
('grade2-15:voluntary','grade2-15:voluntary','grade2','grade2-15','voluntary','자발적인','adjective','Man is a voluntary agent.','인간은 자발적인 행위자이다.','Once all the voluntary evacuations have taken place, then we will concentrate our efforts and our forces to mandatorily evacuate individuals.','모든 자발적 대피가 완료되면 우리는 개인의 강제 대피에 모든 노력과 힘을 집중할 것입니다.','published'),
('grade2-15:widespread','grade2-15:widespread','grade2','grade2-15','widespread','널리 퍼진','adjective','Human rights violations, misogyny and exclusion are widespread and systematic.','인권침해, 여성혐오, 배제는 광범위하고 체계적입니다.','The BMJ editorial describes oppression against women and girls as a great injustice that is insidious, systematic and widespread.','BMJ 사설은 여성과 소녀에 대한 억압을 교활하고 체계적이며 널리 퍼져 있는 큰 불의로 묘사합니다.','published'),
('grade2-15:witness','grade2-15:witness','grade2','grade2-15','witness','목격자;목격하다','noun','Her photographic memory makes her a great witness.','그녀의 사진 기억력은 그녀를 훌륭한 증인으로 만듭니다.','The defense attorneys cast aspersions on the probity of the witness.','변호인들은 증인의 정직성을 비난했습니다.','published'),
('grade3-01:abdicate','grade3-01:abdicate','grade3','grade3-01','abdicate','포기하다;퇴위하다','verb','The aging king chose to abdicate the throne.','나이 많은 왕은 왕위를 포기하기로 결정했습니다.','A leader should not abdicate responsibility during a crisis.','리더는 위기 상황에서 책임을 회피해서는 안 된다.','published'),
('grade3-01:abide','grade3-01:abide','grade3','grade3-01','abide','준수하다','verb','All participants must abide by the competition rules.','모든 참가자는 대회 규정을 준수해야 합니다.','The company agreed to abide by the court''s decision.','회사는 법원의 결정을 따르기로 동의했습니다.','published'),
('grade3-01:abstain','grade3-01:abstain','grade3','grade3-01','abstain','삼가다','verb','I abstain from this vote, as I have no particular preference.','나는 특별히 선호하는 바가 없기 때문에 이번 투표에 기권합니다.','People often abstain under pressure.','사람들은 압력을 받으면 기권하는 경우가 많습니다.','published'),
('grade3-01:abundance','grade3-01:abundance','grade3','grade3-01','abundance','풍부함','noun','I went to my garden and found abundance.','나는 내 정원에 가서 풍요로움을 발견했습니다.','The report clearly described the abundance.','보고서는 풍부함을 명확하게 설명했습니다.','published'),
('grade3-01:academic','grade3-01:academic','grade3','grade3-01','academic','학문적인','adjective','I have always had an academic interest in hacking.','저는 항상 해킹에 학문적 관심을 갖고 있었습니다.','I''m more academic than athletic — I get lower marks in phys. ed. than in anything else.','나는 운동보다는 학문에 더 가깝습니다. 체육에서 낮은 점수를 받았습니다. 에드. 다른 것보다.','published'),
('grade3-01:acclaim','grade3-01:acclaim','grade3','grade3-01','acclaim','칭송하다','verb','By his twenties, the young virtuoso had won international acclaim for his lyrical, powerful and disciplined artistry.','20대가 되자 이 젊은 거장은 서정적이고 강력하며 절제된 예술성으로 국제적인 찬사를 받았습니다.','The band''s final album was met with universal acclaim.','밴드의 마지막 앨범은 전 세계의 호평을 받았습니다.','published'),
('grade3-01:accredit','grade3-01:accredit','grade3','grade3-01','accredit','인가하다','verb','MISA says the electoral commission should accredit all journalists without conditions.','MISA는 선거관리위원회가 조건 없이 모든 언론인을 승인해야 한다고 말합니다.','The students were asked to accredit something important.','학생들은 중요한 것을 인정해 달라는 요청을 받았습니다.','published'),
('grade3-01:acidic','grade3-01:acidic','grade3','grade3-01','acidic','산성의','adjective','Lemon juice is acidic and tastes sour.','레몬즙은 산성이고 신맛이 난다.','The plant cannot grow well in highly acidic soil.','식물은 산성도가 높은 토양에서는 잘 자랄 수 없습니다.','published'),
('grade3-01:acquittal','grade3-01:acquittal','grade3','grade3-01','acquittal','무죄 판결','noun','The new evidence led to the defendant''s acquittal.','새로운 증거는 피고인의 무죄를 선고했습니다.','Her acquittal ended the long criminal trial.','그녀의 무죄 판결로 오랜 형사 재판이 끝났습니다.','published'),
('grade3-01:addict','grade3-01:addict','grade3','grade3-01','addict','중독자','noun','He is an addict when it comes to chocolate cookies.','그는 초콜릿 쿠키의 중독자입니다.','I used to be a heroin addict.','나는 한때 헤로인 중독자였어.','published'),
('grade3-01:adjacent','grade3-01:adjacent','grade3','grade3-01','adjacent','인접한','adjective','Because the conference room is filled, we will have our meeting in the adjacent room.','회의실이 꽉 차서 바로 옆방에서 회의를 하게 되었습니다.','The picture is on the adjacent page.','사진은 옆 페이지에 있습니다.','published'),
('grade3-01:aesthetic','grade3-01:aesthetic','grade3','grade3-01','aesthetic','미적인','adjective','The illustrations made the book an aesthetic success.','삽화는 이 책을 미학적 성공으로 이끌었습니다.','It works well enough, but the shabby exterior offends his aesthetic sensibilities.','그것은 충분히 잘 작동하지만 초라한 외관은 그의 미적 감각을 상하게 합니다.','published'),
('grade3-01:affirm','grade3-01:affirm','grade3','grade3-01','affirm','확언하다','verb','They did everything they could to affirm the children''s self-confidence.','그들은 아이들의 자신감을 확인하기 위해 최선을 다했습니다.','The students were asked to affirm something important.','학생들은 중요한 것을 확인해 달라는 요청을 받았습니다.','published'),
('grade3-01:aggravate','grade3-01:aggravate','grade3','grade3-01','aggravate','악화시키다','verb','Lack of sleep can aggravate the symptoms.','잠이 부족하면 증상이 악화될 수 있습니다.','His careless remark may aggravate the conflict.','그의 부주의한 발언이 갈등을 악화시킬 수도 있다.','published'),
('grade3-01:albeit','grade3-01:albeit','grade3','grade3-01','albeit','비록 ~일지라도','conjunction','The task was difficult, albeit possible.','가능하긴 했지만 그 일은 어려웠습니다.','The room was small, albeit comfortable.','방은 작았지만 편안했습니다.','published'),
('grade3-01:allege','grade3-01:allege','grade3','grade3-01','allege','주장하다','verb','Witnesses allege that the company hid important evidence.','증인들은 회사가 중요한 증거를 숨겼다고 주장합니다.','The report does not allege any criminal conduct.','보고서는 어떠한 범죄 행위도 주장하지 않습니다.','published'),
('grade3-01:alliance','grade3-01:alliance','grade3','grade3-01','alliance','동맹','noun','Through their unholy alliance, the ambitious campaign manager and the morally compromised politician make their way to the top.','야심찬 캠페인 관리자와 도덕적으로 타협한 정치인은 그들의 불경스러운 동맹을 통해 정상에 오르게 됩니다.','The intergalactic alliance was in danger of collapsing.','은하계 동맹이 붕괴될 위험에 처해 있었습니다.','published'),
('grade3-01:ambiguity','grade3-01:ambiguity','grade3','grade3-01','ambiguity','모호성','noun','His speech was made with such great ambiguity that neither supporter nor opponent could be certain of his true position.','그의 연설은 너무나 모호하여 지지자도 반대자도 그의 진정한 입장을 확신할 수 없었다.','In the face of ambiguity, refuse the temptation to guess.','모호함에 직면하여 추측하려는 유혹을 거부하십시오.','published'),
('grade3-01:amendment','grade3-01:amendment','grade3','grade3-01','amendment','수정안','noun','The amendment is still pending ratification.','개정안은 아직 비준을 기다리고 있다.','The amendment required careful planning.','개정안에는 신중한 계획이 필요했습니다.','published'),
('grade3-01:amplify','grade3-01:amplify','grade3','grade3-01','amplify','증폭하다','verb','It was a mistake to amplify this debate with thoughtless responses.','경솔한 답변으로 이 논쟁을 증폭시킨 것은 실수였습니다.','The pattern could amplify over time.','패턴은 시간이 지남에 따라 증폭될 수 있습니다.','published'),
('grade3-02:anarchy','grade3-02:anarchy','grade3','grade3-02','anarchy','무정부 상태','noun','Anarchy is order without power.','무정부 상태는 힘이 없는 질서이다.','Anarchy isn''t a lack of rules; it''s a lack of rulers.','무정부 상태는 규칙이 부족한 것이 아닙니다. 그것은 통치자의 부족입니다.','published'),
('grade3-02:animosity','grade3-02:animosity','grade3','grade3-02','animosity','적개심','noun','Years of conflict created deep animosity between the groups.','수년간의 갈등으로 인해 그룹간에 깊은 적대감이 생겼습니다.','She spoke without animosity toward her former opponent.','그녀는 이전 상대에 대해 적대감 없이 말했습니다.','published'),
('grade3-02:anonymous','grade3-02:anonymous','grade3','grade3-02','anonymous','익명의','adjective','An anonymous donor paid for the new library books.','익명의 기부자가 도서관의 새 도서 구입 비용을 지불했습니다.','The survey allows students to remain anonymous.','설문조사를 통해 학생들은 익명을 유지할 수 있습니다.','published'),
('grade3-02:antidote','grade3-02:antidote','grade3','grade3-02','antidote','해독제','noun','The doctor quickly gave the patient an antidote.','의사는 신속하게 환자에게 해독제를 투여했습니다.','There is no simple antidote to online misinformation.','온라인상의 잘못된 정보에 대한 간단한 해독제는 없습니다.','published'),
('grade3-02:applaud','grade3-02:applaud','grade3','grade3-02','applaud','박수치다;칭찬하다','verb','One hand alone cannot applaud.','한 손만으로는 박수를 보낼 수 없습니다.','The students may applaud after the announcement.','발표 후 학생들은 박수를 보낼 수 있습니다.','published'),
('grade3-02:apprehend','grade3-02:apprehend','grade3','grade3-02','apprehend','이해하다;체포하다','verb','It took time to apprehend the meaning of the poem.','시의 의미를 이해하는 데 시간이 걸렸습니다.','Police were able to apprehend the suspect quickly.','경찰은 용의자를 신속하게 체포할 수 있었다.','published'),
('grade3-02:arduous','grade3-02:arduous','grade3','grade3-02','arduous','고된','adjective','Worked their arduous way up the mining valley.','광산 계곡 위로 힘든 길을 일했습니다.','Your willingness after these six arduous days to remain here.','이 힘든 6일을 보낸 후에도 여기에 머물겠다는 의지입니다.','published'),
('grade3-02:ascend','grade3-02:ascend','grade3','grade3-02','ascend','오르다','verb','Inheritance may not ascend linearly.','상속은 선형적으로 올라갈 수 없습니다.','Who of those who have been cast down by sin shall ascend?','죄로 인해 버림받은 자 중에 누가 올라갈 것인가?','published'),
('grade3-02:aspiration','grade3-02:aspiration','grade3','grade3-02','aspiration','열망','noun','Her greatest aspiration is to become a scientist.','그녀의 가장 큰 소망은 과학자가 되는 것이다.','Education can help students achieve their aspiration.','교육은 학생들이 자신의 열망을 달성하는 데 도움이 될 수 있습니다.','published'),
('grade3-02:assurance','grade3-02:assurance','grade3','grade3-02','assurance','확신;보장','noun','His assurance in his superiority did not make him popular.','자신의 우월성에 대한 확신은 그를 인기 있게 만들지 못했습니다.','An assurance of help when needed.','필요할 때 도움을 받을 수 있다는 보장.','published'),
('grade3-02:atrocity','grade3-02:atrocity','grade3','grade3-02','atrocity','잔혹 행위','noun','Atrocity crimes are imminent unless there is a cessation of hostilities.','적대 행위가 중단되지 않는 한 잔혹 범죄는 임박해 있습니다.','Her atrocity helped the team solve the problem.','그녀의 잔혹함은 팀이 문제를 해결하는 데 도움이 되었습니다.','published'),
('grade3-02:attentive','grade3-02:attentive','grade3','grade3-02','attentive','주의 깊은','adjective','The nurse was attentive to her patient.','간호사는 환자에게 세심한 주의를 기울였습니다.','She is an attentive listener, but does not like to talk much.','그녀는 주의 깊게 경청하지만 말을 많이 하는 것을 좋아하지 않습니다.','published'),
('grade3-02:authentic','grade3-02:authentic','grade3','grade3-02','authentic','진정한','adjective','The museum displayed an authentic ancient vase.','박물관에는 진짜 고대 꽃병이 전시되어 있었습니다.','Her honest response felt authentic to the audience.','그녀의 솔직한 대답은 청중들에게 진정성 있게 느껴졌습니다.','published'),
('grade3-02:autonomy','grade3-02:autonomy','grade3','grade3-02','autonomy','자율성','noun','How much of your own autonomy are you ceding to these people?','당신은 이 사람들에게 당신 자신의 자율성을 얼마나 양보하고 있습니까?','Bodily autonomy is a human right.','신체의 자율성은 인권이다.','published'),
('grade3-02:avert','grade3-02:avert','grade3','grade3-02','avert','피하다;막다','verb','To avert the eyes from an object.','물체로부터 눈을 돌리다.','We need to act now if we want to avert disaster.','재난을 피하려면 지금 행동해야 합니다.','published'),
('grade3-02:backlash','grade3-02:backlash','grade3','grade3-02','backlash','반발','noun','There was a backlash of intolerance.','편협함의 반발이있었습니다.','The public backlash to the proposal was quick and insistent.','이 제안에 대한 대중의 반발은 빠르고 집요했습니다.','published'),
('grade3-02:barren','grade3-02:barren','grade3','grade3-02','barren','불모의','adjective','The war left the land barren and lifeless.','전쟁으로 인해 땅은 황폐해지고 생명이 없게 되었습니다.','The reviewers considered the final result barren.','리뷰어들은 최종 결과가 불모지라고 생각했습니다.','published'),
('grade3-02:benevolence','grade3-02:benevolence','grade3','grade3-02','benevolence','자비','noun','The charity was founded through the benevolence of local citizens.','이 자선단체는 지역 주민들의 자비로 설립되었습니다.','His benevolence earned the trust of the community.','그의 자비심은 지역 사회의 신뢰를 얻었습니다.','published'),
('grade3-02:bilateral','grade3-02:bilateral','grade3','grade3-02','bilateral','양자 간의','adjective','The two countries signed a bilateral trade agreement.','양국은 양자 무역협정을 체결했다.','Bilateral talks helped reduce tension along the border.','양자 회담은 국경의 긴장을 완화하는 데 도움이 되었습니다.','published'),
('grade3-02:bleak','grade3-02:bleak','grade3','grade3-02','bleak','암울한','adjective','A bleak future is in store for you.','당신에게는 암울한 미래가 기다리고 있습니다.','But with an official camp recently opened specifically to accommodate them, some have chosen to remain in the bleak shelter.','그러나 최근 그들을 수용하기 위해 특별히 공식 캠프가 열리면서 일부 사람들은 황량한 보호소에 남아 있기를 선택했습니다.','published'),
('grade3-03:bolster','grade3-03:bolster','grade3','grade3-03','bolster','강화하다','verb','You need some evidence to bolster your claim.','귀하의 주장을 뒷받침하려면 몇 가지 증거가 필요합니다.','The team may bolster the proposal after careful review.','팀은 신중하게 검토한 후 제안을 강화할 수 있습니다.','published'),
('grade3-03:brittle','grade3-03:brittle','grade3','grade3-03','brittle','부서지기 쉬운','adjective','A brittle and calculating woman.','까칠하고 계산적인 여자.','A diamond is hard but brittle.','다이아몬드는 단단하지만 부서지기 쉽습니다.','published'),
('grade3-03:bureaucracy','grade3-03:bureaucracy','grade3','grade3-03','bureaucracy','관료제','noun','A complex bureaucracy can delay simple decisions.','복잡한 관료제는 단순한 결정을 지연시킬 수 있습니다.','The reform aims to make the bureaucracy more efficient.','개혁의 목표는 관료제를 더욱 효율적으로 만드는 것입니다.','published'),
('grade3-03:calibrate','grade3-03:calibrate','grade3','grade3-03','calibrate','정밀 조정하다','verb','Technicians calibrate the instrument before every experiment.','기술자는 모든 실험 전에 기기를 교정합니다.','We must calibrate the scale to ensure accurate results.','정확한 결과를 얻으려면 저울을 교정해야 합니다.','published'),
('grade3-03:capricious','grade3-03:capricious','grade3','grade3-03','capricious','변덕스러운','adjective','Authoritarian rulers are frequently capricious.','권위주의적인 통치자는 종종 변덕스럽습니다.','The final decision seemed capricious to everyone involved.','최종 결정은 관련된 모든 사람에게 변덕스러운 것처럼 보였습니다.','published'),
('grade3-03:causality','grade3-03:causality','grade3','grade3-03','causality','인과관계','noun','The study found correlation but did not prove causality.','이번 연구에서는 상관관계는 발견됐지만 인과관계는 입증되지 않았다.','Researchers designed another experiment to test causality.','연구자들은 인과관계를 테스트하기 위해 또 다른 실험을 설계했습니다.','published'),
('grade3-03:censor','grade3-03:censor','grade3','grade3-03','censor','검열하다','verb','The government attempted to censor the critical article.','정부는 비판적인 기사를 검열하려고 시도했습니다.','Editors should not censor opinions simply because they disagree.','편집자는 단지 의견이 다르다는 이유만으로 의견을 검열해서는 안 됩니다.','published'),
('grade3-03:chronic','grade3-03:chronic','grade3','grade3-03','chronic','만성적인','adjective','The chronic irascible gossiper is evidently a characteristic type of person who has specialized in this mode of reaction to anger.','만성적으로 화를 잘 내는 수다쟁이는 분명히 분노에 대한 이러한 반응 방식을 전문으로 하는 사람의 특징적인 유형입니다.','COPD, chronic obstructive pulmonary disease, blocks airflow through the lungs.','만성폐쇄성폐질환인 COPD는 폐를 통한 공기 흐름을 차단합니다.','published'),
('grade3-03:circumscribe','grade3-03:circumscribe','grade3','grade3-03','circumscribe','제한하다','verb','Strict rules may circumscribe a teacher''s freedom.','엄격한 규칙으로 인해 교사의 자유가 제한될 수 있습니다.','The constitution can circumscribe the power of government.','헌법은 정부의 권력을 제한할 수 있다.','published'),
('grade3-03:cite','grade3-03:cite','grade3','grade3-03','cite','인용하다','verb','Students cite the cost of flights, and worries about renewing visas as the main reasons for not traveling.','학생들은 여행을 하지 않는 주된 이유로 비행 비용과 비자 갱신에 대한 걱정을 꼽습니다.','The students were asked to cite something important.','학생들은 중요한 내용을 인용해 달라는 요청을 받았습니다.','published'),
('grade3-03:cognitive','grade3-03:cognitive','grade3','grade3-03','cognitive','인지의','adjective','Cognitive behavioral therapy doesn''t work for everything or everyone.','인지 행동 치료는 모든 사람 또는 모든 사람에게 효과가 있는 것은 아닙니다.','Have you tried cognitive behavioral therapy?','인지행동치료를 받아보셨나요?','published'),
('grade3-03:cohesion','grade3-03:cohesion','grade3','grade3-03','cohesion','결속력','noun','Team activities can strengthen cohesion among students.','팀 활동은 학생들 간의 결속력을 강화할 수 있습니다.','The repeated theme gives the essay greater cohesion.','반복되는 주제는 에세이의 응집력을 더욱 높여줍니다.','published'),
('grade3-03:collaborate','grade3-03:collaborate','grade3','grade3-03','collaborate','협력하다','verb','Let''s collaborate on this project, and get it finished faster.','이 프로젝트에 협력하여 더 빨리 완료하도록 합시다.','If you collaborate with the occupying forces, you will be shot.','점령군과 협력하면 총살당합니다.','published'),
('grade3-03:commemorate','grade3-03:commemorate','grade3','grade3-03','commemorate','기념하다','verb','The ceremony will commemorate those who served the country.','이번 행사는 나라를 위해 봉사한 분들을 기리는 행사입니다.','A monument was built to commemorate the historic event.','역사적인 사건을 기념하기 위해 기념비가 세워졌습니다.','published'),
('grade3-03:commend','grade3-03:commend','grade3','grade3-03','commend','칭찬하다','verb','His paintings commend him to the artistic world.','그의 그림은 그를 예술계에 소개합니다.','I commend my children to you.','나는 내 자녀들을 당신께 추천합니다.','published'),
('grade3-03:compatible','grade3-03:compatible','grade3','grade3-03','compatible','양립 가능한','adjective','Her deeds were compatible with her ideology.','그녀의 행동은 그녀의 이념과 일치했습니다.','The pillow vowed to never bring compatible people together.','베개는 호환되는 사람들을 결코 하나로 모으지 않겠다고 맹세했습니다.','published'),
('grade3-03:complacency','grade3-03:complacency','grade3','grade3-03','complacency','자기만족','noun','His complacency was absolutely disgusting.','그의 안일함은 정말 역겨웠습니다.','She expressed her complacency honestly.','그녀는 솔직하게 자신의 안도감을 표현했다.','published'),
('grade3-03:complement','grade3-03:complement','grade3','grade3-03','complement','보완하다','verb','I need some pepper to complement the sweet touch in the soup.','수프의 달콤한 맛을 보완하려면 후추가 필요해요.','The students were asked to complement something important.','학생들은 중요한 것을 보완해 달라는 요청을 받았습니다.','published'),
('grade3-03:complicate','grade3-03:complicate','grade3','grade3-03','complicate','복잡하게 하다','verb','Don''t complicate yourself in issues that are beyond the scope of your understanding.','당신의 이해 범위를 넘어서는 문제로 자신을 복잡하게 만들지 마십시오.','The team may complicate the proposal after careful review.','팀에서는 신중하게 검토한 후 제안을 복잡하게 만들 수 있습니다.','published'),
('grade3-03:compulsion','grade3-03:compulsion','grade3','grade3-03','compulsion','강박;강제','noun','He felt a compulsion to babble on about the accident.','그는 그 사고에 대해 횡설수설하고 싶은 충동을 느꼈다.','Her compulsion to wash her hands repeatedly.','손을 반복적으로 씻어야 한다는 강박관념.','published'),
('grade3-04:conceive','grade3-04:conceive','grade3','grade3-04','conceive','상상하다;생각해 내다','verb','Assisted procreation can help those trying to conceive.','출산 지원은 임신을 시도하는 사람들에게 도움이 될 수 있습니다.','The students were asked to conceive something important.','학생들은 중요한 것을 생각해 보라고 요청 받았습니다.','published'),
('grade3-04:concurrence','grade3-04:concurrence','grade3','grade3-04','concurrence','동의;동시 발생','noun','The plan requires the concurrence of all committee members.','이 계획에는 모든 위원회 구성원의 동의가 필요합니다.','The concurrence of the two events surprised the researchers.','두 사건의 동시 발생은 연구자들을 놀라게 했습니다.','published'),
('grade3-04:condescend','grade3-04:condescend','grade3','grade3-04','condescend','거들먹거리다','verb','Good leaders do not condescend to less experienced workers.','좋은 리더는 경험이 부족한 직원을 우대하지 않습니다.','She refused to condescend to the young students.','그녀는 어린 학생들에게 굴복하는 것을 거부했습니다.','published'),
('grade3-04:confidential','grade3-04:confidential','grade3','grade3-04','confidential','기밀의','adjective','This arrangement must be kept confidential.','이 합의는 비밀로 유지되어야 합니다.','The reviewers considered the final result confidential.','검토자들은 최종 결과를 기밀로 간주했습니다.','published'),
('grade3-04:conform','grade3-04:conform','grade3','grade3-04','conform','따르다;순응하다','verb','The backrest should conform to the natural curvature of your spine, and provide adequate lumbar support.','등받이는 척추의 자연스러운 곡선에 맞춰야 하며 요추를 적절하게 지지해야 합니다.','The situation may conform without warning.','상황은 예고 없이 바뀔 수도 있습니다.','published'),
('grade3-04:conjecture','grade3-04:conjecture','grade3','grade3-04','conjecture','추측','noun','He dismissed it as mere conjecture.','그는 이를 단순한 추측이라고 일축했다.','Her conjecture changed after she reviewed the evidence.','그녀의 추측은 증거를 검토한 후 바뀌었습니다.','published'),
('grade3-04:conscientious','grade3-04:conscientious','grade3','grade3-04','conscientious','양심적인','adjective','A conscientious decision to speak out about injustice.','불의에 대해 목소리를 높이는 양심적인 결정입니다.','Undoubtedly we ought to be conscientious and we ought to fear and regret evil.','의심할 바 없이 우리는 양심적이어야 하며 악을 두려워하고 후회해야 합니다.','published'),
('grade3-04:consolidate','grade3-04:consolidate','grade3','grade3-04','consolidate','통합하다;강화하다','verb','The measures are part of efforts to consolidate its increasingly authoritarian grip.','이번 조치는 점점 더 권위주의적인 지배력을 강화하려는 노력의 일환입니다.','They continued to consolidate their leadership position in that space.','그들은 계속해서 그 분야에서 리더십 위치를 공고히 했습니다.','published'),
('grade3-04:constrain','grade3-04:constrain','grade3','grade3-04','constrain','제약하다','verb','A limited budget may constrain our choices.','제한된 예산으로 인해 선택이 제한될 수 있습니다.','Social expectations can constrain individual behavior.','사회적 기대는 개인의 행동을 제한할 수 있습니다.','published'),
('grade3-04:contemplate','grade3-04:contemplate','grade3','grade3-04','contemplate','숙고하다','verb','She sat quietly to contemplate her future.','그녀는 자신의 미래를 생각하기 위해 조용히 앉아 있었습니다.','The city is beginning to contemplate a new transport system.','도시는 새로운 교통 시스템을 고려하기 시작했습니다.','published'),
('grade3-04:contingency','grade3-04:contingency','grade3','grade3-04','contingency','우발 사태','noun','We should have a contingency plan.','우리는 비상 계획을 세워야 합니다.','Contingency plans in some countries include quarantining families when any family member contracts the disease.','일부 국가의 비상 계획에는 가족 구성원이 질병에 걸릴 경우 가족을 격리하는 것이 포함됩니다.','published'),
('grade3-04:contradictory','grade3-04:contradictory','grade3','grade3-04','contradictory','모순되는','noun','The president has voiced a wide range of often contradictory views.','대통령은 종종 모순되는 다양한 견해를 표명했습니다.','Transphobes usually preface their transphobic rants with the contradictory statement, "I don''t care who you are or what you do.".','트랜스혐오자들은 일반적으로 “당신이 누구인지, 무엇을 하는지는 상관하지 않습니다.”라는 모순된 말로 트랜스혐오적인 폭언을 시작합니다.','published'),
('grade3-04:converge','grade3-04:converge','grade3','grade3-04','converge','수렴하다','verb','The two paths converge near the river.','두 길은 강 근처에서 수렴됩니다.','Our opinions began to converge after a long discussion.','우리의 의견은 오랜 토론 끝에 수렴되기 시작했습니다.','published'),
('grade3-04:conviction','grade3-04:conviction','grade3','grade3-04','conviction','확신;유죄 판결','noun','The conviction came as no surprise.','유죄 판결은 전혀 놀랄 일이 아니었습니다.','Nothing could sway his conviction.','그 어떤 것도 그의 신념을 꺾을 수 없었다.','published'),
('grade3-04:corroborate','grade3-04:corroborate','grade3','grade3-04','corroborate','뒷받침하다','verb','I can corroborate his story.','나는 그의 이야기를 확증할 수 있다.','The students were asked to corroborate something important.','학생들은 중요한 것을 확증해 달라는 요청을 받았습니다.','published'),
('grade3-04:counteract','grade3-04:counteract','grade3','grade3-04','counteract','대응하다;상쇄하다','verb','This will counteract the foolish actions of my colleagues.','이것은 내 동료들의 어리석은 행동에 대응할 것입니다.','The coach may counteract the players during practice.','코치는 연습 중에 선수에게 반격을 가할 수 있습니다.','published'),
('grade3-04:counterpart','grade3-04:counterpart','grade3','grade3-04','counterpart','상대방;대응물','noun','The minister met her Japanese counterpart in Seoul.','장관은 서울에서 일본 측 장관을 만났다.','This phone is cheaper than its newer counterpart.','이 전화기는 최신 전화기보다 가격이 저렴합니다.','published'),
('grade3-04:credible','grade3-04:credible','grade3','grade3-04','credible','믿을 만한','adjective','She was not the...credible fool he expected.','그녀는 그가 기대했던... 믿을만한 바보가 아니었습니다.','The websites of some predatory publishers look credible.','일부 약탈적인 게시자의 웹사이트는 신뢰할 만해 보입니다.','published'),
('grade3-04:culpable','grade3-04:culpable','grade3','grade3-04','culpable','비난받아 마땅한','adjective','I am culpable for stealing your money.','나는 당신의 돈을 훔친 책임이 있습니다.','The reviewers considered the final result culpable.','검토자들은 최종 결과가 과실이 있다고 생각했습니다.','published'),
('grade3-04:curtail','grade3-04:curtail','grade3','grade3-04','curtail','축소하다','verb','The new rules may curtail unnecessary spending.','새로운 규정은 불필요한 지출을 줄일 수 있습니다.','Heavy rain forced organizers to curtail the outdoor event.','폭우로 인해 주최측은 야외 행사를 축소했습니다.','published'),
('grade3-05:decentralize','grade3-05:decentralize','grade3','grade3-05','decentralize','분권화하다','verb','The reform aims to decentralize political power.','이번 개혁은 정치권력을 분권하는 것을 목표로 한다.','The company decided to decentralize its decision-making process.','회사는 의사결정 과정을 분산화하기로 결정했습니다.','published'),
('grade3-05:decisive','grade3-05:decisive','grade3','grade3-05','decisive','결정적인','adjective','Two factors had a decisive influence.','두 가지 요인이 결정적인 영향을 미쳤습니다.','Had a decisive lead in the polls.','여론조사에서 결정적인 우위를 점했습니다.','published'),
('grade3-05:deem','grade3-05:deem','grade3','grade3-05','deem','여기다','verb','The court may deem the evidence unreliable.','법원은 증거가 신뢰할 수 없다고 판단할 수도 있습니다.','Officials deem the building safe for public use.','당국은 이 건물이 대중이 사용하기에 안전하다고 간주합니다.','published'),
('grade3-05:deficient','grade3-05:deficient','grade3','grade3-05','deficient','부족한','adjective','The diet was deficient in several essential vitamins.','식단에는 몇 가지 필수 비타민이 부족했습니다.','The report is deficient in reliable evidence.','보고서에는 신뢰할만한 증거가 부족합니다.','published'),
('grade3-05:degrade','grade3-05:degrade','grade3','grade3-05','degrade','저하시키다','verb','Pollution can degrade the quality of drinking water.','오염은 식수의 질을 저하시킬 수 있습니다.','Repeated heat may degrade the material over time.','반복적인 열은 시간이 지남에 따라 재료의 품질을 저하시킬 수 있습니다.','published'),
('grade3-05:delicate','grade3-05:delicate','grade3','grade3-05','delicate','섬세한','adjective','A kite too delicate to fly safely.','너무 연약해서 안전하게 날 수 없는 연입니다.','The reviewers considered the final result delicate.','검토자들은 최종 결과가 미묘하다고 생각했습니다.','published'),
('grade3-05:demographic','grade3-05:demographic','grade3','grade3-05','demographic','인구통계학적인','adjective','Republicans have been implementing ways to ensure undemocratic minority rule, because their core demographic is shrinking.','공화당은 핵심 인구가 줄어들고 있기 때문에 비민주적인 소수 지배를 보장하는 방법을 시행해 왔습니다.','While some countries are in position to reap a ''demographic dividend,'' others must prepare to care for a much older population.','일부 국가에서는 ''인구학적 배당금''을 얻을 수 있는 위치에 있지만 다른 국가에서는 훨씬 더 나이 많은 인구를 돌볼 준비를 해야 합니다.','published'),
('grade3-05:denounce','grade3-05:denounce','grade3','grade3-05','denounce','공개적으로 비난하다','verb','My sentences are original: this is why those who shamelessly plagiarize me denounce themselves.','내 문장은 독창적입니다. 뻔뻔하게 나를 표절하는 사람들이 자신을 비난하는 이유입니다.','The team may denounce the proposal after careful review.','팀은 신중한 검토 후 제안을 거부할 수 있습니다.','published'),
('grade3-05:deprivation','grade3-05:deprivation','grade3','grade3-05','deprivation','박탈','noun','Losing him is no great deprivation.','그를 잃는 것은 큰 박탈감이 아닙니다.','Tom is in a sensory deprivation tank.','톰은 감각 차단 탱크에 있습니다.','published'),
('grade3-05:desolation','grade3-05:desolation','grade3','grade3-05','desolation','황폐','noun','The feeling of desolation entered my heart; I sorrowed in tears, and life almost became a weariness.','황량한 느낌이 내 마음에 들어왔습니다. 나는 눈물을 흘리며 슬퍼했고, 생활은 거의 지칠 뻔했습니다.','The desolation lasted longer than expected.','황폐화는 예상보다 오래 지속되었습니다.','published'),
('grade3-05:deter','grade3-05:deter','grade3','grade3-05','deter','단념시키다','verb','Tom installed security cameras on his property to deter thieves.','톰은 도둑을 막기 위해 자신의 집에 보안 카메라를 설치했습니다.','Police presence in the neighborhood was increased as a measure to deter crime.','범죄를 예방하기 위한 조치로 인근 지역에 경찰의 배치가 강화되었습니다.','published'),
('grade3-05:deterrent','grade3-05:deterrent','grade3','grade3-05','deterrent','억제책','noun','A visible security camera can act as a deterrent to theft.','눈에 보이는 보안 카메라는 도난을 방지하는 역할을 할 수 있습니다.','High costs are a major deterrent for small businesses.','높은 비용은 중소기업의 주요 장애물입니다.','published'),
('grade3-05:devastate','grade3-05:devastate','grade3','grade3-05','devastate','황폐화하다','verb','Economic experts warn that lockdowns could devastate the country’s economy, which is already inhibited by international sanctions.','경제 전문가들은 봉쇄가 이미 국제 제재로 인해 억제되고 있는 국가 경제를 황폐화시킬 수 있다고 경고합니다.','The team may devastate the proposal after careful review.','팀에서는 신중하게 검토한 후 제안을 폐기할 수 있습니다.','published'),
('grade3-05:devise','grade3-05:devise','grade3','grade3-05','devise','고안하다','verb','Devise a plan to take over the director''s office.','이사직을 인수할 계획을 세웁니다.','We need to devise a plan.','우리는 계획을 세워야 합니다.','published'),
('grade3-05:dignity','grade3-05:dignity','grade3','grade3-05','dignity','존엄','noun','It was beneath his dignity to cheat.','속이는 것은 그의 존엄성을 훼손하는 일이었습니다.','Showed his true dignity when under pressure.','압박을 받을 때 진정한 위엄을 보여주었습니다.','published'),
('grade3-05:diminish','grade3-05:diminish','grade3','grade3-05','diminish','줄어들다','verb','An experiment on obese rats found that consuming probiotics for 30 days helps diminish the accumulation of fat in the liver.','비만 쥐를 대상으로 한 실험에서 30일 동안 프로바이오틱스를 섭취하면 간에 지방이 축적되는 것을 줄이는 데 도움이 되는 것으로 나타났습니다.','The pattern could diminish over time.','시간이 지남에 따라 패턴이 줄어들 수 있습니다.','published'),
('grade3-05:discern','grade3-05:discern','grade3','grade3-05','discern','분별하다','verb','It was difficult to discern his face in the darkness.','어둠 속에서 그의 얼굴을 알아보기가 어려웠다.','Careful readers can discern a change in the writer''s tone.','주의 깊은 독자는 작가의 어조의 변화를 알아차릴 수 있습니다.','published'),
('grade3-05:discreet','grade3-05:discreet','grade3','grade3-05','discreet','신중한','adjective','She was discreet when discussing the private matter.','그녀는 사적인 문제를 논의할 때 신중했습니다.','A discreet sign marked the entrance to the office.','사무실 입구에는 눈에 띄는 표지판이 표시되어 있었습니다.','published'),
('grade3-05:discretion','grade3-05:discretion','grade3','grade3-05','discretion','재량','noun','The servants showed great tact and discretion.','하인들은 뛰어난 재치와 분별력을 보여주었습니다.','They worked together to improve the discretion.','그들은 재량권을 향상시키기 위해 함께 노력했습니다.','published'),
('grade3-05:disguise','grade3-05:disguise','grade3','grade3-05','disguise','변장하다;위장','verb','Algerians disguise the socio-political reality of their country by pride and hypocrisy.','알제리인들은 자만심과 위선으로 자국의 사회정치적 현실을 위장합니다.','Terms like "woke" and "cancel culture" are used by the right as filler to disguise the lack of substance in their arguments.','권리에서는 "깨어남" 및 "문화 취소"와 같은 용어를 주장의 실체 부족을 위장하기 위해 보충용으로 사용합니다.','published'),
('grade3-06:disintegrate','grade3-06:disintegrate','grade3','grade3-06','disintegrate','붕괴하다','verb','The old paper began to disintegrate in the damp air.','오래된 종이는 습한 공기 속에서 분해되기 시작했습니다.','Without trust, the alliance may slowly disintegrate.','신뢰가 없으면 동맹은 서서히 무너질 수 있습니다.','published'),
('grade3-06:disparity','grade3-06:disparity','grade3','grade3-06','disparity','격차','noun','The report revealed a large disparity in income.','보고서는 소득 격차가 크다는 사실을 드러냈다.','Education can help reduce the disparity between regions.','교육은 지역 간 격차를 줄이는 데 도움이 될 수 있습니다.','published'),
('grade3-06:dispute','grade3-06:dispute','grade3','grade3-06','dispute','분쟁','noun','He had a dispute with his wife.','그는 아내와 논쟁을 벌였습니다.','Once two people involved in a dispute have explained themselves, they arrange a compromise.','분쟁에 연루된 두 사람이 자신의 입장을 설명하면 타협을 주선합니다.','published'),
('grade3-06:dissipate','grade3-06:dissipate','grade3','grade3-06','dissipate','흩어지다','verb','The morning fog began to dissipate after sunrise.','아침 안개는 해가 뜨고 나서 걷히기 시작했습니다.','Her anxiety started to dissipate as the interview continued.','그녀의 불안감은 인터뷰가 계속되면서 사라지기 시작했다.','published'),
('grade3-06:distort','grade3-06:distort','grade3','grade3-06','distort','왜곡하다','verb','A curved mirror can distort your reflection.','곡면 거울은 반사를 왜곡할 수 있습니다.','Leaving out evidence may distort the truth.','증거를 생략하면 진실이 왜곡될 수 있습니다.','published'),
('grade3-06:doctrine','grade3-06:doctrine','grade3','grade3-06','doctrine','원칙;교리','noun','The course examines a major legal doctrine.','이 과정에서는 주요 법률 교리를 검토합니다.','The organization changed its doctrine after the debate.','조직은 토론 후 교리를 변경했습니다.','published'),
('grade3-06:dormant','grade3-06:dormant','grade3','grade3-06','dormant','휴면 상태의','adjective','Her feelings of affection are dormant but easily awakened.','그녀의 애정 감정은 잠자고 있지만 쉽게 깨어납니다.','The final decision seemed dormant to everyone involved.','최종 결정은 관련된 모든 사람에게 휴면 상태인 것처럼 보였습니다.','published'),
('grade3-06:dwindle','grade3-06:dwindle','grade3','grade3-06','dwindle','점차 줄어들다','verb','Food supplies began to dwindle during the long journey.','긴 여행 동안 식량 공급이 줄어들기 시작했습니다.','Attendance may dwindle if the program loses support.','프로그램이 지원을 잃으면 출석률이 줄어들 수 있습니다.','published'),
('grade3-06:eclectic','grade3-06:eclectic','grade3','grade3-06','eclectic','절충적인','adjective','The restaurant offers an eclectic mix of international dishes.','레스토랑은 다양한 세계 각국의 요리를 선보입니다.','Her eclectic taste includes jazz, folk, and classical music.','그녀의 다양한 취향에는 재즈, 포크, 클래식 음악이 포함됩니다.','published'),
('grade3-06:elaboration','grade3-06:elaboration','grade3','grade3-06','elaboration','상세한 설명','noun','An elaboration of the sketch followed.','스케치의 정교화가 이어졌습니다.','The elaboration required careful planning.','정교화에는 신중한 계획이 필요했습니다.','published'),
('grade3-06:elicit','grade3-06:elicit','grade3','grade3-06','elicit','이끌어 내다','verb','Did you elicit a response?','반응을 이끌어냈나요?','The students were asked to elicit something important.','학생들은 중요한 것을 이끌어내도록 요청받았습니다.','published'),
('grade3-06:emancipate','grade3-06:emancipate','grade3','grade3-06','emancipate','해방하다','verb','We anarchists do not want to emancipate the people; we want the people to emancipate themselves.','우리 무정부주의자들은 인민을 해방시키고 싶어하지 않습니다. 우리는 사람들이 스스로 해방되기를 바랍니다.','The teacher could emancipate a student after class.','교사는 수업이 끝난 후 학생을 해방시킬 수 있습니다.','published'),
('grade3-06:embellish','grade3-06:embellish','grade3','grade3-06','embellish','꾸미다','verb','To embellish a story, the truth.','이야기, 진실을 꾸미기 위해.','Men may embellish their look with gloves or a top hat if they desire.','남성은 원할 경우 장갑이나 모자로 외모를 꾸밀 수 있습니다.','published'),
('grade3-06:embrace','grade3-06:embrace','grade3','grade3-06','embrace','받아들이다;포옹하다','verb','I wholeheartedly embrace the new legislation.','나는 새로운 법안을 진심으로 지지합니다.','Now is the time to embrace our nation''s multiculturalism and seize the opportunity to appeal to new and growing demographics.','지금은 우리 나라의 다문화주의를 포용하고 새롭게 증가하는 인구 통계에 호소할 수 있는 기회를 포착해야 할 때입니다.','published'),
('grade3-06:empirical','grade3-06:empirical','grade3','grade3-06','empirical','실증적인','adjective','An empirical treatment of a disease about which little is known.','거의 알려지지 않은 질병에 대한 경험적 치료법입니다.','In its more extreme variants, cis ideology can include denial of the empirical reality of intersex and transgender people.','보다 극단적인 변형인 시스 이데올로기는 간성과 트랜스젠더의 경험적 현실을 부정하는 것을 포함할 수 있습니다.','published'),
('grade3-06:endanger','grade3-06:endanger','grade3','grade3-06','endanger','위험에 빠뜨리다','verb','Plastic waste can endanger marine animals.','플라스틱 폐기물은 해양 동물을 위험에 빠뜨릴 수 있습니다.','Driving while tired may endanger other people.','피곤한 상태에서 운전하면 다른 사람에게 위험을 초래할 수 있습니다.','published'),
('grade3-06:enforce','grade3-06:enforce','grade3','grade3-06','enforce','시행하다','verb','The police are there to enforce the law.','경찰은 법을 집행하기 위해 존재합니다.','The victim was able to enforce his evidence against the alleged perpetrator.','피해자는 가해자 혐의에 대해 자신의 증거를 강화할 수 있었습니다.','published'),
('grade3-06:enrich','grade3-06:enrich','grade3','grade3-06','enrich','풍요롭게 하다','verb','There are no good flags, only good people working together to enrich each other and their society.','좋은 깃발은 없습니다. 오직 좋은 사람들만이 서로와 사회를 풍요롭게 하기 위해 함께 노력할 뿐입니다.','The team may enrich the proposal after careful review.','팀은 신중한 검토를 거쳐 제안을 강화할 수 있습니다.','published'),
('grade3-06:enthusiastic','grade3-06:enthusiastic','grade3','grade3-06','enthusiastic','열정적인','adjective','Enthusiastic crowds filled the streets.','열정적인 군중이 거리를 가득 채웠습니다.','Was enthusiastic about taking ballet lessons.','발레 레슨을 받는 것에 열의를 보였습니다.','published'),
('grade3-06:enumerate','grade3-06:enumerate','grade3','grade3-06','enumerate','열거하다','verb','A pronoun is a word used in place of a noun, to indicate or enumerate persons or things without naming them.','대명사는 명사를 대신하여 사람이나 사물을 명명하지 않고 나타내거나 나열하는 단어입니다.','There are too many to enumerate here.','여기에 열거하기에는 너무 많습니다.','published'),
('grade3-07:epidemic','grade3-07:epidemic','grade3','grade3-07','epidemic','유행병','noun','The people responsible for the opioid epidemic will never face any consequences.','오피오이드 전염병에 책임이 있는 사람들은 결코 어떤 결과도 직면하지 않을 것입니다.','Xylazine is proof that the heroin epidemic is intentionally being inflicted on people.','자일라진은 헤로인 전염병이 의도적으로 사람들에게 가해지고 있다는 증거입니다.','published'),
('grade3-07:equitable','grade3-07:equitable','grade3','grade3-07','equitable','공정한','adjective','The committee sought an equitable solution for everyone.','위원회는 모든 사람을 위한 공평한 해결책을 모색했습니다.','Students deserve equitable access to educational resources.','학생들은 교육 자원에 공평하게 접근할 자격이 있습니다.','published'),
('grade3-07:eradicate','grade3-07:eradicate','grade3','grade3-07','eradicate','근절하다','verb','The campaign aims to eradicate the disease completely.','이 캠페인은 질병을 완전히 근절하는 것을 목표로 합니다.','Education can help eradicate harmful misconceptions.','교육은 해로운 오해를 근절하는 데 도움이 될 수 있습니다.','published'),
('grade3-07:erroneous','grade3-07:erroneous','grade3','grade3-07','erroneous','잘못된','adjective','The article was based on erroneous information.','해당 기사는 잘못된 정보를 기반으로 작성되었습니다.','An erroneous assumption can lead to a false conclusion.','잘못된 가정은 잘못된 결론으로 이어질 수 있습니다.','published'),
('grade3-07:essence','grade3-07:essence','grade3','grade3-07','essence','본질','noun','Privacy protects the essence of who we are.','개인 정보 보호는 우리가 누구인지의 본질을 보호합니다.','What is the essence of the soul?','영혼의 본질은 무엇인가?','published'),
('grade3-07:eternal','grade3-07:eternal','grade3','grade3-07','eternal','영원한','adjective','We''re not immortal, but we are eternal.','우리는 불멸은 아니지만 영원합니다.','The mountains are eternal witnesses.','산들은 영원한 증인이다.','published'),
('grade3-07:evade','grade3-07:evade','grade3','grade3-07','evade','피하다','verb','They tend to evade their responsibilities.','그들은 책임을 회피하는 경향이 있습니다.','This difficult idea seems to evade her.','이 어려운 생각은 그녀를 회피하는 것 같습니다.','published'),
('grade3-07:exacerbation','grade3-07:exacerbation','grade3','grade3-07','exacerbation','악화','noun','His foolishness was followed by an exacerbation of their quarrel.','그의 어리석음은 그들의 다툼을 더욱 악화시켰습니다.','The team completed the exacerbation before the deadline.','팀은 마감일 이전에 악화를 완료했습니다.','published'),
('grade3-07:exemplify','grade3-07:exemplify','grade3','grade3-07','exemplify','예시하다','verb','Her actions exemplify courage and responsibility.','그녀의 행동은 용기와 책임감을 보여줍니다.','These buildings exemplify modern Korean architecture.','이 건물들은 현대 한국 건축의 전형적인 예입니다.','published'),
('grade3-07:exhaustive','grade3-07:exhaustive','grade3','grade3-07','exhaustive','철저한','adjective','The committee conducted an exhaustive review of the evidence.','위원회는 증거를 철저히 검토했습니다.','This short list is useful but not exhaustive.','이 짧은 목록은 유용하지만 완전한 것은 아닙니다.','published'),
('grade3-07:exotic','grade3-07:exotic','grade3','grade3-07','exotic','이국적인','adjective','They kayaked through mangroves and saw many exotic birds.','그들은 맹그로브 숲 사이로 카약을 타고 많은 이국적인 새들을 보았습니다.','The reviewers considered the final result exotic.','리뷰어들은 최종 결과가 이색적이라고 생각했습니다.','published'),
('grade3-07:expedite','grade3-07:expedite','grade3','grade3-07','expedite','신속히 처리하다','verb','This should expedite the process.','이렇게 하면 프로세스가 가속화됩니다.','I will try to expedite the matter.','문제를 신속하게 처리하도록 노력하겠습니다.','published'),
('grade3-07:expulsion','grade3-07:expulsion','grade3','grade3-07','expulsion','추방','noun','Repeated misconduct may lead to expulsion from school.','반복적인 위법 행위는 학교에서 퇴학을 당할 수 있습니다.','The committee reviewed the student''s expulsion carefully.','위원회는 학생의 퇴학을 주의 깊게 검토했습니다.','published'),
('grade3-07:extinguish','grade3-07:extinguish','grade3','grade3-07','extinguish','끄다','verb','Firefighters worked quickly to extinguish the fire.','소방대원들은 화재 진압을 위해 재빠르게 움직였습니다.','Use water to extinguish the small campfire completely.','작은 모닥불을 완전히 끄려면 물을 사용하세요.','published'),
('grade3-07:extrapolate','grade3-07:extrapolate','grade3','grade3-07','extrapolate','외삽하다;추정하다','verb','Researchers should not extrapolate broad conclusions from one case.','연구자들은 하나의 사례에서 광범위한 결론을 추론해서는 안 됩니다.','We can extrapolate future demand from the current trend.','현재 추세를 통해 미래 수요를 추정할 수 있습니다.','published'),
('grade3-07:fallacious','grade3-07:fallacious','grade3','grade3-07','fallacious','그릇된','adjective','The argument sounds convincing but is fallacious.','이 주장은 설득력 있게 들리지만 오류가 있다.','The claim rests on a fallacious assumption about human behavior.','이 주장은 인간 행동에 대한 잘못된 가정에 기초하고 있습니다.','published'),
('grade3-07:favorable','grade3-07:favorable','grade3','grade3-07','favorable','호의적인','adjective','He received a favorable rating.','그는 호평을 받았습니다.','Listened with a favorable ear.','호의적인 귀로 들었습니다.','published'),
('grade3-07:fervent','grade3-07:fervent','grade3','grade3-07','fervent','열렬한','adjective','A fervent desire to change society.','사회를 변화시키려는 뜨거운 열망.','The fervent heat...merely communicated a genial warmth to their half-torpid systems.','그 뜨거운 열기는... 반쯤 무감각해진 시스템에 온화한 온기를 전달했을 뿐입니다.','published'),
('grade3-07:finite','grade3-07:finite','grade3','grade3-07','finite','유한한','adjective','The "goes" in "he goes" is a finite form of a verb.','"he goes"의 "goes"는 동사의 유한형입니다.','Great... another day of learning about nondeterministic finite automata.','좋습니다... 비결정론적 유한 오토마타에 대해 배우는 또 다른 날입니다.','published'),
('grade3-07:fluctuation','grade3-07:fluctuation','grade3','grade3-07','fluctuation','변동','noun','Experts say the absence of early warning systems increases the effects of climate fluctuation on the poor.','전문가들은 조기 경보 시스템의 부재로 인해 기후 변동이 가난한 사람들에게 미치는 영향이 증가한다고 말합니다.','The fluctuation changed the course of the day.','그 변동이 하루의 흐름을 바꾸었습니다.','published'),
('grade3-08:forestall','grade3-08:forestall','grade3','grade3-08','forestall','미연에 방지하다','verb','Early treatment may forestall serious complications.','조기 치료를 통해 심각한 합병증을 예방할 수 있습니다.','The company lowered prices to forestall a decline in sales.','회사는 매출 감소를 막기 위해 가격을 낮췄다.','published'),
('grade3-08:foster','grade3-08:foster','grade3','grade3-08','foster','촉진하다;양육하다','verb','We believe that large, publicly available voice datasets will foster innovation and healthy commercial competition in machine-learning based speech technology.','우리는 공개적으로 사용 가능한 대규모 음성 데이터 세트가 기계 학습 기반 음성 기술의 혁신과 건전한 상업적 경쟁을 촉진할 것이라고 믿습니다.','There are far more children in foster care than there are potential adopters.','잠재적 입양자 수보다 위탁 보호를 받는 아이들이 훨씬 더 많습니다.','published'),
('grade3-08:friction','grade3-08:friction','grade3','grade3-08','friction','마찰','noun','The friction that occurs during the violent vaporization process generates the flare.','격렬한 기화 과정에서 발생하는 마찰로 인해 플레어가 발생합니다.','I''m worried it could create friction between us.','우리 사이에 마찰이 생길까봐 걱정됩니다.','published'),
('grade3-08:frugal','grade3-08:frugal','grade3','grade3-08','frugal','검소한','adjective','Tom is a very frugal person.','톰은 아주 검소한 사람이야.','The student felt frugal before the presentation.','그 학생은 발표 전에 검소함을 느꼈습니다.','published'),
('grade3-08:futility','grade3-08:futility','grade3','grade3-08','futility','무익함','noun','His taking the bar exam for a third time was pure futility.','그가 세 번째 변호사 시험에 응시한 것은 그야말로 헛수고였다.','The report clearly described the futility.','보고서는 무익함을 명확하게 설명했습니다.','published'),
('grade3-08:genetic','grade3-08:genetic','grade3','grade3-08','genetic','유전적인','adjective','Genetic history reconstructs the origins of a literary work.','유전사는 문학 작품의 기원을 재구성합니다.','People with a given skin color do not form a genetic clade.','특정 피부색을 가진 사람들은 유전적 계통을 형성하지 않습니다.','published'),
('grade3-08:genre','grade3-08:genre','grade3','grade3-08','genre','장르','noun','Eventually, the genre became stagnant.','결국 장르는 정체됐다.','Rock is the most self-obsessed genre.','록은 가장 자기 집착적인 장르이다.','published'),
('grade3-08:gratify','grade3-08:gratify','grade3','grade3-08','gratify','기쁘게 하다','verb','The positive response will gratify everyone who worked on the project.','긍정적인 반응은 프로젝트에 참여한 모든 사람을 만족시킬 것입니다.','It will gratify her to see the students succeed.','학생들이 성공하는 것을 보면 그녀는 기뻐할 것입니다.','published'),
('grade3-08:grim','grade3-08:grim','grade3','grade3-08','grim','암울한','adjective','The grim task of burying the victims.','희생자들을 매장하는 암울한 임무.','A grim man loving duty more than humanity.','인간성보다 의무를 더 사랑하는 냉철한 남자.','published'),
('grade3-08:haphazard','grade3-08:haphazard','grade3','grade3-08','haphazard','무계획적인','adjective','A most haphazard system of record keeping.','가장 위험한 기록 보관 시스템입니다.','Do not make such haphazard changes to the settings; instead, adjust the knobs carefully, a bit at a time.','설정을 함부로 변경하지 마십시오. 대신 손잡이를 한 번에 조금씩 조심스럽게 조정하십시오.','published'),
('grade3-08:harsh','grade3-08:harsh','grade3','grade3-08','harsh','가혹한','adjective','The harsh white light makes you screw up your eyes.','가혹한 백색광은 눈을 망치게 만듭니다.','The harsh weather exacerbated his illness.','혹독한 날씨가 그의 병을 악화시켰다.','published'),
('grade3-08:hegemony','grade3-08:hegemony','grade3','grade3-08','hegemony','패권','noun','The hegemony of a single member state is not incompatible with a genuine confederation.','단일 회원국의 헤게모니는 진정한 연방과 양립할 수 없습니다.','To say they have priority is not to say they have complete hegemony.','그들이 우선권을 가지고 있다고 말하는 것은 그들이 완전한 헤게모니를 가지고 있다고 말하는 것이 아닙니다.','published'),
('grade3-08:heuristic','grade3-08:heuristic','grade3','grade3-08','heuristic','발견법의','adjective','I don''t think that heuristic will work.','나는 휴리스틱이 작동하지 않을 것이라고 생각합니다.','The final decision seemed heuristic to everyone involved.','최종 결정은 관련된 모든 사람에게 경험적 방법으로 보였습니다.','published'),
('grade3-08:homogeneous','grade3-08:homogeneous','grade3','grade3-08','homogeneous','동질적인','adjective','It''s a heterogeneous group, not a homogeneous one.','동질적인 그룹이 아닌 이질적인 그룹입니다.','The reviewers considered the final result homogeneous.','검토자는 최종 결과가 동질적이라고 생각했습니다.','published'),
('grade3-08:humble','grade3-08:humble','grade3','grade3-08','humble','겸손한','adjective','Essentially humble...and self-effacing, he achieved the highest formal honors and distinctions.','본질적으로 겸손하고... 자기를 드러내지 않는 그는 최고의 공식적인 영예와 영예를 얻었습니다.','I think I am actually humble. I think I''m much more humble than you would understand.','저는 사실 겸손한 편인 것 같아요. 나는 당신이 이해하는 것보다 훨씬 더 겸손하다고 생각합니다.','published'),
('grade3-08:hypothetical','grade3-08:hypothetical','grade3','grade3-08','hypothetical','가설의','adjective','The force carriers for gravity are hypothetical things called gravitons, for electromagnetism they''re the photons.','중력에 대한 힘 운반체는 중력자라고 불리는 가상의 것이며, 전자기학에서는 광자입니다.','The final decision seemed hypothetical to everyone involved.','최종 결정은 관련된 모든 사람에게 가상적인 것처럼 보였습니다.','published'),
('grade3-08:ideology','grade3-08:ideology','grade3','grade3-08','ideology','이념','noun','A dictatorship, in order to secure its reign, bans things that do not conform to its ideology.','독재정권은 자신의 통치를 보장하기 위해 자신의 이념에 부합하지 않는 것을 금지합니다.','No one who describes "postmodernism" as an ideology should ever be taken seriously about anything.','"포스트모더니즘"을 하나의 이념으로 묘사하는 사람은 어떤 일에든 진지하게 받아들여져서는 안 됩니다.','published'),
('grade3-08:illicit','grade3-08:illicit','grade3','grade3-08','illicit','불법적인','adjective','Critics say the pill could be diverted to illicit use and could worsen the country''s opioid crisis.','비평가들은 이 알약이 불법 사용으로 전환될 수 있으며 국가의 오피오이드 위기를 악화시킬 수 있다고 말합니다.','The final decision seemed illicit to everyone involved.','최종 결정은 관련된 모든 사람에게 불법으로 보였습니다.','published'),
('grade3-08:immune','grade3-08:immune','grade3','grade3-08','immune','면역의','adjective','As a diplomat, you are immune from prosecution.','외교관으로서 당신은 기소로부터 면제됩니다.','I am immune to chicken pox.','나는 수두에 면역이다.','published'),
('grade3-08:impartiality','grade3-08:impartiality','grade3','grade3-08','impartiality','공정성','noun','Judges must maintain impartiality throughout a trial.','판사는 재판 내내 공정성을 유지해야 합니다.','Her impartiality allowed both sides to trust the decision.','그녀의 공정성 덕분에 양측은 결정을 신뢰할 수 있었습니다.','published'),
('grade3-09:imperative','grade3-09:imperative','grade3','grade3-09','imperative','필수적인;명령적인','adjective','As nuclear weapons proliferate, preventing war becomes imperative.','핵무기가 확산되면서 전쟁을 예방하는 것이 필수가 되었습니다.','Requests that grew more and more imperative.','점점 더 긴급해지는 요청.','published'),
('grade3-09:impetus','grade3-09:impetus','grade3','grade3-09','impetus','추진력','noun','The discovery gave new impetus to the research project.','이 발견은 연구 프로젝트에 새로운 자극을 주었습니다.','Public concern provided the impetus for environmental reform.','대중의 관심은 환경 개혁의 원동력이 되었습니다.','published'),
('grade3-09:inadequate','grade3-09:inadequate','grade3','grade3-09','inadequate','불충분한','adjective','The available evidence is inadequate to support the claim.','이용 가능한 증거는 주장을 뒷받침하기에 충분하지 않습니다.','The shelter was inadequate for such a severe storm.','그런 심한 폭풍에는 대피소가 부족했습니다.','published'),
('grade3-09:inaugurate','grade3-09:inaugurate','grade3','grade3-09','inaugurate','취임시키다;개시하다','verb','The city will inaugurate the new subway line next week.','시는 다음 주에 새로운 지하철 노선을 개통할 예정이다.','The ceremony will inaugurate the president''s new term.','이번 행사에서는 대통령의 새 임기가 시작됩니다.','published'),
('grade3-09:inclination','grade3-09:inclination','grade3','grade3-09','inclination','성향','noun','He had an inclination to give up too easily.','그는 너무 쉽게 포기하려는 경향이 있었습니다.','Her inclination is for classical music.','그녀의 성향은 클래식 음악이다.','published'),
('grade3-09:incongruous','grade3-09:incongruous','grade3','grade3-09','incongruous','어울리지 않는','adjective','A joke that was incongruous with polite conversation.','예의바른 대화와 어울리지 않는 농담.','The reviewers considered the final result incongruous.','검토자들은 최종 결과가 부적절하다고 생각했습니다.','published'),
('grade3-09:indifference','grade3-09:indifference','grade3','grade3-09','indifference','무관심','noun','Public indifference allowed the problem to continue.','대중의 무관심으로 인해 문제가 계속되었습니다.','Her indifference to the result surprised the team.','결과에 대한 그녀의 무관심은 팀을 놀라게 했습니다.','published'),
('grade3-09:indignation','grade3-09:indignation','grade3','grade3-09','indignation','분노','noun','The sensitive mind recoils with indignation, disgust, and horror from the picture presented.','예민한 마음은 제시된 그림에 대한 분노, 혐오감, 공포로 움츠러들게 됩니다.','His indignation became clear during the conversation.','그의 분노는 대화 중에 분명해졌습니다.','published'),
('grade3-09:induce','grade3-09:induce','grade3','grade3-09','induce','유도하다','verb','No coaxing could induce them to advance, and the application of the whip only seemed to exasperate their obstinacy.','어떤 달래도 그들을 앞으로 나아가도록 유도할 수 없었으며, 채찍을 사용하는 것은 그들의 완고함을 더욱 격화시키는 것처럼 보였습니다.','The students were asked to induce something important.','학생들은 중요한 것을 유도해 달라는 요청을 받았습니다.','published'),
('grade3-09:inertia','grade3-09:inertia','grade3','grade3-09','inertia','관성','noun','He had to overcome his inertia and get back to work.','그는 관성을 극복하고 다시 일을 시작해야 했습니다.','Her inertia helped the team solve the problem.','그녀의 관성은 팀이 문제를 해결하는 데 도움이 되었습니다.','published'),
('grade3-09:inflexible','grade3-09:inflexible','grade3','grade3-09','inflexible','융통성 없는','adjective','An inflexible schedule can create unnecessary stress.','유연하지 못한 일정은 불필요한 스트레스를 유발할 수 있습니다.','The manager remained inflexible despite reasonable objections.','관리자는 합리적인 반대에도 불구하고 경직된 자세를 유지했습니다.','published'),
('grade3-09:inhibit','grade3-09:inhibit','grade3','grade3-09','inhibit','억제하다','verb','Fear can inhibit creative thinking.','두려움은 창의적인 사고를 방해할 수 있습니다.','The medicine may inhibit the growth of bacteria.','약은 박테리아의 성장을 억제할 수 있습니다.','published'),
('grade3-09:injustice','grade3-09:injustice','grade3','grade3-09','injustice','부당함','noun','The BMJ editorial describes oppression against women and girls as a great injustice that is insidious, systematic and widespread.','BMJ 사설은 여성과 소녀에 대한 억압을 교활하고 체계적이며 널리 퍼져 있는 큰 불의로 묘사합니다.','The injustice required careful planning.','불의에는 신중한 계획이 필요했습니다.','published'),
('grade3-09:innovative','grade3-09:innovative','grade3','grade3-09','innovative','혁신적인','adjective','These people are working on the goals in innovative ways.','이 사람들은 혁신적인 방식으로 목표를 달성하기 위해 노력하고 있습니다.','They collaborate to create innovative solutions.','그들은 혁신적인 솔루션을 만들기 위해 협력합니다.','published'),
('grade3-09:insignificant','grade3-09:insignificant','grade3','grade3-09','insignificant','하찮은','adjective','My country''s enemies are weak, insignificant, and dangerous.','내 나라의 적들은 약하고, 하찮고, 위험합니다.','The reviewers considered the final result insignificant.','검토자들은 최종 결과가 중요하지 않다고 생각했습니다.','published'),
('grade3-09:instability','grade3-09:instability','grade3','grade3-09','instability','불안정','noun','Political instability discouraged foreign investment.','정치적 불안정으로 인해 외국인 투자가 위축되었습니다.','The bridge was closed because of structural instability.','구조적 불안정으로 인해 다리가 폐쇄되었습니다.','published'),
('grade3-09:insurmountable','grade3-09:insurmountable','grade3','grade3-09','insurmountable','극복할 수 없는','adjective','Getting everybody to agree proved to be an insurmountable difficulty.','모든 사람의 동의를 얻는 것은 극복할 수 없는 어려움이었습니다.','The final decision seemed insurmountable to everyone involved.','최종 결정은 관련된 모든 사람에게 극복할 수 없는 것처럼 보였습니다.','published'),
('grade3-09:integral','grade3-09:integral','grade3','grade3-09','integral','필수적인','adjective','Trust is an integral part of a strong relationship.','신뢰는 강력한 관계의 필수적인 부분입니다.','Regular practice is integral to learning a language.','정기적인 연습은 언어 학습에 필수적입니다.','published'),
('grade3-09:intelligible','grade3-09:intelligible','grade3','grade3-09','intelligible','이해할 수 있는','adjective','Are the languages mutually intelligible?','언어는 서로 이해할 수 있습니까?','As an equation it presents nothing antinomic; it is absolute and immutable like every law, and, like every law, very intelligible.','방정식으로서 그것은 이율배반적인 것을 나타내지 않습니다. 그것은 모든 법칙과 마찬가지로 절대적이고 불변하며, 모든 법칙과 마찬가지로 매우 이해하기 쉽습니다.','published'),
('grade3-09:interdisciplinary','grade3-09:interdisciplinary','grade3','grade3-09','interdisciplinary','학제 간의','adjective','This journal is interdisciplinary: it has articles on everything from biology to electrical engineering.','이 저널은 학제간 저널입니다. 생물학부터 전기공학까지 모든 분야에 대한 기사를 담고 있습니다.','The interdisciplinary co-operation at this university is very impressive.','이 대학의 학제간 협력은 매우 인상적입니다.','published'),
('grade3-10:intervention','grade3-10:intervention','grade3','grade3-10','intervention','개입','noun','It occurs without human intervention.','이는 사람의 개입 없이 발생합니다.','The purpose of intervention is to prevent unnecessary duplication of lawsuits.','개입의 목적은 불필요한 소송의 중복을 방지하는 것입니다.','published'),
('grade3-10:intrinsic','grade3-10:intrinsic','grade3','grade3-10','intrinsic','본질적인','adjective','Form was treated as something intrinsic, as the very essence of the thing.','형태는 사물의 본질인 본질적인 것으로 취급되었습니다.','I question the intrinsic value of nihilism.','나는 허무주의의 본질적인 가치에 의문을 제기합니다.','published'),
('grade3-10:invalidate','grade3-10:invalidate','grade3','grade3-10','invalidate','무효화하다','verb','The final outcome will also depend on investigations into alleged election fraud, which some candidates say should invalidate the voting.','최종 결과는 또한 선거 부정 혐의에 대한 조사에 달려 있을 것이며, 일부 후보자들은 투표를 무효화해야 한다고 말합니다.','The team may invalidate the proposal after careful review.','팀은 신중한 검토 후 제안을 무효화할 수 있습니다.','published'),
('grade3-10:invoke','grade3-10:invoke','grade3','grade3-10','invoke','불러내다;호소하다','verb','I invoke my right to remain silent.','나는 묵비권을 행사할 권리를 원합니다.','The students were asked to invoke something important.','학생들은 중요한 것을 불러오라는 요청을 받았습니다.','published'),
('grade3-10:irreconcilable','grade3-10:irreconcilable','grade3','grade3-10','irreconcilable','양립할 수 없는','adjective','The two accounts contain irreconcilable differences.','두 계정에는 화해할 수 없는 차이가 있습니다.','Their goals appeared irreconcilable after the final meeting.','그들의 목표는 최종 회의 이후 양립할 수 없는 것처럼 보였습니다.','published'),
('grade3-10:irrelevant','grade3-10:irrelevant','grade3','grade3-10','irrelevant','무관한','adjective','If the economy is doing well and the people aren''t, the economy is irrelevant.','경제가 잘 되는데 국민이 안 되면 경제는 별 의미가 없다.','Whatever meaning the larger universe may have would be irrelevant to our tiny little lives on this rock.','더 큰 우주가 어떤 의미를 갖고 있든 이 바위 위에 있는 우리의 작은 생명과는 무관할 것입니다.','published'),
('grade3-10:jeopardize','grade3-10:jeopardize','grade3','grade3-10','jeopardize','위태롭게 하다','verb','This could jeopardize the whole operation.','이로 인해 전체 작업이 위태로워질 수 있습니다.','The change could jeopardize many students.','이러한 변화는 많은 학생들을 위험에 빠뜨릴 수 있습니다.','published'),
('grade3-10:jurisdiction','grade3-10:jurisdiction','grade3','grade3-10','jurisdiction','관할권','noun','Courts having jurisdiction in this district.','이 지역을 관할하는 법원입니다.','Universal jurisdiction holds that some crimes are so heinous they transcend any one nation and can be tried anywhere.','보편적 관할권은 일부 범죄가 너무 극악해서 어느 한 국가를 초월하며 어디에서나 재판을 받을 수 있다고 주장합니다.','published'),
('grade3-10:legitimacy','grade3-10:legitimacy','grade3','grade3-10','legitimacy','정당성','noun','Domestic foes argue the so-called unity government lacks legitimacy and has been foisted on the country by foreign powers.','국내 적들은 소위 통합 정부가 정당성이 부족하고 외국 세력에 의해 국가에 떠맡겨졌다고 주장합니다.','Her legitimacy helped the team solve the problem.','그녀의 정당성은 팀이 문제를 해결하는 데 도움이 되었습니다.','published'),
('grade3-10:leverage','grade3-10:leverage','grade3','grade3-10','leverage','지렛대 효과;활용하다','noun','Relatively small groups can sometimes exert immense political leverage.','상대적으로 작은 그룹이 때때로 엄청난 정치적 영향력을 행사할 수 있습니다.','A crowbar uses leverage to pry nails out of wood.','지렛대는 지렛대를 사용하여 나무에서 못을 들어냅니다.','published'),
('grade3-10:liberation','grade3-10:liberation','grade3','grade3-10','liberation','해방','noun','She worked for women''s liberation.','그녀는 여성 해방을 위해 일했습니다.','The team completed the liberation before the deadline.','팀은 마감일 이전에 해방을 완료했습니다.','published'),
('grade3-10:lucrative','grade3-10:lucrative','grade3','grade3-10','lucrative','수익성이 좋은','adjective','Tom became convinced that mining guano would be a lucrative business venture.','Tom은 구아노 채굴이 수익성 있는 사업이 될 것이라고 확신하게 되었습니다.','Computer programming was devalued as a women''s job until it became lucrative, at which point women were sidelined.','컴퓨터 프로그래밍은 수익성이 높아질 때까지 여성의 직업으로 평가절하되었으며, 그 시점에서 여성은 소외되었습니다.','published'),
('grade3-10:manifest','grade3-10:manifest','grade3','grade3-10','manifest','명백한;드러내다','adjective','The benefits of regular exercise soon became manifest.','규칙적인 운동의 이점은 곧 명백해졌습니다.','A clear pattern is manifest in the collected data.','수집된 데이터에는 명확한 패턴이 나타납니다.','published'),
('grade3-10:marginal','grade3-10:marginal','grade3','grade3-10','marginal','미미한;주변의','adjective','In recent years there has been an increase in violence against marginal groups.','최근 몇 년 동안 소외 계층에 대한 폭력이 증가했습니다.','The final decision seemed marginal to everyone involved.','최종 결정은 관련된 모든 사람에게 미미한 것으로 보였습니다.','published'),
('grade3-10:mediocrity','grade3-10:mediocrity','grade3','grade3-10','mediocrity','평범함','noun','Here we are in the reign of mediocrity!','여기 우리는 평범함의 시대에 있습니다!','This is the reign of mediocrity!','이것은 평범함의 통치입니다!','published'),
('grade3-10:methodology','grade3-10:methodology','grade3','grade3-10','methodology','방법론','noun','Do you understand the methodology?','방법론을 이해하고 있나요?','Her methodology changed after she reviewed the evidence.','증거를 검토한 후 그녀의 방법론이 바뀌었습니다.','published'),
('grade3-10:milestone','grade3-10:milestone','grade3','grade3-10','milestone','중요한 이정표','noun','Graduation is an important milestone in a student''s life.','졸업은 학생의 인생에서 중요한 이정표입니다.','The team celebrated a major milestone in the project.','팀은 프로젝트의 중요한 이정표를 축하했습니다.','published'),
('grade3-10:misinterpret','grade3-10:misinterpret','grade3','grade3-10','misinterpret','잘못 해석하다','verb','Don''t misinterpret my comments as criticism.','내 의견을 비판으로 오해하지 마십시오.','I tend to misinterpret things.','나는 사물을 잘못 해석하는 경향이 있습니다.','published'),
('grade3-10:mobilize','grade3-10:mobilize','grade3','grade3-10','mobilize','동원하다','verb','The campaign hopes to mobilize young voters.','이 캠페인은 젊은 유권자들을 동원하기를 희망합니다.','Emergency officials quickly mobilize resources after a disaster.','재난 발생 후 긴급구조 담당자는 신속하게 자원을 동원합니다.','published'),
('grade3-10:momentum','grade3-10:momentum','grade3','grade3-10','momentum','추진력','noun','The car''s momentum carried it off the road.','자동차의 추진력이 도로를 벗어났습니다.','The momentum of the particles was deduced from meteoritic velocities.','입자의 운동량은 운석의 속도로부터 추론되었습니다.','published'),
('grade3-11:moratorium','grade3-11:moratorium','grade3','grade3-11','moratorium','일시 중지','noun','Canada may put a moratorium on cloning for research.','캐나다는 연구용 복제를 유예할 수도 있습니다.','They used the moratorium to prepare for the test.','그들은 시험 준비를 위해 모라토리엄을 사용했습니다.','published'),
('grade3-11:multifaceted','grade3-11:multifaceted','grade3','grade3-11','multifaceted','다면적인','adjective','Tom is a multifaceted player.','Tom은 다재다능한 플레이어입니다.','Tom said it was a complex and multifaceted problem.','Tom은 이것이 복잡하고 다면적인 문제라고 말했습니다.','published'),
('grade3-11:mutate','grade3-11:mutate','grade3','grade3-11','mutate','돌연변이를 일으키다','verb','Some viruses can mutate rapidly over time.','일부 바이러스는 시간이 지남에 따라 빠르게 변이될 수 있습니다.','The gene may mutate when exposed to radiation.','방사선에 노출되면 유전자에 돌연변이가 발생할 수 있습니다.','published'),
('grade3-11:negligible','grade3-11:negligible','grade3','grade3-11','negligible','무시해도 될 정도의','adjective','We found errors, but their effects were negligible.','오류를 발견했지만 그 영향은 미미했습니다.','The final decision seemed negligible to everyone involved.','최종 결정은 관련된 모든 사람에게 사소한 것처럼 보였습니다.','published'),
('grade3-11:notable','grade3-11:notable','grade3','grade3-11','notable','주목할 만한','adjective','The city has made notable progress in reducing pollution.','이 도시는 오염을 줄이는 데 있어 눈에 띄는 진전을 이루었습니다.','One notable feature of the design is its low cost.','디자인의 주목할만한 특징 중 하나는 저렴한 비용입니다.','published'),
('grade3-11:nurture','grade3-11:nurture','grade3','grade3-11','nurture','기르다','verb','Identity is shaped by both nature and nurture.','정체성은 본성과 양육에 의해 형성됩니다.','How do you nurture yourself daily?','매일 어떻게 자신을 키우나요?','published'),
('grade3-11:obsess','grade3-11:obsess','grade3','grade3-11','obsess','사로잡다','verb','I probably shouldn''t obsess over my trauma.','트라우마에 집착하면 안 될 것 같아요.','But for sure, we obsess over the subject of work and how to do it better, faster, and more profitably.','그러나 확실히 우리는 작업 주제와 작업을 더 잘, 더 빠르게, 더 수익성 있게 수행하는 방법에 집착합니다.','published'),
('grade3-11:obsolete','grade3-11:obsolete','grade3','grade3-11','obsolete','구식의','adjective','Smartphones made many older devices obsolete.','스마트폰은 많은 오래된 장치를 쓸모없게 만들었습니다.','The factory replaced its obsolete equipment.','공장은 더 이상 사용되지 않는 장비를 교체했습니다.','published'),
('grade3-11:opaque','grade3-11:opaque','grade3','grade3-11','opaque','불투명한','adjective','The bathroom window is opaque for privacy.','욕실 창문은 프라이버시를 위해 불투명합니다.','The committee''s decision-making process remained opaque.','위원회의 의사결정 과정은 여전히 불투명했다.','published'),
('grade3-11:ordeal','grade3-11:ordeal','grade3','grade3-11','ordeal','시련','noun','The rescue ended a terrifying ordeal for the hikers.','구조로 등산객들에게 끔찍한 시련이 끝났습니다.','Recovering from the accident was a long ordeal.','사고에서 회복하는 것은 오랜 시련이었습니다.','published'),
('grade3-11:outdated','grade3-11:outdated','grade3','grade3-11','outdated','시대에 뒤떨어진','adjective','For these reasons, I particularly appreciate everyone''s patience as we debug the new information system that has replaced the outdated system.','이러한 이유로 구식 시스템을 대체하는 새로운 정보 시스템을 디버깅하는 동안 여러분의 인내심에 특히 감사드립니다.','The reviewers considered the final result outdated.','검토자는 최종 결과가 오래된 것으로 간주했습니다.','published'),
('grade3-11:overarching','grade3-11:overarching','grade3','grade3-11','overarching','포괄적인','adjective','The overarching goal is to improve student learning.','가장 중요한 목표는 학생들의 학습 능력을 향상시키는 것입니다.','An overarching theme connects all five chapters.','중요한 주제는 다섯 장을 모두 연결합니다.','published'),
('grade3-11:paradigm','grade3-11:paradigm','grade3','grade3-11','paradigm','사고의 틀','noun','He framed the problem within the psychoanalytic paradigm.','그는 정신분석적 패러다임 내에서 문제의 틀을 잡았습니다.','The study examined the paradigm in detail.','이 연구에서는 패러다임을 자세히 조사했습니다.','published'),
('grade3-11:paradoxical','grade3-11:paradoxical','grade3','grade3-11','paradoxical','역설적인','adjective','It is paradoxical that standing is more tiring than walking.','걷는 것보다 서 있는 것이 더 피곤하다는 것은 역설적이다.','The reviewers considered the final result paradoxical.','검토자들은 최종 결과가 역설적이라고 생각했습니다.','published'),
('grade3-11:patronize','grade3-11:patronize','grade3','grade3-11','patronize','후원하다;깔보다','verb','Local residents often patronize the small family restaurant.','지역 주민들은 종종 작은 패밀리 레스토랑을 애용합니다.','Do not patronize students by speaking to them like children.','아이들처럼 말하면서 학생들을 애용하지 마십시오.','published'),
('grade3-11:peripheral','grade3-11:peripheral','grade3','grade3-11','peripheral','주변의','adjective','Energy is far from a peripheral issue in the economy.','에너지는 경제의 주변적인 문제가 아닙니다.','The final decision seemed peripheral to everyone involved.','최종 결정은 관련된 모든 사람에게 주변적인 것처럼 보였습니다.','published'),
('grade3-11:perplex','grade3-11:perplex','grade3','grade3-11','perplex','당황하게 하다','verb','The unexpected result may perplex even experienced researchers.','예상치 못한 결과는 숙련된 연구자들조차 당혹스럽게 만들 수 있습니다.','The complicated instructions continue to perplex new users.','복잡한 지침은 계속해서 새로운 사용자를 당황하게 합니다.','published'),
('grade3-11:persuasion','grade3-11:persuasion','grade3','grade3-11','persuasion','설득','noun','I am not of your persuasion.','나는 당신의 설득력이 없습니다.','It is his persuasion that abortion should never be condoned.','낙태는 결코 용납되어서는 안 된다는 것이 그의 설득이다.','published'),
('grade3-11:pessimistic','grade3-11:pessimistic','grade3','grade3-11','pessimistic','비관적인','adjective','I think we should not be too pessimistic about some delays.','일부 지연에 대해 너무 비관해서는 안 된다고 생각합니다.','She remained pessimistic throughout the discussion.','그녀는 토론 내내 비관적인 태도를 유지했습니다.','published'),
('grade3-11:plausible','grade3-11:plausible','grade3','grade3-11','plausible','그럴듯한','adjective','The trick is to maintain plausible deniability.','비결은 그럴듯한 거부성을 유지하는 것입니다.','The reviewers considered the final result plausible.','검토자들은 최종 결과가 타당하다고 생각했습니다.','published'),
('grade3-12:polarize','grade3-12:polarize','grade3','grade3-12','polarize','양극화하다','verb','The issue may polarize public opinion.','이 문제는 여론을 양극화시킬 수 있다.','Extreme claims can polarize a classroom discussion.','극단적인 주장은 교실 토론을 양극화할 수 있습니다.','published'),
('grade3-12:precede','grade3-12:precede','grade3','grade3-12','precede','앞서다','verb','Stone tools precede bronze tools.','석기 도구는 청동 도구보다 우선합니다.','A small change could precede the entire process.','전체 프로세스에 앞서 작은 변화가 있을 수 있습니다.','published'),
('grade3-12:preclude','grade3-12:preclude','grade3','grade3-12','preclude','막다;불가능하게 하다','verb','It has been raining for days, but that doesn’t preclude the possibility that the skies will clear by this afternoon!','며칠 동안 비가 내렸지만, 그렇다고 해서 오늘 오후쯤에는 하늘이 맑아질 가능성이 배제되지는 않습니다!','That, of course, would effectively preclude the underlying tombs ever being investigated archaeologically.','물론 그것은 밑에 있는 무덤이 고고학적으로 조사되는 것을 사실상 불가능하게 만들 것입니다.','published'),
('grade3-12:predominant','grade3-12:predominant','grade3','grade3-12','predominant','지배적인','adjective','The predominant mood among policy-makers is optimism.','정책 입안자들의 주된 분위기는 낙관주의입니다.','The final decision seemed predominant to everyone involved.','최종 결정은 관련된 모든 사람에게 우세한 것처럼 보였습니다.','published'),
('grade3-12:premise','grade3-12:premise','grade3','grade3-12','premise','전제','noun','The argument begins with a false premise.','논쟁은 잘못된 전제에서 시작됩니다.','The story is built on an unusual premise.','이야기는 특이한 전제를 바탕으로 만들어졌습니다.','published'),
('grade3-12:presumption','grade3-12:presumption','grade3','grade3-12','presumption','추정','noun','The presumption is that an event has taken place.','이벤트가 발생했다고 합니다.','The class discussed the presumption from several viewpoints.','수업에서는 여러 관점에서 추정에 대해 논의했습니다.','published'),
('grade3-12:procrastinate','grade3-12:procrastinate','grade3','grade3-12','procrastinate','미루다','verb','Students who procrastinate often rush before a deadline.','미루는 학생들은 마감일을 앞두고 서두르는 경우가 많습니다.','Try not to procrastinate when an important task is due.','중요한 일이 마감되었을 때 미루지 마십시오.','published'),
('grade3-12:proliferate','grade3-12:proliferate','grade3','grade3-12','proliferate','급증하다','verb','Pizza parlors proliferate in this area.','이 지역에는 피자 가게가 급증하고 있습니다.','We must not proliferate nuclear arms.','우리는 핵무기를 확산시켜서는 안 됩니다.','published'),
('grade3-12:prominent','grade3-12:prominent','grade3','grade3-12','prominent','두드러진','adjective','A new theory is the most prominent feature of the book.','새로운 이론은 이 책의 가장 두드러진 특징이다.','There are several varieties of omelettes, each named after the ingredient prominent in the composition.','오믈렛에는 여러 종류가 있으며, 각 이름은 구성 요소에서 눈에 띄는 성분의 이름을 따서 명명되었습니다.','published'),
('grade3-12:propel','grade3-12:propel','grade3','grade3-12','propel','추진하다','verb','Strong winds can propel the boat across the lake.','강한 바람이 불면 보트가 호수를 가로질러 나아갈 수 있습니다.','Her curiosity helped propel the research forward.','그녀의 호기심은 연구가 진행되는 데 도움이 되었습니다.','published'),
('grade3-12:prosecute','grade3-12:prosecute','grade3','grade3-12','prosecute','기소하다','verb','Tom declined to prosecute the person who stole from him, reasoning that the police and prison guards were far bigger criminals.','톰은 경찰과 교도관이 훨씬 더 큰 범죄자라고 생각하여 자신의 물건을 훔친 사람을 기소하는 것을 거부했습니다.','The students may prosecute after the announcement.','학생들은 발표 후 기소될 수 있습니다.','published'),
('grade3-12:provisional','grade3-12:provisional','grade3','grade3-12','provisional','임시의','adjective','The provisional presidential results show the ruling party garnered 60% of the vote, with 33% of the vote counted.','임시대통령 결과에 따르면 여당은 60%의 득표율을 기록했고, 33%의 득표율을 기록했다.','The final decision seemed provisional to everyone involved.','최종 결정은 관련된 모든 사람에게 잠정적인 것처럼 보였습니다.','published'),
('grade3-12:proximity','grade3-12:proximity','grade3','grade3-12','proximity','근접성','noun','The house''s proximity to school saves commuting time.','집이 학교와 가까워 통근 시간이 절약됩니다.','Plants competed for sunlight because of their close proximity.','식물은 서로 가깝기 때문에 햇빛을 두고 경쟁했습니다.','published'),
('grade3-12:quantify','grade3-12:quantify','grade3','grade3-12','quantify','수량화하다','verb','Can you quantify your results?','결과를 정량화할 수 있나요?','The team may quantify the proposal after careful review.','팀은 신중한 검토 후 제안을 정량화할 수 있습니다.','published'),
('grade3-12:quest','grade3-12:quest','grade3','grade3-12','quest','탐구','noun','The scientist began a quest for a better solution.','과학자는 더 나은 해결책을 찾기 시작했습니다.','Their quest for knowledge continued throughout the journey.','지식에 대한 그들의 탐구는 여행 내내 계속되었습니다.','published'),
('grade3-12:rationale','grade3-12:rationale','grade3','grade3-12','rationale','근거;이유','noun','The teacher explained the rationale behind the new rule.','교사는 새로운 규칙의 근거를 설명했습니다.','There is a clear economic rationale for the decision.','결정에는 분명한 경제적 근거가 있습니다.','published'),
('grade3-12:reconcile','grade3-12:reconcile','grade3','grade3-12','reconcile','화해시키다;조정하다','verb','It''s best not to try to reconcile the contradictions.','모순을 조정하려고 노력하지 않는 것이 가장 좋습니다.','The team may reconcile the proposal during the meeting.','팀은 회의 중에 제안을 조정할 수 있습니다.','published'),
('grade3-12:reconstruction','grade3-12:reconstruction','grade3','grade3-12','reconstruction','재건','noun','The reconstruction of the medieval bridge began last year.','중세 다리의 재건축은 작년에 시작되었습니다.','The detective''s reconstruction of what happened that night is dubious.','그날 밤 일어난 일에 대한 형사의 재구성은 의심스럽습니다.','published'),
('grade3-12:recurrence','grade3-12:recurrence','grade3','grade3-12','recurrence','재발','noun','Regular treatment can reduce the recurrence of symptoms.','정기적인 치료를 통해 증상의 재발을 줄일 수 있습니다.','The recurrence of the same error concerned the engineers.','동일한 오류가 반복되어 엔지니어가 우려했습니다.','published'),
('grade3-12:refrain','grade3-12:refrain','grade3','grade3-12','refrain','삼가다','verb','Jews refrain from proselytizing and even discourage others from converting.','유대인들은 전도하는 것을 삼가고 심지어 다른 사람들이 개종하는 것을 방해하기도 합니다.','To advance the international cause of human rights, we must first respect each other and refrain from politicizing human rights.','국제적인 인권 운동을 발전시키려면 먼저 서로를 존중하고 인권을 정치화하는 것을 삼가해야 합니다.','published'),
('grade3-13:refute','grade3-13:refute','grade3','grade3-13','refute','반박하다','verb','Do you have an objection to the source, or a relevant piece of evidence to refute the claim?','출처에 대한 이의가 있거나 주장을 반박할 수 있는 관련 증거가 있습니까?','It is much harder to refute a lie than to tell one.','거짓말을 하는 것보다 거짓말을 반박하는 것이 훨씬 더 어렵습니다.','published'),
('grade3-13:reimbursement','grade3-13:reimbursement','grade3','grade3-13','reimbursement','상환','noun','He received reimbursement for his travel expenses.','그는 여행 경비를 상환 받았습니다.','They protected the reimbursement carefully.','그들은 환급을 신중하게 보호했습니다.','published'),
('grade3-13:relativity','grade3-13:relativity','grade3','grade3-13','relativity','상대성','noun','Einstein transformed physics with his theory of relativity.','아인슈타인은 상대성 이론으로 물리학을 변화시켰습니다.','The course introduces students to the basic ideas of relativity.','이 과정은 학생들에게 상대성 이론의 기본 개념을 소개합니다.','published'),
('grade3-13:remedy','grade3-13:remedy','grade3','grade3-13','remedy','치료법;해결책','noun','Unless a drastic remedy is quickly found, these elements, I am convinced, are going to be the nation''s undoing.','과감한 해결책이 조속히 발견되지 않는 한, 이러한 요소들이 국가를 파멸로 몰고 갈 것이라고 나는 확신합니다.','The team completed the remedy before the deadline.','팀은 마감일 이전에 해결 방법을 완료했습니다.','published'),
('grade3-13:renowned','grade3-13:renowned','grade3','grade3-13','renowned','유명한','adjective','The population is renowned for its remarkable growth during the 20th century, following virtual annihilation by sealers in the 19th century.','인구는 19세기 바다표범에 의해 사실상 멸종된 이후 20세기 동안 눈에 띄게 증가한 것으로 유명합니다.','The reviewers considered the final result renowned.','검토자들은 최종 결과가 유명하다고 생각했습니다.','published'),
('grade3-13:replenish','grade3-13:replenish','grade3','grade3-13','replenish','보충하다','verb','It''s a popular product, and they have to replenish their stock of it frequently.','이는 인기 있는 제품이므로 재고를 자주 보충해야 합니다.','A military veteran shows how his compost business helps to replenish precious topsoil.','퇴역 군인이 자신의 퇴비 사업이 귀중한 표토를 보충하는 데 어떻게 도움이 되는지 보여줍니다.','published'),
('grade3-13:repress','grade3-13:repress','grade3','grade3-13','repress','억압하다','verb','To repress a vinyl record.','비닐 레코드를 억압합니다.','The report also discusses actions by governments and other groups to repress the news media.','보고서는 또한 뉴스 매체를 탄압하기 위한 정부 및 기타 단체의 조치에 대해서도 논의합니다.','published'),
('grade3-13:resilient','grade3-13:resilient','grade3','grade3-13','resilient','회복력 있는','adjective','People are very resilient in general.','사람들은 일반적으로 회복력이 매우 뛰어납니다.','They shine like the stars, resilient and bright.','그들은 별처럼 빛나고 탄력 있고 밝게 빛납니다.','published'),
('grade3-13:restrain','grade3-13:restrain','grade3','grade3-13','restrain','억제하다','verb','I resigned myself to restrain my feelings.','나는 내 감정을 억제하기 위해 사임했습니다.','I decided to restrain my heart.','나는 마음을 억제하기로 결정했습니다.','published'),
('grade3-13:resume','grade3-13:resume','grade3','grade3-13','resume','재개하다','verb','We will resume this discussion tomorrow at nine.','내일 9시에 이 논의를 재개하겠습니다.','I''ve made some changes to my resume.','이력서를 일부 수정했습니다.','published'),
('grade3-13:retrieve','grade3-13:retrieve','grade3','grade3-13','retrieve','되찾다','verb','Retrieve the car from the parking garage.','주차장에서 차를 회수하세요.','Train the dog to retrieve.','개가 회수하도록 훈련시키세요.','published'),
('grade3-13:revelation','grade3-13:revelation','grade3','grade3-13','revelation','폭로;계시','noun','It''s not a particularly brilliant revelation of mine.','그것은 나의 특별한 계시가 아닙니다.','Everyone discussed the revelation after class.','수업이 끝난 후 모두가 그 계시에 대해 토론했습니다.','published'),
('grade3-13:rigid','grade3-13:rigid','grade3','grade3-13','rigid','경직된','adjective','A table made of rigid plastic.','단단한 플라스틱으로 만든 테이블입니다.','Whereas the junction is more stiff or rigid, the nexus is more pliable; it is, as it were, animate or articulated.','접합부가 더 뻣뻣하거나 단단한 반면, 넥서스는 더 유연합니다. 말하자면 그것은 살아 움직이거나 표현되는 것입니다.','published'),
('grade3-13:robust','grade3-13:robust','grade3','grade3-13','robust','튼튼한','adjective','The experiment yielded robust results.','실험은 확실한 결과를 낳았습니다.','A robust wall was put up.','견고한 벽이 세워졌습니다.','published'),
('grade3-13:rupture','grade3-13:rupture','grade3','grade3-13','rupture','파열','noun','After extensively studying the quake and its aftermath, scientists say the rupture is unprecedented.','지진과 그 여파를 광범위하게 연구한 후, 과학자들은 이번 지진 파열은 전례 없는 일이라고 말했습니다.','The rupture lasted longer than expected.','파열은 예상보다 오래 지속됐다.','published'),
('grade3-13:sanction','grade3-13:sanction','grade3','grade3-13','sanction','제재;승인','noun','It had the sanction of the church.','교회의 승인을 받은 것이었습니다.','The sanction gave the students useful information.','이 제재는 학생들에게 유용한 정보를 제공했습니다.','published'),
('grade3-13:scrutiny','grade3-13:scrutiny','grade3','grade3-13','scrutiny','면밀한 조사','noun','The proposal came under close public scrutiny.','이 제안은 대중의 면밀한 조사를 받았습니다.','Scientific claims must withstand careful scrutiny.','과학적 주장은 면밀한 조사를 거쳐야 합니다.','published'),
('grade3-13:seclude','grade3-13:seclude','grade3','grade3-13','seclude','격리하다','verb','The writer chose to seclude herself in a quiet cabin.','작가는 조용한 오두막에 은둔하기로 결정했습니다.','The hospital may seclude a patient only when necessary for safety.','병원은 안전을 위해 필요한 경우에만 환자를 격리할 수 있습니다.','published'),
('grade3-13:selective','grade3-13:selective','grade3','grade3-13','selective','선택적인','adjective','The school was very selective in its admissions.','그 학교는 입학을 매우 선별적으로 진행했습니다.','The final decision seemed selective to everyone involved.','최종 결정은 관련된 모든 사람에게 선택적인 것처럼 보였습니다.','published'),
('grade3-13:setback','grade3-13:setback','grade3','grade3-13','setback','차질','noun','He sees opportunity in every setback.','그는 모든 좌절 속에서 기회를 봅니다.','Nobody expected the setback to happen so suddenly.','그 누구도 이렇게 갑자기 좌절이 일어날 것이라고는 예상하지 못했습니다.','published'),
('grade3-14:shrewd','grade3-14:shrewd','grade3','grade3-14','shrewd','영리한','adjective','He was too shrewd to go along with them on a road that could lead only to their overthrow.','그는 너무 영리해서 그들을 멸망시킬 수밖에 없는 길로 그들과 함께 갈 수 없었습니다.','The student felt shrewd before the presentation.','그 학생은 발표 전에 영리함을 느꼈습니다.','published'),
('grade3-14:skeptical','grade3-14:skeptical','grade3','grade3-14','skeptical','회의적인','adjective','There is a physical reality, but we must be skeptical of our knowledge of it.','물리적 현실이 있지만 우리는 그것에 대한 우리의 지식에 대해 회의적이어야 합니다.','James was skeptical about cisgenderism.','제임스는 시스젠더리즘에 대해 회의적이었습니다.','published'),
('grade3-14:solemn','grade3-14:solemn','grade3','grade3-14','solemn','엄숙한','adjective','The judge was solemn as he pronounced sentence.','판사는 엄숙하게 형을 선고했습니다.','But to-night the elderly servitor was solemn and unloquacious beyond his custom.','그러나 오늘 밤 나이든 하인은 평소와는 달리 엄숙하고 말수가 적었다.','published'),
('grade3-14:solitary','grade3-14:solitary','grade3','grade3-14','solitary','혼자의','adjective','It was a walk up a long, lonely road to a solitary thorn-tree, where I was studying a shrike''s nest.','그것은 내가 때까치 둥지를 연구하고 있던 고독한 가시나무까지 길고 외로운 길을 걸어가는 일이었습니다.','It was whilst suffering the agonies of solitary confinement in that military prison that I first decided to record my experiences.','내가 처음으로 내 경험을 기록하기로 결심한 것은 그 군 감옥에서 독방에 갇히는 고통을 겪으면서였다.','published'),
('grade3-14:speculation','grade3-14:speculation','grade3','grade3-14','speculation','추측','noun','He knew the stock was a speculation when he bought it.','그는 주식을 샀을 때 그 주식이 투기라는 것을 알았습니다.','Amid speculation that the party is headed for a schism, participants at the meeting resolved to maintain the party''s unity and integrity.','당이 분열로 향하고 있다는 관측이 나오는 가운데, 회의 참석자들은 당의 단결과 청렴을 유지하기로 결의했다.','published'),
('grade3-14:stagnant','grade3-14:stagnant','grade3','grade3-14','stagnant','정체된','adjective','Eventually, the genre became stagnant.','결국 장르는 정체됐다.','The final decision seemed stagnant to everyone involved.','관련된 모든 사람에게 최종 결정은 정체된 것처럼 보였습니다.','published'),
('grade3-14:stereotype','grade3-14:stereotype','grade3','grade3-14','stereotype','고정관념','noun','The film challenges a common cultural stereotype.','영화는 일반적인 문화적 고정관념에 도전한다.','We should not judge a person by a stereotype.','우리는 고정관념으로 사람을 판단해서는 안 됩니다.','published'),
('grade3-14:strenuous','grade3-14:strenuous','grade3','grade3-14','strenuous','힘든','adjective','The hikers rested after a strenuous climb.','등산객들은 힘든 등반을 마치고 휴식을 취하고 있다.','Strenuous exercise may not be suitable for every patient.','격렬한 운동은 모든 환자에게 적합하지 않을 수 있습니다.','published'),
('grade3-14:subdue','grade3-14:subdue','grade3','grade3-14','subdue','진압하다','verb','Firefighters struggled to subdue the spreading flames.','소방관들은 번지는 불길을 진압하기 위해 고군분투했습니다.','She took a deep breath to subdue her anger.','그녀는 분노를 가라앉히기 위해 심호흡을 했다.','published'),
('grade3-14:subordination','grade3-14:subordination','grade3','grade3-14','subordination','종속','noun','The policy reinforced the subordination of local offices to headquarters.','이 정책은 지역 사무소의 본사 종속을 강화했습니다.','The essay examines subordination within the social hierarchy.','이 에세이는 사회 계층 내의 종속을 조사합니다.','published'),
('grade3-14:substantiate','grade3-14:substantiate','grade3','grade3-14','substantiate','입증하다','verb','The president''s trip will substantiate good relations with the former enemy country.','대통령의 이번 순방은 옛 적국과의 좋은 관계를 입증하게 될 것이다.','The students were asked to substantiate something important.','학생들은 중요한 것을 입증하도록 요청 받았습니다.','published'),
('grade3-14:succession','grade3-14:succession','grade3','grade3-14','succession','연속;승계','noun','A succession of stalls offering soft drinks.','청량 음료를 판매하는 일련의 노점.','The managing director''s resignation is certain to touch off a fierce but gentlemanly succession struggle.','이번 전무이사의 사임은 신사적이지만 치열한 승계투쟁을 촉발할 것이 확실하다.','published'),
('grade3-14:succumb','grade3-14:succumb','grade3','grade3-14','succumb','굴복하다','verb','The small company refused to succumb to financial pressure.','소규모 회사는 재정적 압박에 굴복하지 않았습니다.','Untreated plants may succumb to the disease.','처리되지 않은 식물은 질병에 걸릴 수 있습니다.','published'),
('grade3-14:supersede','grade3-14:supersede','grade3','grade3-14','supersede','대체하다','verb','The new regulation will supersede the old rule.','새로운 규정은 기존 규정을 대체합니다.','New technology may supersede older methods in the future.','미래에는 새로운 기술이 기존 방법을 대체할 수도 있습니다.','published'),
('grade3-14:susceptibility','grade3-14:susceptibility','grade3','grade3-14','susceptibility','취약성','noun','Age can increase a person''s susceptibility to infection.','나이가 들면 감염에 대한 민감성이 높아질 수 있습니다.','The study measured each plant''s susceptibility to drought.','이 연구는 가뭄에 대한 각 식물의 민감성을 측정했습니다.','published'),
('grade3-14:suspend','grade3-14:suspend','grade3','grade3-14','suspend','중단하다','verb','Suspend the aid to the war-torn country.','전쟁으로 피폐해진 국가에 대한 지원을 중단하십시오.','To suspend one''s judgement or one''s disbelief.','자신의 판단이나 불신을 유예시키다.','published'),
('grade3-14:synthesis','grade3-14:synthesis','grade3','grade3-14','synthesis','종합','noun','The essay presents a synthesis of several competing theories.','이 에세이는 여러 경쟁 이론의 종합을 제시합니다.','Photosynthesis involves the synthesis of sugar from carbon dioxide and water.','광합성은 이산화탄소와 물로부터 당을 합성하는 과정을 포함합니다.','published'),
('grade3-14:tacit','grade3-14:tacit','grade3','grade3-14','tacit','암묵적인','adjective','Tacit consent : consent by silence, or by not raising an objection.','암묵적 동의 : 묵묵히 동의하거나 이의를 제기하지 않음으로써 동의하는 것.','The reviewers considered the final result tacit.','검토자들은 최종 결과가 암묵적이라고 생각했습니다.','published'),
('grade3-14:tangible','grade3-14:tangible','grade3','grade3-14','tangible','유형의;실질적인','adjective','The new policy produced tangible benefits for students.','새로운 정책은 학생들에게 실질적인 혜택을 제공했습니다.','The team needed tangible evidence to support the claim.','팀은 주장을 뒷받침할 실질적인 증거가 필요했습니다.','published'),
('grade3-14:tentative','grade3-14:tentative','grade3','grade3-14','tentative','잠정적인','adjective','We made a tentative plan for the weekend.','우리는 주말에 임시 계획을 세웠습니다.','The scientists reached a tentative conclusion based on limited evidence.','과학자들은 제한된 증거를 바탕으로 잠정적인 결론에 도달했습니다.','published'),
('grade3-15:threshold','grade3-15:threshold','grade3','grade3-15','threshold','문턱;한계점','noun','The noise level remained below the safety threshold.','소음 수준은 안전 기준치 미만으로 유지되었습니다.','She paused at the threshold before entering the room.','그녀는 방에 들어가기 전에 문지방에서 잠시 멈췄다.','published'),
('grade3-15:thwart','grade3-15:thwart','grade3','grade3-15','thwart','좌절시키다','verb','Tom thought he could thwart my plans.','톰은 내 계획을 방해할 수 있다고 생각했어요.','The students were asked to thwart something important.','학생들은 중요한 일을 저지해 달라는 요청을 받았습니다.','published'),
('grade3-15:trait','grade3-15:trait','grade3','grade3-15','trait','특성','noun','Kindness is the most beautiful trait a person can have.','친절은 사람이 가질 수 있는 가장 아름다운 특성입니다.','Her trait helped the team solve the problem.','그녀의 특성은 팀이 문제를 해결하는 데 도움이 되었습니다.','published'),
('grade3-15:transient','grade3-15:transient','grade3','grade3-15','transient','일시적인','adjective','Sculptures made of sand are transient, here today and gone tomorrow, subject to the whims of wind and waves.','모래로 만든 조각품은 바람과 파도의 변덕에 따라 오늘 여기 있다가 내일 사라지는 일시적인 것입니다.','The final decision seemed transient to everyone involved.','관련된 모든 사람에게 최종 결정은 일시적인 것처럼 보였습니다.','published'),
('grade3-15:transparent','grade3-15:transparent','grade3','grade3-15','transparent','투명한','adjective','Trump is transparent in the sense that he is a shameless hypocrite.','트럼프는 자신이 뻔뻔한 위선자라는 점에서 투명하다.','The caterpillars were so transparent that under a low magnifying power the nervous, tracheal, and alimentary systems could be beautifully seen.','애벌레는 너무 투명해서 낮은 배율에서도 신경계, 기관, 소화계가 아름답게 보입니다.','published'),
('grade3-15:turbulent','grade3-15:turbulent','grade3','grade3-15','turbulent','격동의','adjective','His wisdom is the anchor in turbulent seas.','그분의 지혜는 험난한 바다의 닻입니다.','The final decision seemed turbulent to everyone involved.','최종 결정은 관련된 모든 사람에게 격동적인 것처럼 보였습니다.','published'),
('grade3-15:unanimous','grade3-15:unanimous','grade3','grade3-15','unanimous','만장일치의','adjective','Mouths were too full for utterance but there was a unanimous bobbing of heads.','입이 너무 꽉 차서 말을 할 수 없었지만 만장일치로 머리가 흔들렸다.','The final decision seemed unanimous to everyone involved.','최종 결정은 관련된 모든 사람에게 만장일치로 보였습니다.','published'),
('grade3-15:uncanny','grade3-15:uncanny','grade3','grade3-15','uncanny','기묘한','adjective','Stumps...had uncanny shapes as of monstrous creatures.','그루터기는...괴물처럼 기괴한 모양을 하고 있었습니다.','The final decision seemed uncanny to everyone involved.','최종 결정은 관련된 모든 사람에게 기괴한 것처럼 보였습니다.','published'),
('grade3-15:undermine','grade3-15:undermine','grade3','grade3-15','undermine','약화시키다','verb','Constant criticism can undermine a student''s confidence.','끊임없는 비판은 학생의 자신감을 약화시킬 수 있습니다.','Weak evidence may undermine the main argument.','약한 증거는 주요 주장을 약화시킬 수 있습니다.','published'),
('grade3-15:unpredictable','grade3-15:unpredictable','grade3','grade3-15','unpredictable','예측 불가능한','adjective','The future is unpredictable but exciting.','미래는 예측할 수 없지만 흥미롭습니다.','The final decision seemed unpredictable to everyone involved.','최종 결정은 관련된 모든 사람에게 예측할 수 없는 것처럼 보였습니다.','published'),
('grade3-15:uphold','grade3-15:uphold','grade3','grade3-15','uphold','지지하다;유지하다','verb','Courts must uphold the rights guaranteed by law.','법원은 법이 보장하는 권리를 옹호해야 합니다.','The committee voted to uphold the original decision.','위원회는 원래 결정을 유지하기로 투표했습니다.','published'),
('grade3-15:vagueness','grade3-15:vagueness','grade3','grade3-15','vagueness','모호함','noun','These terms were used with a vagueness that suggested little or no thought about what each might convey.','이러한 용어는 각각이 전달할 내용에 대해 거의 또는 전혀 생각하지 못하게 하는 모호하게 사용되었습니다.','The report clearly described the vagueness.','보고서는 모호함을 명확하게 설명했습니다.','published'),
('grade3-15:vanish','grade3-15:vanish','grade3','grade3-15','vanish','사라지다','verb','Our enemies will vanish like dew in the sun.','우리의 적들은 해의 이슬처럼 사라질 것입니다.','The situation may vanish without warning.','상황은 예고 없이 사라질 수도 있습니다.','published'),
('grade3-15:veneration','grade3-15:veneration','grade3','grade3-15','veneration','존경','noun','His respect for the law bordered on veneration.','법에 대한 그의 존경심은 숭배에 가까웠습니다.','She expressed her veneration honestly.','그녀는 존경심을 솔직하게 표현했습니다.','published'),
('grade3-15:viable','grade3-15:viable','grade3','grade3-15','viable','실행 가능한','adjective','Despite the piles of investment money thrown at the project, the company has yet to come out with a viable product.','프로젝트에 쏟아부은 막대한 투자에도 불구하고 회사는 아직 실행 가능한 제품을 내놓지 못했습니다.','A fetus is merely a part of the pregnant person''s body until it is viable.','태아는 생존할 수 있을 때까지 임신한 사람의 신체 일부일 뿐입니다.','published'),
('grade3-15:vindicate','grade3-15:vindicate','grade3','grade3-15','vindicate','정당성을 입증하다','verb','Vindicate the rights of the citizens.','시민의 권리를 옹호해주세요.','You must vindicate yourself and fight this libel.','당신은 자신을 변호하고 이 명예훼손에 맞서 싸워야 합니다.','published'),
('grade3-15:vivid','grade3-15:vivid','grade3','grade3-15','vivid','생생한','adjective','Oh, to lose her now; now that her love and her reason had both returned, each more vivid than before!','아, 이제 그녀를 잃게 되다니; 이제 그녀의 사랑과 이성은 모두 이전보다 더 생생하게 돌아왔습니다!','The final decision seemed vivid to everyone involved.','최종 결정은 관련된 모든 사람에게 생생하게 보였습니다.','published'),
('grade3-15:wane','grade3-15:wane','grade3','grade3-15','wane','약해지다','verb','Public interest began to wane after several months.','몇 달이 지나자 대중의 관심이 줄어들기 시작했습니다.','Her anxiety started to wane as she gained experience.','그녀의 불안은 경험이 쌓이면서 줄어들기 시작했습니다.','published'),
('grade3-15:wholesome','grade3-15:wholesome','grade3','grade3-15','wholesome','건전한','adjective','Tom is the most wholesome person you''ll ever meet.','톰은 당신이 만날 수 있는 가장 건전한 사람입니다.','The reviewers considered the final result wholesome.','검토자들은 최종 결과가 건전하다고 생각했습니다.','published'),
('grade3-15:yield','grade3-15:yield','grade3','grade3-15','yield','산출하다;양보하다','verb','We should plant aplenty of cherry and small fruit trees to yield feed for birds.','우리는 새들에게 먹이를 주기 위해 벚나무와 작은 과일나무를 많이 심어야 합니다.','A cultivar is a plant deliberately selected for its characteristics, such as color, crop yield or disease resistance.','품종은 색상, 작물 수확량 또는 질병 저항성과 같은 특성을 위해 의도적으로 선택된 식물입니다.','published')
